INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/gpu', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'gpu', 0, 0, 70, '2026-02-18T01:08:43.394Z', '2026-02-18T02:08:16.214Z', NULL, '{"id":"majiayu000/claude-skill-registry/gpu","name":"gpu","description":{"es":"El monitoreo de GPU para Ollama permite verificar el estado de la GPU, el uso de VRAM y los modelos cargados en la memoria de la GPU","fr":"La surveillance de la GPU pour Ollama permet de vérifier l''état de la GPU, l''utilisation de la VRAM et les modèles chargés dans la mémoire de la GPU","de":"Die GPU-Überwachung für Ollama ermöglicht die Überprüfung des GPU-Status, der VRAM-Nutzung und der in der GPU-Speicher geladenen Modelle","pt":"O monitoramento de GPU para Ollama permite verificar o status da GPU, uso de VRAM e métricas de inferência","ru":"Мониторинг GPU для Ollama позволяет проверить статус GPU, использование VRAM и метрики вывода","ar":"مراقبة GPU لـ Ollama تمكنك من التحقق من حالة GPU واستخدام VRAM وقياسات الاستدلال","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"es":"Monitoreo de GPU para Ollama","fr":"Surveillance de la GPU pour Ollama","de":"GPU-Überwachung für Ollama","pt":"Monitoramento de GPU para Ollama","ru":"Мониторинг GPU для Ollama","ar":"مراقبة GPU لـ Ollama","en":"gpu"},"description":{"es":"El monitoreo de GPU para Ollama permite verificar el estado de la GPU, el uso de VRAM y los modelos cargados en la memoria de la GPU","fr":"La surveillance de la GPU pour Ollama permet de vérifier l''état de la GPU, l''utilisation de la VRAM et les modèles chargés dans la mémoire de la GPU","de":"Die GPU-Überwachung für Ollama ermöglicht die Überprüfung des GPU-Status, der VRAM-Nutzung und der in der GPU-Speicher geladenen Modelle","pt":"O monitoramento de GPU para Ollama permite verificar o status da GPU, uso de VRAM e métricas de inferência","ru":"Мониторинг GPU для Ollama позволяет проверить статус GPU, использование VRAM и метрики вывода","ar":"مراقبة GPU لـ Ollama تمكنك من التحقق من حالة GPU واستخدام VRAM وقياسات الاستدلال","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"es":["Verificación del estado de la GPU","Monitoreo del uso de VRAM","Verificación de los modelos cargados en la memoria de la GPU","Monitoreo de los métricos de inferencia","Compatibilidad con NVIDIA y ROCm"],"fr":["Vérification de l''état de la GPU","Surveillance de l''utilisation de la VRAM","Vérification des modèles chargés dans la mémoire de la GPU","Surveillance des métriques d''inférence","Compatibilité avec NVIDIA et ROCm"],"de":["Überprüfung des GPU-Status","Überwachung der VRAM-Nutzung","Überprüfung der in der GPU-Speicher geladenen Modelle","Überwachung der Inferenzmetriken","Kompatibilität mit NVIDIA und ROCm"],"pt":["Verificação do status da GPU","Monitoramento do uso de VRAM","Verificação de modelos carregados na memória da GPU","Métricas de inferência","Suporte a NVIDIA e ROCm"],"ru":["Проверка состояния GPU","Мониторинг использования VRAM","Проверка моделей, загруженных в память GPU","Метрики вывода","Поддержка NVIDIA и ROCm"],"ar":["التحقق من حالة GPU","مراقبة استخدام VRAM","التحقق من النماذج المحملة في ذاكرة GPU","قياسات الاستدلال","دعم NVIDIA و ROCm"]},"keywords":{"es":["monitoreo de gpu","ollama","aceleración de gpu","uso de vram","modelos en memoria de gpu","métricas de inferencia","nvidia","rocm"],"fr":["surveillance de la gpu","ollama","accélération de la gpu","utilisation de la vram","modèles en mémoire de la gpu","métriques d''inférence","nvidia","rocm"],"de":["gpu-überwachung","ollama","gpu-beschleunigung","vram-nutzung","modelle in gpu-speicher","inferenzmetriken","nvidia","rocm"],"pt":["monitoramento de gpu","ollama","gpu acceleration","nvidia","rocm","vram usage","inference metrics"],"ru":["мониторинг gpu","ollama","ускорение gpu","nvidia","rocm","использование vram","метрики вывода"],"ar":["مراقبة gpu","ollama","تسريع gpu","nvidia","rocm","استخدام vram","قياسات الاستدلال"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.394Z","topics":[],"category":"community","skillMd":{"name":"gpu","description":"|","bodyPreview":"# GPU Monitoring for Ollama\n\n## Overview\n\nMonitor GPU usage and performance when running Ollama with GPU acceleration. This skill covers checking GPU status, VRAM usage, models loaded in GPU memory, and inference performance metrics.\n\n## Quick Reference\n\n| Check | Method |\n|-------|--------|\n| GPU status | `nvidia-smi` / `rocm-smi` |\n| Models in memory | `GET /api/ps` |\n| Inference metrics | Response metadata |\n| VRAM usage | Both nvidia-smi and /api/ps |\n\n## GPU Status Check\n\n### NVIDIA\n\n```pyt","body":"# GPU Monitoring for Ollama\n\n## Overview\n\nMonitor GPU usage and performance when running Ollama with GPU acceleration. This skill covers checking GPU status, VRAM usage, models loaded in GPU memory, and inference performance metrics.\n\n## Quick Reference\n\n| Check | Method |\n|-------|--------|\n| GPU status | `nvidia-smi` / `rocm-smi` |\n| Models in memory | `GET /api/ps` |\n| Inference metrics | Response metadata |\n| VRAM usage | Both nvidia-smi and /api/ps |\n\n## GPU Status Check\n\n### NVIDIA\n\n```python\nimport subprocess\n\ndef check_nvidia_gpu():\n    \"\"\"Check NVIDIA GPU status.\"\"\"\n    try:\n        result = subprocess.run(\n            [\"nvidia-smi\",\n             \"--query-gpu=name,memory.used,memory.total,utilization.gpu\",\n             \"--format=csv,noheader,nounits\"],\n            capture_output=True,\n            text=True,\n            timeout=5\n        )\n        if result.returncode == 0:\n            lines = result.stdout.strip().split(\"\\n\")\n            for i, line in enumerate(lines):\n                parts = line.split(\", \")\n                if len(parts) >= 4:\n                    name, mem_used, mem_total, util = parts\n                    print(f\"GPU {i}: {name}\")\n                    print(f\"  Memory: {mem_used} MB / {mem_total} MB\")\n                    print(f\"  Utilization: {util}%\")\n    except FileNotFoundError:\n        print(\"nvidia-smi not found - NVIDIA GPU may not be available\")\n    except subprocess.TimeoutExpired:\n        print(\"nvidia-smi timed out\")\n\ncheck_nvidia_gpu()\n```\n\n### AMD\n\n```python\nimport subprocess\n\ndef check_amd_gpu():\n    \"\"\"Check AMD GPU status.\"\"\"\n    try:\n        result = subprocess.run(\n            [\"rocm-smi\", \"--showmeminfo\", \"vram\"],\n            capture_output=True,\n            text=True,\n            timeout=5\n        )\n        print(result.stdout)\n    except FileNotFoundError:\n        print(\"rocm-smi not found - AMD GPU may not be available\")\n\ncheck_amd_gpu()\n```\n\n## Models Loaded in GPU Memory\n\n```python\nimport os\nimport requests\n\nOLLAMA_HOST = os.getenv(\"OLLAMA_HOST\", \"http://localhost:11434\")\n\nresponse = requests.get(f\"{OLLAMA_HOST}/api/ps\")\nrunning = response.json()\n\nif running.get(\"models\"):\n    print(\"=== Models Loaded in GPU Memory ===\")\n    for model in running[\"models\"]:\n        name = model.get(\"name\", \"Unknown\")\n        size = model.get(\"size\", 0) / (1024**3)\n        vram = model.get(\"size_vram\", 0) / (1024**3)\n        expires = model.get(\"expires_at\", \"N/A\")\n        print(f\"  - {name}\")\n        print(f\"    Total Size: {size:.2f} GB\")\n        print(f\"    VRAM Usage: {vram:.2f} GB\")\n        print(f\"    Expires: {expires}\")\nelse:\n    print(\"No models currently loaded in memory\")\n```\n\n## Inference Performance Metrics\n\n```python\nimport os\nimport time\nimport requests\n\nOLLAMA_HOST = os.getenv(\"OLLAMA_HOST\", \"http://localhost:11434\")\n\n# Run inference\nstart_time = time.perf_counter()\nresponse = requests.post(\n    f\"{OLLAMA_HOST}/api/generate\",\n    json={\n        \"model\": \"llama3.2:latest\",\n        \"prompt\": \"Write a haiku about computers.\",\n        \"stream\": False\n    }\n)\nend_time = time.perf_counter()\n\nresult = response.json()\n\nprint(f\"Response: {result[''response'']}\")\nprint()\nprint(\"=== Inference Metrics ===\")\nprint(f\"Wall clock time: {end_time - start_time:.2f}s\")\nprint(f\"Prompt eval count: {result.get(''prompt_eval_count'', ''N/A'')}\")\nprint(f\"Prompt eval duration: {result.get(''prompt_eval_duration'', 0) / 1e9:.3f}s\")\nprint(f\"Eval count (tokens generated): {result.get(''eval_count'', ''N/A'')}\")\nprint(f\"Eval duration: {result.get(''eval_duration'', 0) / 1e9:.3f}s\")\nprint(f\"Total duration: {result.get(''total_duration'', 0) / 1e9:.3f}s\")\n\nif result.get(''eval_count'') and result.get(''eval_duration''):\n    tokens_per_sec = result[''eval_count''] / (result[''eval_duration''] / 1e9)\n    print(f\"Tokens/second: {tokens_per_sec:.1f}\")\n```\n\n## GPU Usage During Inference\n\n```python\nimport os\nimport subprocess\nimport requests\nimport threading\nimport time\n\nOLLAMA_HOST = os.getenv(\"OLLAMA_HOST\", \"http://localhost:11434\")\n\ndef monitor_gpu(stop_event, readings):\n    \"\"\"Monitor GPU usage in background.\"\"\"\n    while not stop_event.is_set():\n        try:\n            result = subprocess.run(\n                [\"nvidia-smi\",\n                 \"--query-gpu=utilization.gpu,memory.used\",\n                 \"--format=csv,noheader,nounits\"],\n                capture_output=True,\n                text=True,\n                timeout=1\n            )\n            if result.returncode == 0:\n                parts = result.stdout.strip().split(\", \")\n                if len(parts) >= 2:\n                    readings.append({\n                        \"util\": int(parts[0]),\n                        \"mem\": int(parts[1])\n                    })\n        except:\n            pass\n        time.sleep(0.5)\n\n# Start monitoring\nstop_event = threading.Event()\nreadings = []\nmonitor_thread = threading.Thread(target=monitor_gpu, args=(stop_event, readings))\nmonitor_thread.start()\n\n# Run inference\nresponse = requests.post(\n    f\"{OLLAMA_HOST}/api/generate\",\n    json={\n        \"model\": \"llama3.2:latest\",\n        \"prompt\": \"Write a short story about AI.\",\n        \"stream\": False\n    }\n)\n\n# Stop monitoring\nstop_event.set()\nmonitor_thread.join()\n\n# Report\nif readings:\n    avg_util = sum(r[\"util\"] for r in readings) / len(readings)\n    max_mem = max(r[\"mem\"] for r in readings)\n    print(f\"Average GPU utilization: {avg_util:.1f}%\")\n    print(f\"Peak memory usage: {max_mem} MB\")\n```\n\n## Complete Health Check\n\n```python\nimport os\nimport subprocess\nimport requests\n\nOLLAMA_HOST = os.getenv(\"OLLAMA_HOST\", \"http://localhost:11434\")\nDEFAULT_MODEL = \"llama3.2:latest\"\n\ndef complete_gpu_health_check():\n    \"\"\"Complete GPU and Ollama health check.\"\"\"\n    print(\"=== GPU Health Check ===\")\n    print()\n\n    # 1. Check GPU hardware\n    print(\"1. GPU Hardware:\")\n    try:\n        result = subprocess.run(\n            [\"nvidia-smi\",\n             \"--query-gpu=name,memory.total\",\n             \"--format=csv,noheader\"],\n            capture_output=True,\n            text=True,\n            timeout=5\n        )\n        if result.returncode == 0:\n            print(f\"   {result.stdout.strip()}\")\n        else:\n            print(\"   nvidia-smi failed\")\n    except FileNotFoundError:\n        print(\"   NVIDIA GPU not detected\")\n\n    # 2. Check Ollama server\n    print()\n    print(\"2. Ollama Server:\")\n    try:\n        response = requests.get(f\"{OLLAMA_HOST}/api/tags\", timeout=5)\n        if response.status_code == 200:\n            print(\"   Server is running\")\n            models = response.json()\n            model_names = [m.get(\"name\", \"\") for m in models.get(\"models\", [])]\n            if DEFAULT_MODEL in model_names:\n                print(f\"   Model ''{DEFAULT_MODEL}'' available\")\n            else:\n                print(f\"   Model ''{DEFAULT_MODEL}'' NOT available\")\n        else:\n            print(f\"   Server error: {response.status_code}\")\n    except requests.exceptions.ConnectionError:\n        print(\"   Cannot connect to server\")\n\n    # 3. Check models in GPU memory\n    print()\n    print(\"3. Models in GPU Memory:\")\n    try:\n        response = requests.get(f\"{OLLAMA_HOST}/api/ps\")\n        running = response.json()\n        if running.get(\"models\"):\n            for model in running[\"models\"]:\n                vram = model.get(\"size_vram\", 0) / (1024**3)\n                print(f\"   {model[''name'']}: {vram:.2f} GB VRAM\")\n        else:\n            print(\"   No models loaded\")\n    except:\n        print(\"   Cannot check running models\")\n\ncomplete_gpu_health_check()\n```\n\n## Model Size Guide\n\n| Model | Parameters | VRAM Needed | Tokens/sec (typical) |\n|-------|------------|-------------|----------------------|\n| phi3 | 3B | 4GB | 60-80 |\n| llama3.2 | 8B | 8GB | 40-60 |\n| mistral | 7B | 8GB | 40-60 |\n| codellama | 7B | 8GB | 40-60 |\n| llama3.2:70b | 70B | 48GB+ | 10-20 |\n\n## Troubleshooting\n\n### GPU Not Used\n\n**Symptom:** Low tokens/second, nvidia-smi shows 0% utilization\n\n**Check:**\n\n```bash\n# Check GPU inside container (adjust container name as needed)\ndocker exec -it ollama nvidia-smi\n# or\npodman exec -it ollama nvidia-smi\n```\n\n**Fix:**\n\n```bash\n# Restart Ollama container with GPU access\n# Refer to bazzite-ai-pod-ollama documentation for container setup\n```\n\n### Out of Memory\n\n**Symptom:** \"out of memory\" error during model loading\n\n**Fix:**\n\n```python\n# Use smaller/quantized model via API\nimport requests\nOLLAMA_HOST = os.getenv(\"OLLAMA_HOST\", \"http://localhost:11434\")\n\nresponse = requests.post(\n    f\"{OLLAMA_HOST}/api/pull\",\n    json={\"name\": \"llama3.2:7b-q4_0\"},\n    stream=True\n)\nfor line in response.iter_lines():\n    if line:\n        print(line.decode())\n```\n\n### Slow Inference\n\n**Symptom:** Very low tokens/second\n\n**Possible causes:**\n1. Model too large for VRAM (using CPU fallback)\n2. Wrong GPU type configured\n3. Driver issues\n\n**Check:**\n\n```python\n# Check VRAM usage vs model size\nresponse = requests.get(f\"{OLLAMA_HOST}/api/ps\")\n# If size_vram << size, model is partially on CPU\n```\n\n## When to Use This Skill\n\nUse when:\n- Debugging slow inference\n- Checking if GPU is being utilized\n- Monitoring VRAM usage\n- Benchmarking different models\n- Troubleshooting GPU issues\n\n## Cross-References\n\n- `bazzite-ai-jupyter:chat` - API for running inference\n- `bazzite-ai-jupyter:ollama` - Python library for inference\n"},"lastSynced":"2026-02-18T02:08:16.214Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents with GPU-accelerated workloads needing real-time performance monitoring and optimization.","zh":"非常适合需要实时性能监控和优化的GPU加速工作负载的AI代理。","ja":"GPUアクセラレーションされたワークロードに実時間のパフォーマンスモニタリングと最適化が必要なAIエージェントに最適です。","ko":"실시간 성능 모니터링 및 최적화가 필요한 GPU 가속 워크로드를 갖춘 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA con cargas de trabajo aceleradas por GPU que necesitan monitoreo y optimización de rendimiento en tiempo real.","fr":"Parfait pour les agents IA avec des charges de travail accélérées par GPU nécessitant un suivi et une optimisation des performances en temps réel.","de":"Perfekt für KI-Agenten mit GPU-beschleunigten Workloads, die Echtzeit-Performance-Überwachung und -Optimierung benötigen.","pt":"Perfeito para agentes de IA com cargas de trabalho aceleradas por GPU que necessitam de monitoramento e otimização de desempenho em tempo real.","ru":"Идеально подходит для агентов ИИ с рабочими нагрузками, ускоренными с помощью GPU, требующих мониторинга производительности и оптимизации в реальном времени.","ar":"مثالي لعمليات وكيل الذكاء الاصطناعي التي تعمل بتقنية جوجل بى و التي تحتاج إلى مراقبة أداء و تحسين وقت حقيقي."},"recommendation":{"en":"Empowers agents to monitor GPU usage and performance, checking GPU status, VRAM usage, models loaded in GPU memory, and inference performance metrics using nvidia-smi, rocm-smi, and API calls.","zh":"赋予代理监控GPU使用情况和性能，检查GPU状态、VRAM使用情况、GPU内存中加载的模型以及使用nvidia-smi、rocm-smi和API调用来检查推理性能指标。","ja":"エージェントにGPUの使用状況とパフォーマンスをモニタリングする能力を提供し、GPUのステータス、VRAMの使用状況、GPUメモリにロードされたモデル、およびnvidia-smi、rocm-smi、APIコールを使用した推論パフォーマンスメトリックをチェックします。","ko":"에이전트에게 GPU 사용량 및 성능을 모니터링 할 수 있는 기능을 제공하며, GPU 상태, VRAM 사용량, GPU 메모리에 로드 된 모델 및 nvidia-smi, rocm-smi 및 API 호출을 사용한 추론 성능 메트릭을 확인합니다.","es":"Habilita a los agentes a monitorear el uso de la GPU y el rendimiento, comprobando el estado de la GPU, el uso de VRAM, los modelos cargados en la memoria de la GPU y las métricas de inferencia utilizando nvidia-smi, rocm-smi y llamadas a la API.","fr":"Permet aux agents de surveiller l''utilisation de la GPU et les performances, en vérifiant l''état de la GPU, l''utilisation de la VRAM, les modèles chargés dans la mémoire de la GPU et les métriques d''inférence à l''aide de nvidia-smi, rocm-smi et d''appels d''API.","de":"Ermöglicht es Agenten, die GPU-Auslastung und -Leistung zu überwachen, indem sie den GPU-Status, den VRAM-Verbrauch, die in der GPU-Speicher geladenen Modelle und die Inferenzleistungsmetriken mit nvidia-smi, rocm-smi und API-Aufrufen überprüfen.","pt":"Habilita os agentes a monitorar o uso e o desempenho da GPU, verificando o status da GPU, o uso de VRAM, os modelos carregados na memória da GPU e as métricas de desempenho de inferência usando nvidia-smi, rocm-smi e chamadas de API.","ru":"Позволяет агентам отслеживать использование и производительность GPU, проверяя состояние GPU, использование VRAM, модели, загруженные в память GPU, и метрики производительности вывода, используя nvidia-smi, rocm-smi и вызовы API.","ar":"يسمح للوكلاء بمراقبة استخدام وحدة معالجة الرسومات و أدائها، و التحقق من حالة وحدة معالجة الرسومات، و استخدام ذاكرة وسيط الرسومات، و النماذج المحملة في ذاكرة وحدة معالجة الرسومات، و مقاييس أداء الاستدلال باستخدام nvidia-smi، و rocm-smi، و مكالمات واجهة البرنامج."},"useCases":{"en":["Monitoring GPU status for Ollama workloads","Optimizing VRAM usage for improved performance","Debugging inference metrics for GPU-accelerated models"],"zh":["监控Ollama工作负载的GPU状态","优化VRAM使用以提高性能","调试GPU加速模型的推理指标"],"ja":["OllamaワークロードのGPUステータスをモニタリングする","パフォーマンスの向上のためのVRAM使用の最適化","GPUアクセラレーションされたモデルの推論メトリックのデバッグ"],"ko":["Ollama 워크로드의 GPU 상태 모니터링","성능 개선을 위한 VRAM 사용 최적화","GPU 가속 모델의 추론 메트릭 디버깅"],"es":["Monitoreo del estado de la GPU para cargas de trabajo de Ollama","Optimización del uso de VRAM para un mejor rendimiento","Depuración de métricas de inferencia para modelos acelerados por GPU"],"fr":["Surveillance de l''état de la GPU pour les charges de travail Ollama","Optimisation de l''utilisation de la VRAM pour améliorer les performances","Débogage des métriques d''inférence pour les modèles accélérés par GPU"],"de":["Überwachung des GPU-Status für Ollama-Workloads","Optimierung der VRAM-Auslastung für verbesserte Leistung","Fehlerbehebung von Inferenzmetriken für GPU-beschleunigte Modelle"],"pt":["Monitoramento do status da GPU para cargas de trabalho Ollama","Otimização do uso de VRAM para melhorar o desempenho","Depuração de métricas de inferência para modelos acelerados por GPU"],"ru":["Отслеживание состояния GPU для рабочих нагрузок Ollama","Оптимизация использования VRAM для улучшения производительности","Отладка метрик вывода для моделей, ускоренных с помощью GPU"],"ar":["مراقبة حالة وحدة معالجة الرسومات لتحميل العمل Ollama","تحسين استخدام ذاكرة وسيط الرسومات لتحسين الأداء","تصحيح أخطاء مقاييس الاستدلال لنماذج معززة بواسطة وحدة معالجة الرسومات"]},"limitations":{"en":["Requires NVIDIA or ROCm GPU drivers","Limited to GPU-accelerated workloads","Dependent on API availability for metrics"],"zh":["需要NVIDIA或ROCM GPU驱动程序","仅限GPU加速工作负载","依赖于API可用性以获取指标"],"ja":["NVIDIAまたはROCMのGPUドライバーが必要","GPUアクセラレーションされたワークロードのみ","メトリックの取得にはAPIの可用性に依存"],"ko":["NVIDIA 또는 ROCM GPU 드라이버가 필요합니다.","GPU 가속 워크로드만 해당","메트릭을 가져 오기 위해 API 가용성에 종속"],"es":["Requiere controladores de GPU de NVIDIA o ROCm","Limitado a cargas de trabajo aceleradas por GPU","Dependiente de la disponibilidad de la API para las métricas"],"fr":["Nécessite des pilotes de GPU NVIDIA ou ROCm","Limité aux charges de travail accélérées par GPU","Dépend de la disponibilité de l''API pour les métriques"],"de":["Benötigt NVIDIA- oder ROCm-GPU-Treiber","Begrenzt auf GPU-beschleunigte Workloads","Abhängig von der Verfügbarkeit der API für Metriken"],"pt":["Requer drivers de GPU da NVIDIA ou ROCm","Limitado a cargas de trabalho aceleradas por GPU","Dependente da disponibilidade da API para métricas"],"ru":["Требует драйверов GPU от NVIDIA или ROCm","Ограничен рабочими нагрузками, ускоренными с помощью GPU","Зависит от доступности API для метрик"],"ar":["يتطلب سائقي وحدة معالجة الرسومات من شركة نيفيديا أو روكم","محدود بالتحميلات التي تعمل بتقنية جوجل بى","يعتمد على توافر واجهة برمجة التطبيقات لأداء المقاييس"]},"version":3},"qualityScore":70}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/cdd', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'cdd', 0, 0, 40, '2026-02-18T01:08:43.394Z', '2026-02-18T02:07:58.825Z', NULL, '{"id":"majiayu000/claude-skill-registry/cdd","name":"cdd","description":{"zh":"CDD技能是上下文驱动开发的综合管道，实现并行开发和版本控制","ja":"CDDスキルはコンテキストドリブン開発の総合パイプラインであり、並行開発とバージョン管理を実現","ko":"CDD 스킬은 컨텍스트 드리븐 개발의 종합 파이프라인으로, 병렬 개발과 버전 관리를 구현","es":"CDD es un enfoque de desarrollo que utiliza un flujo de trabajo de lanzamiento basado en el contexto para mejorar la eficiencia y la colaboración.","fr":"Le CDD est une approche de développement qui utilise un flux de travail de lancement basé sur le contexte pour améliorer l''efficacité et la collaboration.","de":"CDD ist eine Entwicklungsmethode, die einen kontextbasierten Release-Workflow verwendet, um die Effizienz und Zusammenarbeit zu verbessern.","pt":"CDD é um registro abrangente de habilidades para desenvolvedores, permitindo trabalhar em paralelo sem conflitos de VCS.","ru":"CDD - это всесторонний реестр навыков для разработчиков, позволяющий работать параллельно без конфликтов VCS.","ar":"سي دي دي هو سجل شامِل للمهارات لِمُطوِّري البرمجيات، مما يسمح العمل بشكل متوازي بدون تضارب في أنظمة التحكم بالنسخ.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"CDD技能：上下文驱动开发管道","ja":"CDDスキル：コンテキストドリブン開発パイプライン","ko":"CDD 스킬: 컨텍스트 드리븐 개발 파이프라인","es":"CDD: Desarrollo de Código Contextual","fr":"CDD : Développement de Code Contextuel","de":"CDD: Kontextgetriebene Code-Entwicklung","pt":"CDD: Desenvolvimento Dirigido por Contexto","ru":"CDD: Контекстно-ориентированное развитие","ar":"سي دي دي: تطوير مدفوع بالسياق","en":"cdd"},"description":{"zh":"CDD技能是上下文驱动开发的综合管道，实现并行开发和版本控制","ja":"CDDスキルはコンテキストドリブン開発の総合パイプラインであり、並行開発とバージョン管理を実現","ko":"CDD 스킬은 컨텍스트 드리븐 개발의 종합 파이프라인으로, 병렬 개발과 버전 관리를 구현","es":"CDD es un enfoque de desarrollo que utiliza un flujo de trabajo de lanzamiento basado en el contexto para mejorar la eficiencia y la colaboración.","fr":"Le CDD est une approche de développement qui utilise un flux de travail de lancement basé sur le contexte pour améliorer l''efficacité et la collaboration.","de":"CDD ist eine Entwicklungsmethode, die einen kontextbasierten Release-Workflow verwendet, um die Effizienz und Zusammenarbeit zu verbessern.","pt":"CDD é um registro abrangente de habilidades para desenvolvedores, permitindo trabalhar em paralelo sem conflitos de VCS.","ru":"CDD - это всесторонний реестр навыков для разработчиков, позволяющий работать параллельно без конфликтов VCS.","ar":"سي دي دي هو سجل شامِل للمهارات لِمُطوِّري البرمجيات، مما يسمح العمل بشكل متوازي بدون تضارب في أنظمة التحكم بالنسخ.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["并行开发","版本控制","工作空间配置","环境变量设置","脚本执行"],"ja":["並行開発","バージョン管理","ワークスペース構成","環境変数設定","スクリプト実行"],"ko":["병렬 개발","버전 관리","작업 공간 구성","환경 변수 설정","스크립트 실행"],"es":["Flujo de trabajo de lanzamiento basado en el contexto","Configuración de espacio de trabajo independiente","Soporte para ramas y directorios de trabajo diferentes","Abortar scripts con error claro si $CDD_DIR no está establecido","Compatibilidad con varios entornos de desarrollo"],"fr":["Flux de travail de lancement basé sur le contexte","Configuration d''un espace de travail indépendant","Prise en charge de branches et de répertoires de travail différents","Abandon des scripts avec une erreur claire si $CDD_DIR n''est pas défini","Compatibilité avec plusieurs environnements de développement"],"de":["Kontextbasierter Release-Workflow","Unabhängige Arbeitsbereichskonfiguration","Unterstützung für verschiedene Branches und Arbeitsverzeichnisse","Abbruch von Skripten mit klarer Fehlermeldung, wenn $CDD_DIR nicht festgelegt ist","Kompatibilität mit mehreren Entwicklungsumgebungen"],"pt":["Trabalho paralelo sem conflitos de VCS","Diretório de trabalho dedicado","Scripts personalizados","Suporte a branchs diferentes","Abortar scripts com erro claro"],"ru":["Параллельная работа без конфликтов VCS","Выделенный рабочий каталог","Пользовательские скрипты","Поддержка разных веток","Прекращение скриптов с ясной ошибкой"],"ar":["العمل المتوازي بدون تضارب في أنظمة التحكم بالنسخ","مجلد عمل مخصص","스크рипٹات مخصصة","دعم الفروع المختلفة","إيقاف سكريبتات مع خطأ واضح"]},"keywords":{"zh":["CDD","上下文驱动开发","并行开发","版本控制","工作空间配置","环境变量"],"ja":["CDD","コンテキストドリブン開発","並行開発","バージョン管理","ワークスペース構成","環境変数"],"ko":["CDD","컨텍스트 드리븐 개발","병렬 개발","버전 관리","작업 공간 구성","환경 변수"],"es":["CDD","Desarrollo de Código Contextual","flujo de trabajo de lanzamiento","configuración de espacio de trabajo","desarrollo de software","colaboración en equipo","eficiencia en el desarrollo"],"fr":["CDD","Développement de Code Contextuel","flux de travail de lancement","configuration d''espace de travail","développement de logiciels","collaboration d''équipe","efficacité dans le développement"],"de":["CDD","Kontextgetriebene Code-Entwicklung","kontextbasierter Release-Workflow","Arbeitsbereichskonfiguration","Software-Entwicklung","Teamzusammenarbeit","Effizienz im Entwicklungsprozess"],"pt":["CDD","Desenvolvimento Dirigido por Contexto","Pipeline de desenvolvimento","Trabalho paralelo","VCS","Diretório de trabalho","Scripts personalizados"],"ru":["CDD","Контекстно-ориентированное развитие","Конвейер разработки","Параллельная работа","VCS","Рабочий каталог","Пользовательские скрипты"],"ar":["سي دي دي","تطوير مدفوع بالسياق","خط أنابيب التطوير","العمل المتوازي","نظام التحكم بالنسخ","مجلد العمل","سكريبتات مخصصة"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.394Z","topics":[],"category":"community","skillMd":{"name":"cdd","description":"Context Driven Development pipeline for release workflows","bodyPreview":"# CDD Pipeline\n\nThis project calls its release workflow Context Driven Development (CDD)\n\n## Workspace Configuration\n\n**All CDD commands and scripts require the `$CDD_DIR` environment variable.**\n\n```bash\nexport CDD_DIR=/path/to/workspace\n```\n\nThis allows parallel workspaces without VCS conflicts. Each workspace is independent - different branches can use different workspace directories simultaneously.\n\nScripts will abort with a clear error if `$CDD_DIR` is not set.\n\n## Core Philosophy\n\nUse user","body":"# CDD Pipeline\n\nThis project calls its release workflow Context Driven Development (CDD)\n\n## Workspace Configuration\n\n**All CDD commands and scripts require the `$CDD_DIR` environment variable.**\n\n```bash\nexport CDD_DIR=/path/to/workspace\n```\n\nThis allows parallel workspaces without VCS conflicts. Each workspace is independent - different branches can use different workspace directories simultaneously.\n\nScripts will abort with a clear error if `$CDD_DIR` is not set.\n\n## Core Philosophy\n\nUse user/agent interactive development time during the Research and Plan phases to prepare tightly focused work that pre-loads the exact required context to run autonomously during the Execute phase.\n\n## Pipeline Phases\n\n  * Research\n  * Plan\n  * Execute\n\n### 1. Research\n\n**What:** Build foundational understanding before design decisions.\n\n**Artifacts:**\n- `$CDD_DIR/README.md` - High-level description of release features\n- `$CDD_DIR/user-stories/` - User actions and expected system responses\n- `$CDD_DIR/research/` - Facts gathered from internet, docs, codebase\n\n**Why this phase exists:** Decisions made without research are assumptions. Research surfaces constraints, prior art, and edge cases that would otherwise appear during execution (when fixing is expensive).\n\n**Key insight:** Research artifacts become reference material for execution. Sub-agents can read `$CDD_DIR/research/` without re-fetching from the internet. The research phase pays the lookup cost once.\n\n### 2. Plan\n\n**What:** Transform research into implementation decisions.\n\n**Artifacts:**\n- `$CDD_DIR/plan/` - Implementation decisions, architecture choices, detailed designs\n\n**Why this phase exists:** Planning is the translation layer between \"what we want\" (research) and \"what to do\". It makes architectural decisions explicit.\n\n### 3. Verify (Sub-phase of Plan)\n\n**What:** Iterative verification of plan alignment.\n\n**Artifacts:**\n- `$CDD_DIR/verified.md` - Log of items verified and issues resolved\n\n**Verification:**\n```\n/cdd:gap-plan  # Verify README/user-stories → plan alignment\nfix gaps\n/cdd:gap-plan  # Repeat until clean\n```\n\nChecks alignment down the pyramid:\n- README/research/user-stories → plan\n- Naming, error handling, memory management conventions\n- Integration points, build changes, migrations\n\n**Why this phase exists:** This is the **last moment of full context visibility**. Cross-cutting issues and inconsistencies can only be caught while the complete picture is visible.\n\n**Key insights:**\n- Specific checklists prevent vague \"find issues\" prompts\n- `verified.md` prevents re-checking completed items\n\n**Convergence pattern:** Each gap-finding run identifies the highest-priority issue. After fixing, re-run. When no substantive gaps remain, verification is complete.\n\n### 4. Execute\n\n**What:** Execution via the ralph harness script.\n\n**Process:**\n```\nralph → /check-quality → /refactor → /check-quality\n```\n\n**Why this structure:** Execution is unattended. No human to provide missing context.\n\n## Directory Structure\n\n```\n$CDD_DIR/\n├── README.md          # High-level release description\n├── user-stories/      # User actions and system responses\n│   └── README.md      # Index/overview\n├── research/          # Internet facts for reference\n│   └── README.md      # Index/overview\n├── plan/              # Implementation decisions\n│   └── README.md      # Index/overview\n├── verified.md        # Verification log (concerns + resolutions)\n├── tmp/               # Temp files during execution\n└── ...                # Other files permitted, ignored by pipeline\n```\n\n## Abstraction Levels\n\nEach directory serves a distinct abstraction level. Content should not leak between levels.\n\n### $CDD_DIR/plan/ - Coordination Layer\n\nPlan documents **coordinate everything shared**.\n\n**The plan owns:**\n- **Public symbols** - Function names, struct names, enum names\n- **Function signatures** - Arguments, argument order, return types\n- **Struct members** - Field names, field order, field types\n- **Enums** - Value names and meanings\n- **Allowed libraries** - Which dependencies can be used, which are forbidden\n- **Architectural choices** - Module boundaries, data flow, ownership rules\n\n**The plan is the contract.**\n\n**DO NOT include:** Implementation code, detailed algorithms, function bodies.\n\n## Artifact Authority\n\nArtifacts form a hierarchy of authority:\n\n```\n$CDD_DIR/README.md (authoritative)\n        ↓\nuser-stories + research (derived)\n        ↓\n      plan (derived)\n```\n\n**Rules:**\n\n1. Lower-level artifacts derive from higher-level ones\n2. Contradictions between levels must be resolved immediately\n3. Resolution is always top-down: align lower artifacts to higher authority\n4. Higher-level documents may change through iteration—but when they do, all derived artifacts must be reviewed and realigned\n\n**Why this matters:** Consistency is enforced during authoring because it cannot be enforced during execution.\n\n## Lifecycle\n\n```\nCreate empty $CDD_DIR/ → Research → Plan → Verify → Execute → Delete $CDD_DIR/\n```\n\nThe workspace directory is ephemeral. It exists only for the duration of the release workflow. After successful execution, it''s deleted. The work lives in the codebase; the pipeline artifacts are disposable.\n\n## Efficiency Principles\n\n1. **Load skills on-demand** - Don''t preload \"just in case\"\n2. **Complete authoring** - Spend tokens researching during authoring so execution doesn''t need to\n3. **Reference vs working knowledge** - Large docs go in separate skills, loaded when needed\n\n## Design Tradeoffs\n\n| Decision | Tradeoff | Rationale |\n|----------|----------|-----------|\n| Full context in verify | Expensive per-run | Last chance to catch cross-cutting issues |\n| Verification is human-terminated | Subjective | Models don''t converge to \"done\" naturally |\n| Research cached in files | Stale if release spans days | Avoids re-fetching during execution |\n\n## When to Load This Skill\n\n- Designing or modifying the release workflow\n- Debugging why execution sub-agents are failing\n- Optimizing token usage in the pipeline\n- Understanding why a phase exists before changing it\n"},"lastSynced":"2026-02-18T02:07:58.825Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing streamlined workflow management with Context Driven Development (CDD) pipelines.","zh":"非常适合需要简化工作流管理的开发代理，具有上下文驱动开发（CDD）管道。","ja":"開発エージェントがワークフロー管理を効率化する必要がある場合に最適です。Context Driven Development（CDD）パイプラインを備えています。","ko":"개발 에이전트가 워크플ロー 관리를 간소화해야 하는 경우에 적합합니다. 컨텍스트 기반 개발(CDD) 파이프라인을 제공합니다.","es":"Perfecto para agentes de desarrollo que necesitan una gestión de flujo de trabajo optimizada con pipelines de Desarrollo Orientado a Contexto (CDD).","fr":"Parfait pour les agents de développement ayant besoin d''une gestion de flux de travail rationalisée avec des pipelines de développement piloté par le contexte (CDD).","de":"Perfekt für Entwicklungsmittel, die eine optimierte Workflow-Verwaltung mit Context-Driven-Development-(CDD)-Pipelines benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de gerenciamento de fluxo de trabalho otimizado com pipelines de Desenvolvimento Dirigido por Contexto (CDD).","ru":"Идеально подходит для агентов разработки, которым необходим упрощенный менеджмент рабочего процесса с помощью конвейеров контекстно-ориентированной разработки (CDD).","ar":"مثالي للوكلاء النموزجيون الذين يحتاجون إلى إدارة تدفق العمل المُتبسط مع أنابيب التطوير الموجه بالسياق (CDD)."},"recommendation":{"en":"Empowers agents to manage independent workspaces, utilize environment variables like $CDD_DIR, and execute scripts for parallel development without VCS conflicts, leveraging bash commands and scripts for efficient project release workflows.","zh":"使代理能够管理独立的工作空间，利用环境变量（如 $CDD_DIR ），并在不发生 VCS 冲突的情况下执行脚本以实现并行开发，利用 bash 命令和脚本实现高效的项目发布工作流。","ja":"エージェントが独立したワークスペースを管理し、環境変数（たとえば $CDD_DIR ）を利用し、VCS の競合が発生せずに並行開発のためのスクリプトを実行することができます。bash コマンドとスクリプトを使用して効率的なプロジェクトリリースワークフローを実現します。","ko":"에이전트가 독립적인 작업 공간을 관리하고 환경 변수를 사용하여(예: $CDD_DIR) VCS 충돌 없이 병렬 개발을 위한 스크립트를 실행할 수 있습니다. bash 명령과 스크립트를 사용하여 효율적인 프로젝트 릴리스 워크플로를 제공합니다.","es":"Habilita a los agentes a gestionar espacios de trabajo independientes, utilizar variables de entorno como $CDD_DIR y ejecutar scripts para el desarrollo paralelo sin conflictos de VCS, aprovechando comandos y scripts de bash para flujos de trabajo de lanzamiento de proyectos eficientes.","fr":"Permet aux agents de gérer des espaces de travail indépendants, d''utiliser des variables d''environnement comme $CDD_DIR et d''exécuter des scripts pour le développement parallèle sans conflits de VCS, en exploitant les commandes et les scripts bash pour des flux de travail de publication de projets efficaces.","de":"Ermächtigt Agenten, unabhängige Arbeitsbereiche zu verwalten, Umgebungsvariablen wie $CDD_DIR zu verwenden und Skripte für parallele Entwicklung ohne VCS-Konflikte auszuführen, indem Bash-Befehle und -Skripte für effiziente Projekt-Release-Workflows genutzt werden.","pt":"Habilita os agentes a gerenciar espaços de trabalho independentes, utilizar variáveis de ambiente como $CDD_DIR e executar scripts para desenvolvimento paralelo sem conflitos de VCS, aproveitando comandos bash e scripts para fluxos de trabalho de lançamento de projeto eficientes.","ru":"Наделяет агентов возможностью управлять независимыми рабочими пространствами, использовать переменные среды, такие как $CDD_DIR, и выполнять скрипты для параллельной разработки без конфликтов VCS, используя команды bash и скрипты для эффективных рабочих процессов выпуска проекта.","ar":"يُمكّن الوكلاء من إدارة مساحات عمل مستقلة، واستخدام المتغيرات البيئية مثل $CDD_DIR، وتنفيذ البرامج النصية للتنمية الموازية دون تحديدات نظام التحكم في الإصدار، واستخدام أوامر bash والبرامج النصية من أجل سير عمل كفؤة لإطلاق المشروع."},"useCases":{"en":["Configuring workspace environments","Executing CDD commands and scripts","Managing parallel workspaces for different branches"],"zh":["配置工作空间环境","执行 CDD 命令和脚本","管理不同分支的并行工作空间"],"ja":["ワークスペース環境の構成","CDD コマンドとスクリプトの実行","異なるブランチの並行ワークスペースの管理"],"ko":["작업 공간 환경 구성","CDD 명령 및 스크립트 실행","다른 브랜치에 대한 병렬 작업 공간 관리"],"es":["Configuración de entornos de espacio de trabajo","Ejecución de comandos y scripts de CDD","Administración de espacios de trabajo paralelos para diferentes ramas"],"fr":["Configuration des environnements d''espace de travail","Exécution de commandes et de scripts CDD","Gestion d''espaces de travail parallèles pour différentes branches"],"de":["Konfiguration von Arbeitsbereichsumgebungen","Ausführen von CDD-Befehlen und -Skripten","Verwaltung von parallelen Arbeitsbereichen für verschiedene Zweige"],"pt":["Configurando ambientes de espaço de trabalho","Executando comandos e scripts CDD","Gerenciando espaços de trabalho paralelos para diferentes branches"],"ru":["Настройка окружения рабочего пространства","Выполнение команд и скриптов CDD","Управление параллельными рабочими пространствами для разных веток"],"ar":["تكوين بيئات مساحات العمل","تنفيذ أوامر وبرامج نصية CDD","إدارة مساحات العمل الموازية للفروع المختلفة"]},"limitations":{"en":["Requires $CDD_DIR environment variable to be set","Abort with error if $CDD_DIR is not set"],"zh":["需要环境变量 $CDD_DIR 设置","如果 $CDD_DIR 未设置，则中止并显示错误"],"ja":["環境変数 $CDD_DIR を設定する必要があります","$CDD_DIR が設定されていない場合、エラーで中止されます"],"ko":["환경 변수 $CDD_DIR 설정이 필요합니다","$CDD_DIR 이 설정되지 않은 경우 오류로 중단됩니다"],"es":["Requiere que la variable de entorno $CDD_DIR esté establecida","Aborta con error si $CDD_DIR no está establecida"],"fr":["Nécessite que la variable d''environnement $CDD_DIR soit définie","Abandonne avec erreur si $CDD_DIR n''est pas définie"],"de":["Benötigt, dass die Umgebungsvariable $CDD_DIR festgelegt ist","Abbruch mit Fehler, wenn $CDD_DIR nicht festgelegt ist"],"pt":["Exige que a variável de ambiente $CDD_DIR seja configurada","Aborta com erro se $CDD_DIR não for configurada"],"ru":["Требует, чтобы переменная среды $CDD_DIR была установлена","Прерывает с ошибкой, если $CDD_DIR не установлена"],"ar":["يتطلب تحديد متغير البيئة $CDD_DIR","يُنهي مع خطأ إذا لم يُحدد $CDD_DIR"]},"version":3},"qualityScore":40}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/deno', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'deno', 0, 0, 70, '2026-02-18T01:08:43.394Z', '2026-02-18T02:08:05.281Z', NULL, '{"id":"majiayu000/claude-skill-registry/deno","name":"deno","description":{"zh":"Deno是现代JavaScript和TypeScript的运行环境，本指南介绍Deno的开发最佳实践","ja":"Denoは現代のJavaScriptとTypeScriptのランタイム環境です。このガイドではDenoの開発ベストプラクティスを紹介します","ko":"Deno는 현대의 JavaScript와 TypeScript의 런타임 환경입니다. 이 가이드에서는 Deno의 개발 모범 사례에 대해介绍합니다","es":"Deno es un entorno de ejecución de JavaScript y TypeScript que permite desarrollar aplicaciones de manera segura y eficiente.","fr":"Deno est un environnement d''exécution JavaScript et TypeScript qui permet de développer des applications de manière sécurisée et efficace.","de":"Deno ist eine Laufzeitumgebung für JavaScript und TypeScript, die es ermöglicht, Anwendungen sicher und effizient zu entwickeln.","pt":"Deno é um runtime de JavaScript e TypeScript que permite desenvolver aplicações seguras e escaláveis","ru":"Deno — это среда выполнения JavaScript и TypeScript, которая позволяет разрабатывать безопасные и масштабируемые приложения","ar":"دينو هو وقت تشغيل JavaScript وTypeScript الذي يسمح بتطوير التطبيقات الآمنة والقابلة للتوسيع","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"Deno开发指南","ja":"Deno開発ガイド","ko":"Deno 개발 가이드","es":"Deno: Desarrollo de Aplicaciones con JavaScript y TypeScript","fr":"Deno : Développement d''applications avec JavaScript et Ty...","de":"Deno: Entwicklung von Anwendungen mit JavaScript und Type...","pt":"Deno: Desenvolvimento de Aplicações Seguras","ru":"Deno: Разработка Безопасных Приложений","ar":"دينو: تطوير التطبيقات الآمنة","en":"deno"},"description":{"zh":"Deno是现代JavaScript和TypeScript的运行环境，本指南介绍Deno的开发最佳实践","ja":"Denoは現代のJavaScriptとTypeScriptのランタイム環境です。このガイドではDenoの開発ベストプラクティスを紹介します","ko":"Deno는 현대의 JavaScript와 TypeScript의 런타임 환경입니다. 이 가이드에서는 Deno의 개발 모범 사례에 대해介绍합니다","es":"Deno es un entorno de ejecución de JavaScript y TypeScript que permite desarrollar aplicaciones de manera segura y eficiente.","fr":"Deno est un environnement d''exécution JavaScript et TypeScript qui permet de développer des applications de manière sécurisée et efficace.","de":"Deno ist eine Laufzeitumgebung für JavaScript und TypeScript, die es ermöglicht, Anwendungen sicher und effizient zu entwickeln.","pt":"Deno é um runtime de JavaScript e TypeScript que permite desenvolver aplicações seguras e escaláveis","ru":"Deno — это среда выполнения JavaScript и TypeScript, которая позволяет разрабатывать безопасные и масштабируемые приложения","ar":"دينو هو وقت تشغيل JavaScript وTypeScript الذي يسمح بتطوير التطبيقات الآمنة والقابلة للتوسيع","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"definition":{"en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"features":{"zh":["版本要求","测试命令","包管理","常用命令","JSR支持"],"ja":["バージョン要件","テストコマンド","パッケージ管理","よく使うコマンド","JSRサポート"],"ko":["버전 요구 사항","테스트 명령","패키지 관리","일반적인 명령","JSR 지원"],"es":["Soporte para JavaScript y TypeScript","Gestión de paquetes con JSR","Pruebas con permisos","Compatibilidad con Deno 2","Definición de permisos en deno.json","Uso de comandos como `deno test -P`"],"fr":["Prise en charge de JavaScript et TypeScript","Gestion des paquets avec JSR","Tests avec autorisations","Compatibilité avec Deno 2","Définition des autorisations dans deno.json","Utilisation de commandes comme `deno test -P`"],"de":["Unterstützung für JavaScript und TypeScript","Paketverwaltung mit JSR","Tests mit Berechtigungen","Kompatibilität mit Deno 2","Definition von Berechtigungen in deno.json","Verwendung von Befehlen wie `deno test -P`"],"pt":["Gerenciamento de pacotes com JSR","Testes com permissões","Definição de permissões em deno.json","Uso de Deno 2","Comandos comuns para desenvolvimento"],"ru":["Управление пакетами с помощью JSR","Тестирование с разрешениями","Определение разрешений в deno.json","Использование Deno 2","Общие команды для разработки"],"ar":["إدارة الحزم مع JSR","اختبارات بالسماح","تحديد الصلاحيات في deno.json","استخدام Deno 2","أوامر مشتركة للتطوير"]},"keywords":{"zh":["Deno","JavaScript","TypeScript","包管理","测试","JSR"],"ja":["Deno","JavaScript","TypeScript","パッケージ管理","テスト","JSR"],"ko":["Deno","JavaScript","TypeScript","패키지 관리","테스트","JSR"],"es":["Deno","JavaScript","TypeScript","desarrollo de aplicaciones","gestión de paquetes","pruebas","seguridad","Deno 2","JSR"],"fr":["Deno","JavaScript","TypeScript","développement d''applications","gestion des paquets","tests","sécurité","Deno 2","JSR"],"de":["Deno","JavaScript","TypeScript","Anwendungsentwicklung","Paketverwaltung","Tests","Sicherheit","Deno 2","JSR"],"pt":["Deno","Desenvolvimento de aplicações","Gerenciamento de pacotes","Testes","Segurança","JavaScript","TypeScript"],"ru":["Deno","Разработка приложений","Управление пакетами","Тестирование","Безопасность","JavaScript","TypeScript"],"ar":["دينو","تطوير التطبيقات","إدارة الحزم","اختبارات","أمان","جافاسكريبت","تايبسكريبت"]}},"owner":"majiayu000","repo":"claude-skill-registry","repoPath":"majiayu000/claude-skill-registry","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.394Z","topics":[],"category":"community","skillMd":{"name":"deno","description":"Deno 2 development workflow including testing with permissions and JSR package management. Use when working with Deno projects, setting up new Deno applications, or when the user mentions Deno, JSR, or modern JavaScript/TypeScript development.","bodyPreview":"# Deno Development\n\n## Version Requirements\n- Always use Deno 2\n\n## Testing\n- Use `deno test -P` for running tests with permissions granted\n- The `-P` flag allows permissions described in `deno.json` during testing.\n- Define test permissions in the `test` section of `deno.json`.\n\n## Package Management\n- Use JSR (JavaScript Registry) for package dependencies https://jsr.io/\n- JSR is the modern package registry for JavaScript and TypeScript\n\n## Common Commands\n\n### Adding Dependencies\n```bash\n# Ad","body":"# Deno Development\n\n## Version Requirements\n- Always use Deno 2\n\n## Testing\n- Use `deno test -P` for running tests with permissions granted\n- The `-P` flag allows permissions described in `deno.json` during testing.\n- Define test permissions in the `test` section of `deno.json`.\n\n## Package Management\n- Use JSR (JavaScript Registry) for package dependencies https://jsr.io/\n- JSR is the modern package registry for JavaScript and TypeScript\n\n## Common Commands\n\n### Adding Dependencies\n```bash\n# Add from JSR\ndeno add jsr:@std/log\ndeno add jsr:@std/path\n\n# Add from npm (when necessary)\ndeno add npm:express\n```\n\n### Running Tests\n```bash\n# Run all tests with permissions\ndeno test -P\n\n# Run specific test file\ndeno test -P test/example.test.ts\n```\n\n### Running Applications\n```bash\n# Run with limited permissions - AVOID -A unless absolutely necessary\ndeno run --allow-read=. main.ts\ndeno run --allow-net --allow-read=./public server.ts\ndeno run --allow-env --allow-read=. config.ts\n\n# for `export default { fetch }`\ndeno serve serve.ts\n\n# Use permission sets from deno.json\ndeno run -P main.ts\n```\n\n## Configuration with deno.json\n\n### Permission Sets\nDefine permission sets in deno.json for consistent security:\n\n```json\n{\n  \"permissions\": {\n    \"default\": {\n      \"read\": [\".\"],\n      \"env\": {\n        \"allow\": [\"NODE_ENV\", \"PORT\"],\n        \"deny\": [\"SECRET_KEY\"],\n        \"ignore\": [\"TEMP_*\"]\n      }\n    },\n    \"server\": {\n      \"read\": [\"./public\"],\n      \"net\": [\"localhost:8000\", \"deno.land\"],\n      \"env\": {\n        \"allow\": [\"DATABASE_URL\", \"API_KEY\"]\n      }\n    }\n  }\n}\n```\n\n### Test Permissions\nConfigure test permissions in deno.json:\n\n```json\n{\n  \"test\": {\n    \"permissions\": {\n      \"read\": [\".\"],\n      \"net\": true\n    }\n  }\n}\n```\n\n## Best Practices\n- NEVER use `-A` (all permissions) unless absolutely necessary\n- Always use the most restrictive permissions possible\n- Use `--allow-read=.` instead of `--allow-read` to limit to current directory\n- Use permission sets in deno.json for consistent security\n- Define test permissions in deno.json under the `test` section\n- Use `env.allow`, `env.deny`, and `env.ignore` for fine-grained environment variable control (`read.ignore` also available)\n- Do not use `import` statements with full URLs for external dependencies. Instead, use `deno add` first.\n- Leverage Deno''s built-in security features\n- Use JSR for package discovery and management\n"},"lastSynced":"2026-02-18T02:08:05.281Z","agentAnalysis":{"suitability":{"en":"Perfect for JavaScript Agents needing secure and efficient runtime environments with Deno 2","zh":"非常适合需要安全高效运行环境的JavaScript代理，特别是与Deno 2结合使用","ja":"JavaScriptエージェントが安全で効率的なランタイム環境を必要とする場合、Deno 2と組み合わせて使用するのに最適","ko":"JavaScript 에이전트가 보안이 높은 효율적인 런타임 환경을 필요로 하는 경우 Deno 2와 함께 사용하기에 완벽","es":"Perfecto para Agentes de JavaScript que necesitan entornos de tiempo de ejecución seguros y eficientes con Deno 2","fr":"Parfait pour les agents JavaScript ayant besoin d''environnements d''exécution sécurisés et efficaces avec Deno 2","de":"Perfekt für JavaScript-Agents, die sichere und effiziente Laufzeitumgebungen mit Deno 2 benötigen","pt":"Perfeito para Agentes JavaScript que necessitam de ambientes de execução seguros e eficientes com Deno 2","ru":"Идеально для агентов JavaScript, требующих безопасных и эффективных сред выполнения с Deno 2","ar":"مثالي للوكلاء JavaScript الذين يحتاجون إلى بيئات تشغيل آمنة وفعاله مع Deno 2"},"recommendation":{"en":"Empowers agents to leverage Deno''s secure by default approach, utilizing JSR for package dependencies and managing permissions with deno.json, while executing tests with granted permissions using `deno test -P`","zh":"赋予代理使用Deno的默认安全方法，利用JSR进行包依赖管理，并使用deno.json管理权限，同时使用`deno test -P`执行具有授予权限的测试","ja":"エージェントにDenoのデフォルトでセキュアなアプローチを利用させ、JSRを使用してパッケージの依存関係を管理し、deno.jsonを使用して権限を管理し、`deno test -P`を使用して権限が付与されたテストを実行する","ko":"에이전트에게 Deno의 기본 보안 방법을 사용할 수 있게 해주며, JSR을 사용하여 패키지 의존성을 관리하고 deno.json을 사용하여 권한을 관리하며 `deno test -P`를 사용하여 권한이 부여된 테스트를 실행","es":"Habilita a los agentes a aprovechar el enfoque seguro por defecto de Deno, utilizando JSR para dependencias de paquetes y gestionando permisos con deno.json, mientras se ejecutan pruebas con permisos concedidos usando `deno test -P`","fr":"Permet aux agents d''exploiter l''approche sécurisée par défaut de Deno, en utilisant JSR pour les dépendances de paquets et en gérant les autorisations avec deno.json, tout en exécutant des tests avec des autorisations accordées en utilisant `deno test -P`","de":"Ermöglicht es Agents, Denos sicherheitsorientierten Ansatz zu nutzen, indem JSR für Paketabhängigkeiten verwendet und Berechtigungen mit deno.json verwaltet werden, während Tests mit erteilten Berechtigungen mithilfe von `deno test -P` ausgeführt werden","pt":"Habilita os agentes a aproveitar a abordagem segura por padrão do Deno, utilizando JSR para dependências de pacotes e gerenciando permissões com deno.json, enquanto executa testes com permissões concedidas usando `deno test -P`","ru":"Наделяет агентов возможностью использовать безопасный по умолчанию подход Deno, используя JSR для зависимостей пакетов и управляя разрешениями с помощью deno.json, при этом выполняя тесты с предоставленными разрешениями с помощью `deno test -P`","ar":"تمكّن الوكلاء من الاستفادة من نهج Deno الآمن افتراضيًا، باستخدام JSR لاعتمادات الحزم وإدارة الأذونات مع deno.json، بينما يتم تشغيل الاختبارات بأذونات معطاة باستخدام `deno test -P`"},"useCases":{"en":["Developing secure server-side applications","Managing dependencies with JSR","Testing Deno projects with permission grants"],"zh":["开发安全的服务器端应用程序","使用JSR管理依赖","使用权限授权测试Deno项目"],"ja":["セキュアなサーバーサイドアプリケーションの開発","JSRを使用した依存関係の管理","権限付与テストを使用したDenoプロジェクトのテスト"],"ko":["보안이 높은 서버端 애플리케이션 개발","JSR을 사용한 의존성 관리","권한 부여 테스트를 사용한 Deno 프로젝트 테스트"],"es":["Desarrollar aplicaciones de servidor seguro","Gestionar dependencias con JSR","Probar proyectos Deno con concesiones de permisos"],"fr":["Développer des applications serveur sécurisées","Gérer les dépendances avec JSR","Tester des projets Deno avec des octrois de permissions"],"de":["Sichere Server-Anwendungen entwickeln","Abhängigkeiten mit JSR verwalten","Deno-Projekte mit Berechtigungsvergaben testen"],"pt":["Desenvolver aplicações de servidor seguro","Gerenciar dependências com JSR","Testar projetos Deno com concessões de permissão"],"ru":["Разработка безопасных серверных приложений","Управление зависимостями с помощью JSR","Тестирование проектов Deno с предоставлением разрешений"],"ar":["تطوير تطبيقات خادم آمنة","إدارة الاعتمادات باستخدام JSR","اختبار مشاريع Deno بأذونات معطاة"]},"limitations":{"en":["Requires Deno 2","Dependent on JSR for package management","Needs deno.json for permission configuration"],"zh":["需要Deno 2","依赖JSR进行包管理","需要deno.json进行权限配置"],"ja":["Deno 2が必要","JSRに依存してパッケージを管理","deno.jsonが必要なので権限の構成"],"ko":["Deno 2가 필요","JSR에 의존하여 패키지를 관리","deno.json이 필요하여 권한 구성"],"es":["Requiere Deno 2","Depende de JSR para la gestión de paquetes","Necesita deno.json para la configuración de permisos"],"fr":["Nécessite Deno 2","Dépend de JSR pour la gestion de paquets","Nécessite deno.json pour la configuration des autorisations"],"de":["Benötigt Deno 2","Hängt von JSR für die Paketverwaltung ab","Benötigt deno.json für die Berechtigungskonfiguration"],"pt":["Exige Deno 2","Depende de JSR para gerenciamento de pacotes","Necessita de deno.json para configuração de permissões"],"ru":["Требует Deno 2","Зависит от JSR для управления пакетами","Требует deno.json для настройки разрешений"],"ar":["يتطلب Deno 2","يعتمد على JSR لإدارة الحزم","يحتاج إلى deno.json لتكوين الأذونات"]},"version":3},"qualityScore":70}');
