INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sickn33/antigravity-awesome-skills/distributed-tracing', 'community', 'sickn33', 'antigravity-awesome-skills', 'sickn33/antigravity-awesome-skills', 'distributed-tracing', 0, 0, 80, '2026-02-18T01:08:43.395Z', '2026-02-18T02:15:12.966Z', NULL, '{"id":"sickn33/antigravity-awesome-skills/distributed-tracing","name":"distributed-tracing","description":{"zh":"分布式追踪是指在微服务架构中实现请求流可见性的技术，使用Jaeger和Tempo等工具。","ja":"分散トレーシングは、マイクロサービスアーキテクチャでリクエストフロー可視性を実現する技術であり、JaegerやTempoなどのツールを使用する。","ko":"분산 트레이싱은 마이크로 서비스 아키텍처에서 요청 흐름 가시성을 实现하는 기술로서 Jaeger와 Tempo 등의 툴을 사용한다.","es":"El rastreo distribuido permite la visibilidad del flujo de solicitudes en microservicios. Implementa con Jaeger y Tempo para mejorar el rendimiento","fr":"Le traçage distribué permet la visibilité du flux de requêtes dans les microservices. Mettez en œuvre avec Jaeger et Tempo pour améliorer les performances","de":"Die verteilte Ablaufverfolgung ermöglicht die Sichtbarkeit des Anforderungsflusses in Mikrodiensten. Implementieren Sie mit Jaeger und Tempo, um die Leistung zu verbessern","pt":"O rastreio distribuído é uma técnica para monitorar e depurar aplicações distribuídas. Implemente com Jaeger e Tempo para melhorar a visibilidade.","ru":"Распределённое трассирование - это техника для мониторинга и отладки распределённых приложений. Реализуйте с Jaeger и Tempo для улучшения видимости.","ar":"التحديد التوزيعي هو تقنية لمراقبة وتحسين التطبيقات الموزعة. نفذ مع Jaeger و Tempo لتحسين الرؤية.","en":"The Ultimate Collection of 800+ Agentic Skills for Claude Code/Antigravity/Cursor. Battle-tested, high-performance skills for AI agents including official skills from Anthropic and Vercel."},"seo":{"title":{"zh":"分布式追踪技术","ja":"分散トレーシング","ko":"분산 트레이싱","es":"Rastreo distribuido para microservicios","fr":"Traçage distribué pour microservices","de":"Verteilte Ablaufverfolgung für Mikrodienste","pt":"Rastreio Distribuído: Visibilidade de Fluxo de Solicitação","ru":"Распределённое трассирование: видимость потока запросов","ar":"التحديد التوزيعي: رؤية تدفق الطلب","en":"distributed-tracing"},"description":{"zh":"分布式追踪是指在微服务架构中实现请求流可见性的技术，使用Jaeger和Tempo等工具。","ja":"分散トレーシングは、マイクロサービスアーキテクチャでリクエストフロー可視性を実現する技術であり、JaegerやTempoなどのツールを使用する。","ko":"분산 트레이싱은 마이크로 서비스 아키텍처에서 요청 흐름 가시성을 实现하는 기술로서 Jaeger와 Tempo 등의 툴을 사용한다.","es":"El rastreo distribuido permite la visibilidad del flujo de solicitudes en microservicios. Implementa con Jaeger y Tempo para mejorar el rendimiento","fr":"Le traçage distribué permet la visibilité du flux de requêtes dans les microservices. Mettez en œuvre avec Jaeger et Tempo pour améliorer les performances","de":"Die verteilte Ablaufverfolgung ermöglicht die Sichtbarkeit des Anforderungsflusses in Mikrodiensten. Implementieren Sie mit Jaeger und Tempo, um die Leistung...","pt":"O rastreio distribuído é uma técnica para monitorar e depurar aplicações distribuídas. Implemente com Jaeger e Tempo para melhorar a visibilidade.","ru":"Распределённое трассирование - это техника для мониторинга и отладки распределённых приложений. Реализуйте с Jaeger и Tempo для улучшения видимости.","ar":"التحديد التوزيعي هو تقنية لمراقبة وتحسين التطبيقات الموزعة. نفذ مع Jaeger و Tempo لتحسين الرؤية.","en":"The Ultimate Collection of 800+ Agentic Skills for Claude Code/Antigravity/Cursor. Battle-tested, high-performance skills for AI agents including official sk..."},"definition":{"en":"The Ultimate Collection of 800+ Agentic Skills for Claude Code/Antigravity/Cursor. Battle-tested, high-performance skills for AI agents including official skills from Anthropic and Vercel."},"features":{"zh":["实现分布式追踪","使用Jaeger和Tempo","提高微服务请求流可见性","支持多种数据存储","提供可视化的请求流追踪"],"ja":["分散トレーシングの実装","JaegerとTempoの使用","マイクロサービス間のリクエストフロー可視性の向上","多種のデータストレージのサポート","可視化されたリクエストフローの追跡"],"ko":["분산 트레이싱 구현","Jaeger와 Tempo 사용","마이크로 서비스 간 요청 흐름 가시성 향상","다양한 데이터 저장소 지원","가시화된 요청 흐름追跡"],"es":["Visibilidad del flujo de solicitudes","Implementación con Jaeger y Tempo","Mejora del rendimiento","Análisis de microservicios","Seguimiento de errores"],"fr":["Visibilité du flux de requêtes","Mise en œuvre avec Jaeger et Tempo","Amélioration des performances","Analyse de microservices","Suivi des erreurs"],"de":["Sichtbarkeit des Anforderungsflusses","Implementierung mit Jaeger und Tempo","Leistungsverbesserung","Analyse von Mikrodiensten","Fehlerverfolgung"],"pt":["Visibilidade de fluxo de solicitação em microsserviços","Implementação com Jaeger e Tempo","Melhoria da depuração e monitoramento","Suporte a aplicações distribuídas","Análise de desempenho e otimização"],"ru":["Видимость потока запросов в микросервисах","Реализация с Jaeger и Tempo","Улучшение отладки и мониторинга","Поддержка распределённых приложений","Анализ производительности и оптимизация"],"ar":["رؤية تدفق الطلب في الخدمات المصغرة","تنفيذ مع Jaeger و Tempo","تحسين التصحيح ومراقبة الأداء","دعم التطبيقات الموزعة","تحليل الأداء وتحسينه"]},"keywords":{"zh":["分布式追踪","微服务架构","Jaeger","Tempo","请求流可见性","分散トレーシング"],"ja":["分散トレーシング","マイクロサービスアーキテクチャ","Jaeger","Tempo","リクエストフロー可視性","トレーシング"],"ko":["분산 트레이싱","마이크로 서비스 아키텍처","Jaeger","Tempo","요청 흐름 가시성","트레이싱"],"es":["rastreo distribuido","microservicios","Jaeger","Tempo","visibilidad de flujo de solicitudes","rendimiento","desarrollo de software"],"fr":["traçage distribué","microservices","Jaeger","Tempo","visibilité du flux de requêtes","performances","développement de logiciels"],"de":["verteilte Ablaufverfolgung","Mikrodienste","Jaeger","Tempo","Sichtbarkeit des Anforderungsflusses","Leistung","Softwareentwicklung"],"pt":["rastreio distribuído","Jaeger","Tempo","microsserviços","visibilidade de fluxo de solicitação","depuração","monitoramento","aplicações distribuídas"],"ru":["распределённое трассирование","Jaeger","Tempo","микросервисы","видимость потока запросов","отладка","мониторинг","распределённые приложения"],"ar":["التحديد التوزيعي","Jaeger","Tempo","الخدمات المصغرة","رؤية تدفق الطلب","التصحيح","مراقبة الأداء","التطبيقات الموزعة"]}},"owner":"sickn33","repo":"antigravity-awesome-skills","repoPath":"sickn33/antigravity-awesome-skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.395Z","topics":[],"category":"community","skillMd":{"name":"distributed-tracing","description":"Implement distributed tracing with Jaeger and Tempo to track requests across microservices and identify performance bottlenecks. Use when debugging microservices, analyzing request flows, or implementing observability for distributed systems.","bodyPreview":"# Distributed Tracing\n\nImplement distributed tracing with Jaeger and Tempo for request flow visibility across microservices.\n\n## Do not use this skill when\n\n- The task is unrelated to distributed tracing\n- You need a different domain or tool outside this scope\n\n## Instructions\n\n- Clarify goals, constraints, and required inputs.\n- Apply relevant best practices and validate outcomes.\n- Provide actionable steps and verification.\n- If detailed examples are required, open `resources/implementation-pl","body":"# Distributed Tracing\n\nImplement distributed tracing with Jaeger and Tempo for request flow visibility across microservices.\n\n## Do not use this skill when\n\n- The task is unrelated to distributed tracing\n- You need a different domain or tool outside this scope\n\n## Instructions\n\n- Clarify goals, constraints, and required inputs.\n- Apply relevant best practices and validate outcomes.\n- Provide actionable steps and verification.\n- If detailed examples are required, open `resources/implementation-playbook.md`.\n\n## Purpose\n\nTrack requests across distributed systems to understand latency, dependencies, and failure points.\n\n## Use this skill when\n\n- Debug latency issues\n- Understand service dependencies\n- Identify bottlenecks\n- Trace error propagation\n- Analyze request paths\n\n## Distributed Tracing Concepts\n\n### Trace Structure\n```\nTrace (Request ID: abc123)\n  ↓\nSpan (frontend) [100ms]\n  ↓\nSpan (api-gateway) [80ms]\n  ├→ Span (auth-service) [10ms]\n  └→ Span (user-service) [60ms]\n      └→ Span (database) [40ms]\n```\n\n### Key Components\n- **Trace** - End-to-end request journey\n- **Span** - Single operation within a trace\n- **Context** - Metadata propagated between services\n- **Tags** - Key-value pairs for filtering\n- **Logs** - Timestamped events within a span\n\n## Jaeger Setup\n\n### Kubernetes Deployment\n\n```bash\n# Deploy Jaeger Operator\nkubectl create namespace observability\nkubectl create -f https://github.com/jaegertracing/jaeger-operator/releases/download/v1.51.0/jaeger-operator.yaml -n observability\n\n# Deploy Jaeger instance\nkubectl apply -f - <<EOF\napiVersion: jaegertracing.io/v1\nkind: Jaeger\nmetadata:\n  name: jaeger\n  namespace: observability\nspec:\n  strategy: production\n  storage:\n    type: elasticsearch\n    options:\n      es:\n        server-urls: http://elasticsearch:9200\n  ingress:\n    enabled: true\nEOF\n```\n\n### Docker Compose\n\n```yaml\nversion: ''3.8''\nservices:\n  jaeger:\n    image: jaegertracing/all-in-one:latest\n    ports:\n      - \"5775:5775/udp\"\n      - \"6831:6831/udp\"\n      - \"6832:6832/udp\"\n      - \"5778:5778\"\n      - \"16686:16686\"  # UI\n      - \"14268:14268\"  # Collector\n      - \"14250:14250\"  # gRPC\n      - \"9411:9411\"    # Zipkin\n    environment:\n      - COLLECTOR_ZIPKIN_HOST_PORT=:9411\n```\n\n**Reference:** See `references/jaeger-setup.md`\n\n## Application Instrumentation\n\n### OpenTelemetry (Recommended)\n\n#### Python (Flask)\n```python\nfrom opentelemetry import trace\nfrom opentelemetry.exporter.jaeger.thrift import JaegerExporter\nfrom opentelemetry.sdk.resources import SERVICE_NAME, Resource\nfrom opentelemetry.sdk.trace import TracerProvider\nfrom opentelemetry.sdk.trace.export import BatchSpanProcessor\nfrom opentelemetry.instrumentation.flask import FlaskInstrumentor\nfrom flask import Flask\n\n# Initialize tracer\nresource = Resource(attributes={SERVICE_NAME: \"my-service\"})\nprovider = TracerProvider(resource=resource)\nprocessor = BatchSpanProcessor(JaegerExporter(\n    agent_host_name=\"jaeger\",\n    agent_port=6831,\n))\nprovider.add_span_processor(processor)\ntrace.set_tracer_provider(provider)\n\n# Instrument Flask\napp = Flask(__name__)\nFlaskInstrumentor().instrument_app(app)\n\n@app.route(''/api/users'')\ndef get_users():\n    tracer = trace.get_tracer(__name__)\n\n    with tracer.start_as_current_span(\"get_users\") as span:\n        span.set_attribute(\"user.count\", 100)\n        # Business logic\n        users = fetch_users_from_db()\n        return {\"users\": users}\n\ndef fetch_users_from_db():\n    tracer = trace.get_tracer(__name__)\n\n    with tracer.start_as_current_span(\"database_query\") as span:\n        span.set_attribute(\"db.system\", \"postgresql\")\n        span.set_attribute(\"db.statement\", \"SELECT * FROM users\")\n        # Database query\n        return query_database()\n```\n\n#### Node.js (Express)\n```javascript\nconst { NodeTracerProvider } = require(''@opentelemetry/sdk-trace-node'');\nconst { JaegerExporter } = require(''@opentelemetry/exporter-jaeger'');\nconst { BatchSpanProcessor } = require(''@opentelemetry/sdk-trace-base'');\nconst { registerInstrumentations } = require(''@opentelemetry/instrumentation'');\nconst { HttpInstrumentation } = require(''@opentelemetry/instrumentation-http'');\nconst { ExpressInstrumentation } = require(''@opentelemetry/instrumentation-express'');\n\n// Initialize tracer\nconst provider = new NodeTracerProvider({\n  resource: { attributes: { ''service.name'': ''my-service'' } }\n});\n\nconst exporter = new JaegerExporter({\n  endpoint: ''http://jaeger:14268/api/traces''\n});\n\nprovider.addSpanProcessor(new BatchSpanProcessor(exporter));\nprovider.register();\n\n// Instrument libraries\nregisterInstrumentations({\n  instrumentations: [\n    new HttpInstrumentation(),\n    new ExpressInstrumentation(),\n  ],\n});\n\nconst express = require(''express'');\nconst app = express();\n\napp.get(''/api/users'', async (req, res) => {\n  const tracer = trace.getTracer(''my-service'');\n  const span = tracer.startSpan(''get_users'');\n\n  try {\n    const users = await fetchUsers();\n    span.setAttributes({ ''user.count'': users.length });\n    res.json({ users });\n  } finally {\n    span.end();\n  }\n});\n```\n\n#### Go\n```go\npackage main\n\nimport (\n    \"context\"\n    \"go.opentelemetry.io/otel\"\n    \"go.opentelemetry.io/otel/exporters/jaeger\"\n    \"go.opentelemetry.io/otel/sdk/resource\"\n    sdktrace \"go.opentelemetry.io/otel/sdk/trace\"\n    semconv \"go.opentelemetry.io/otel/semconv/v1.4.0\"\n)\n\nfunc initTracer() (*sdktrace.TracerProvider, error) {\n    exporter, err := jaeger.New(jaeger.WithCollectorEndpoint(\n        jaeger.WithEndpoint(\"http://jaeger:14268/api/traces\"),\n    ))\n    if err != nil {\n        return nil, err\n    }\n\n    tp := sdktrace.NewTracerProvider(\n        sdktrace.WithBatcher(exporter),\n        sdktrace.WithResource(resource.NewWithAttributes(\n            semconv.SchemaURL,\n            semconv.ServiceNameKey.String(\"my-service\"),\n        )),\n    )\n\n    otel.SetTracerProvider(tp)\n    return tp, nil\n}\n\nfunc getUsers(ctx context.Context) ([]User, error) {\n    tracer := otel.Tracer(\"my-service\")\n    ctx, span := tracer.Start(ctx, \"get_users\")\n    defer span.End()\n\n    span.SetAttributes(attribute.String(\"user.filter\", \"active\"))\n\n    users, err := fetchUsersFromDB(ctx)\n    if err != nil {\n        span.RecordError(err)\n        return nil, err\n    }\n\n    span.SetAttributes(attribute.Int(\"user.count\", len(users)))\n    return users, nil\n}\n```\n\n**Reference:** See `references/instrumentation.md`\n\n## Context Propagation\n\n### HTTP Headers\n```\ntraceparent: 00-0af7651916cd43dd8448eb211c80319c-b7ad6b7169203331-01\ntracestate: congo=t61rcWkgMzE\n```\n\n### Propagation in HTTP Requests\n\n#### Python\n```python\nfrom opentelemetry.propagate import inject\n\nheaders = {}\ninject(headers)  # Injects trace context\n\nresponse = requests.get(''http://downstream-service/api'', headers=headers)\n```\n\n#### Node.js\n```javascript\nconst { propagation } = require(''@opentelemetry/api'');\n\nconst headers = {};\npropagation.inject(context.active(), headers);\n\naxios.get(''http://downstream-service/api'', { headers });\n```\n\n## Tempo Setup (Grafana)\n\n### Kubernetes Deployment\n\n```yaml\napiVersion: v1\nkind: ConfigMap\nmetadata:\n  name: tempo-config\ndata:\n  tempo.yaml: |\n    server:\n      http_listen_port: 3200\n\n    distributor:\n      receivers:\n        jaeger:\n          protocols:\n            thrift_http:\n            grpc:\n        otlp:\n          protocols:\n            http:\n            grpc:\n\n    storage:\n      trace:\n        backend: s3\n        s3:\n          bucket: tempo-traces\n          endpoint: s3.amazonaws.com\n\n    querier:\n      frontend_worker:\n        frontend_address: tempo-query-frontend:9095\n---\napiVersion: apps/v1\nkind: Deployment\nmetadata:\n  name: tempo\nspec:\n  replicas: 1\n  template:\n    spec:\n      containers:\n      - name: tempo\n        image: grafana/tempo:latest\n        args:\n          - -config.file=/etc/tempo/tempo.yaml\n        volumeMounts:\n        - name: config\n          mountPath: /etc/tempo\n      volumes:\n      - name: config\n        configMap:\n          name: tempo-config\n```\n\n**Reference:** See `assets/jaeger-config.yaml.template`\n\n## Sampling Strategies\n\n### Probabilistic Sampling\n```yaml\n# Sample 1% of traces\nsampler:\n  type: probabilistic\n  param: 0.01\n```\n\n### Rate Limiting Sampling\n```yaml\n# Sample max 100 traces per second\nsampler:\n  type: ratelimiting\n  param: 100\n```\n\n### Adaptive Sampling\n```python\nfrom opentelemetry.sdk.trace.sampling import ParentBased, TraceIdRatioBased\n\n# Sample based on trace ID (deterministic)\nsampler = ParentBased(root=TraceIdRatioBased(0.01))\n```\n\n## Trace Analysis\n\n### Finding Slow Requests\n\n**Jaeger Query:**\n```\nservice=my-service\nduration > 1s\n```\n\n### Finding Errors\n\n**Jaeger Query:**\n```\nservice=my-service\nerror=true\ntags.http.status_code >= 500\n```\n\n### Service Dependency Graph\n\nJaeger automatically generates service dependency graphs showing:\n- Service relationships\n- Request rates\n- Error rates\n- Average latencies\n\n## Best Practices\n\n1. **Sample appropriately** (1-10% in production)\n2. **Add meaningful tags** (user_id, request_id)\n3. **Propagate context** across all service boundaries\n4. **Log exceptions** in spans\n5. **Use consistent naming** for operations\n6. **Monitor tracing overhead** (<1% CPU impact)\n7. **Set up alerts** for trace errors\n8. **Implement distributed context** (baggage)\n9. **Use span events** for important milestones\n10. **Document instrumentation** standards\n\n## Integration with Logging\n\n### Correlated Logs\n```python\nimport logging\nfrom opentelemetry import trace\n\nlogger = logging.getLogger(__name__)\n\ndef process_request():\n    span = trace.get_current_span()\n    trace_id = span.get_span_context().trace_id\n\n    logger.info(\n        \"Processing request\",\n        extra={\"trace_id\": format(trace_id, ''032x'')}\n    )\n```\n\n## Troubleshooting\n\n**No traces appearing:**\n- Check collector endpoint\n- Verify network connectivity\n- Check sampling configuration\n- Review application logs\n\n**High latency overhead:**\n- Reduce sampling rate\n- Use batch span processor\n- Check exporter configuration\n\n## Reference Files\n\n- `references/jaeger-setup.md` - Jaeger installation\n- `references/instrumentation.md` - Instrumentation patterns\n- `assets/jaeger-config.yaml.template` - Jaeger configuration\n\n## Related Skills\n\n- `prometheus-configuration` - For metrics\n- `grafana-dashboards` - For visualization\n- `slo-implementation` - For latency SLOs\n"},"lastSynced":"2026-02-18T02:15:12.966Z","agentAnalysis":{"suitability":{"en":"Ideal for Microservice Agents requiring visibility into request flows across services using Jaeger and Tempo for distributed tracing.","zh":"适用于需要跨服务查看请求流的微服务代理，使用Jaeger和Tempo进行分布式追踪。","ja":"JaegerとTempoを使用した分散トレーシングにより、サービス間のリクエストフローを可視化する必要があるマイクロサービスエージェントに適しています。","ko":"분산 추적을 위해 Jaeger와 Tempo를 사용하여 서비스 간 요청 흐름을 볼 수 있는 마이크로 서비스 에이전트에 적합합니다.","es":"Ideal para Agentes de Microservicio que requieren visibilidad en los flujos de solicitudes a través de servicios que utilizan Jaeger y Tempo para trazado distribuido.","fr":"Idéal pour les Agents de Microservice nécessitant une visibilité dans les flux de requêtes à travers les services utilisant Jaeger et Tempo pour le traçage distribué.","de":"Ideal für Microservice-Agents, die Sichtbarkeit in den Anforderungsflüssen über Dienste hinweg benötigen, die Jaeger und Tempo für verteilte Nachverfolgung verwenden.","pt":"Ideal para Agentes de Microsserviços que exigem visibilidade em fluxos de solicitação em serviços que utilizam Jaeger e Tempo para rastreamento distribuído.","ru":"Идеально подходит для агентов микросервисов, требующих видимости потоков запросов через службы с использованием Jaeger и Tempo для распределенного трассирования.","ar":"مثالي للوكلاء ميكروسيرفيس الذين يحتاجون إلى رؤية تدفقات الطلب عبر الخدمات باستخدام Jaeger و Tempo للتعقب الموزع."},"recommendation":{"en":"Empowers agents to implement distributed tracing for request flow visibility across microservices, leveraging Jaeger and Tempo for enhanced observability and debugging capabilities, including support for microservice architectures and request flow analysis.","zh":"赋予代理实现分布式追踪以查看微服务间的请求流，利用Jaeger和Tempo增强可观察性和调试能力，包括对微服务架构和请求流分析的支持。","ja":"エージェントに、マイクロサービス間のリクエストフローを可視化するための分散トレーシングを実装する力を与え、JaegerとTempoを利用して可観測性とデバッグ機能を強化し、マイクロサービスアーキテクチャとリクエストフロー分析をサポートします。","ko":"분산 추적을 통해 마이크로 서비스 간의 요청 흐름을 볼 수 있는 에이전트를 구현할 수 있도록 하며, Jaeger와 Tempo를 사용하여 관찰 가능성과 디버깅 기능을 강화하고, 마이크로 서비스 아키텍처 및 요청 흐름 분석을 지원합니다.","es":"Habilita a los agentes a implementar un trazado distribuido para la visibilidad del flujo de solicitudes en microservicios, aprovechando Jaeger y Tempo para mejorar las capacidades de observabilidad y depuración, incluyendo soporte para arquitecturas de microservicios y análisis de flujos de solicitudes.","fr":"Permet aux agents de mettre en œuvre un traçage distribué pour la visibilité du flux de requêtes entre les microservices, en exploitant Jaeger et Tempo pour améliorer les capacités d''observabilité et de débogage, y compris le support pour les architectures de microservices et l''analyse des flux de requêtes.","de":"Ermächtigt die Agents, verteilte Nachverfolgung für die Sichtbarkeit des Anforderungsflusses in Microdiensten umzusetzen, indem sie Jaeger und Tempo für verbesserte Beobachtbarkeits- und Debugging-Funktionen nutzen, einschließlich Unterstützung für Microdienst-Architekturen und Anforderungsflussanalyse.","pt":"Habilita os agentes a implementar rastreamento distribuído para visibilidade do fluxo de solicitação em microsserviços, aproveitando Jaeger e Tempo para capacidades de observabilidade e depuração aprimoradas, incluindo suporte a arquiteturas de microsserviços e análise de fluxo de solicitação.","ru":"Наделяет агентов возможностью реализовать распределенное трассирование для видимости потоков запросов через микросервисы, используя Jaeger и Tempo для расширенных возможностей наблюдаемости и отладки, включая поддержку архитектур микросервисов и анализ потоков запросов.","ar":"يمنح الوكلاء القدرة على تنفيذ التعقب الموزع لرؤية تدفق الطلب عبر ميكروسيرفيس، مستفيداً من Jaeger و Tempo لتحسين القدرات على المراقبة وإصلاح الأعطال، بما في ذلك الدعم للعمارة ميكروسيرفيس وتحليل تدفق الطلب."},"useCases":{"en":["Implementing distributed tracing for microservice architectures","Debugging request flows across multiple services","Analyzing performance bottlenecks in distributed systems"],"zh":["为微服务架构实现分布式追踪","调试多个服务间的请求流","分析分布式系统中的性能瓶颈"],"ja":["マイクロサービスアーキテクチャのための分散トレーシングの実装","複数サービス間のリクエストフローのデバッグ","分散システムのパフォーマンスボトルネックの分析"],"ko":["마이크로 서비스 아키텍처를 위한 분산 추적 구현","複数 서비스 간의 요청 흐름 디버깅","분산 시스템의 성능 병목 현상 분석"],"es":["Implementar un trazado distribuido para arquitecturas de microservicio","Depurar flujos de solicitudes a través de varios servicios","Analizar cuellos de botella de rendimiento en sistemas distribuidos"],"fr":["Mettre en œuvre un traçage distribué pour les architectures de microservice","Déboguer les flux de requêtes à travers plusieurs services","Analyser les goulots d''étranglement de performance dans les systèmes distribués"],"de":["Verteilte Nachverfolgung für Microdienst-Architekturen implementieren","Anforderungsflüsse über mehrere Dienste hinweg debuggen","Leistungsbottlenecks in verteilten Systemen analysieren"],"pt":["Implementação de rastreamento distribuído para arquiteturas de microsserviços","Depuração de fluxos de solicitação em vários serviços","Análise de gargalos de desempenho em sistemas distribuídos"],"ru":["Реализация распределенного трассирования для архитектур микросервисов","Отладка потоков запросов через несколько служб","Анализ узких мест производительности в распределенных системах"],"ar":["تنفيذ التعقب الموزع للعمارة ميكروسيرفيس","تصحيح أعطال تدفق الطلب عبر خدمات متعددة","تحليل معوقات الأداء في الأنظمة الموزعة"]},"limitations":{"en":["Requires Jaeger or Tempo setup","Limited to distributed tracing use cases","May require additional configuration for non-microservice architectures"],"zh":["需要Jaeger或Tempo设置","仅限分布式追踪用例","可能需要非微服务架构的额外配置"],"ja":["JaegerまたはTempoの設定が必要","分散トレーシングの用途に限定","非マイクロサービスアーキテクチャでは追加の設定が必要になる場合がある"],"ko":["Jaeger 또는 Tempo 설정이 필요합니다.","분산 추적 사용 사례로 제한됨","비 마이크로 서비스 아키텍처의 경우 추가 구성이 필요할 수 있음"],"es":["Requiere configuración de Jaeger o Tempo","Limitado a casos de uso de trazado distribuido","Puede requerir configuración adicional para arquitecturas no de microservicio"],"fr":["Nécessite une configuration de Jaeger ou Tempo","Limité aux cas d''utilisation de traçage distribué","Peut nécessiter une configuration supplémentaire pour les architectures non de microservice"],"de":["Jaeger- oder Tempo-Setup erfordert","Begrenzt auf Anwendungsfälle für verteilte Nachverfolgung","Kann für Nicht-Microdienst-Architekturen zusätzliche Konfiguration erfordern"],"pt":["Exige configuração do Jaeger ou Tempo","Limitado a casos de uso de rastreamento distribuído","Pode exigir configuração adicional para arquiteturas não microsserviços"],"ru":["Требует настройки Jaeger или Tempo","Ограничен до случаев использования распределенного трассирования","Может потребовать дополнительной настройки для архитектур, не являющихся микросервисами"],"ar":["يتطلب إعداد Jaeger أو Tempo","محدود لcases استخدام التعقب الموزع","يمكن أن يتطلب إعدادا إضافيا للعمارة غير ميكروسيرفيس"]},"version":3},"qualityScore":80}');
