INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ancoleman/ai-design-components/managing-vulnerabilities', 'community', 'ancoleman', 'ai-design-components', 'ancoleman/ai-design-components', 'managing-vulnerabilities', 0, 0, 80, '2026-02-18T01:08:43.397Z', '2026-02-18T02:32:28.297Z', NULL, '{"id":"ancoleman/ai-design-components/managing-vulnerabilities","name":"managing-vulnerabilities","description":{"zh":"该技能提供了漏洞管理的综合解决方案，包括多层扫描、SBOM生成和风险优先级","ja":"このスキルは、脆弱性管理のための総合的なソリューションを提供し、多層スキャン、SBOM生成、リスク優先順位付けを含む","ko":"이 스킬은 취약성 관리를 위한 종합적인 솔루션을 제공하며, 다중 계층 스캔, SBOM 생성 및 위험 우선순위 지정 등을 포함","es":"Gestiona vulnerabilidades con Claude, implementando flujos de detección y remediación en contenedores y aplicaciones","fr":"Gérez les vulnérabilités avec Claude, en mettant en œuvre des flux de détection et de remédiation dans des conteneurs et des applications","de":"Verwalten Sie Schwachstellen mit Claude, indem Sie umfassende Schwachstellen- und Risikomanagement-Workflows in Containern und Anwendungen implementieren","en":"Comprehensive UI/UX and Backend component design skills for AI-assisted development with Claude"},"seo":{"title":{"zh":"漏洞管理技能：全面检测和修复","ja":"脆弱性管理スキル：総合的な検出と修復","ko":"취약성 관리 스킬: 종합적인 탐지 및 수정","es":"Gestión de vulnerabilidades con Claude","fr":"Gestion des vulnérabilités avec Claude","de":"Verwaltung von Schwachstellen mit Claude","en":"managing-vulnerabilities"},"description":{"zh":"该技能提供了漏洞管理的综合解决方案，包括多层扫描、SBOM生成和风险优先级","ja":"このスキルは、脆弱性管理のための総合的なソリューションを提供し、多層スキャン、SBOM生成、リスク優先順位付けを含む","ko":"이 스킬은 취약성 관리를 위한 종합적인 솔루션을 제공하며, 다중 계층 스캔, SBOM 생성 및 위험 우선순위 지정 등을 포함","es":"Gestiona vulnerabilidades con Claude, implementando flujos de detección y remediación en contenedores y aplicaciones","fr":"Gérez les vulnérabilités avec Claude, en mettant en œuvre des flux de détection et de remédiation dans des conteneurs et des applications","de":"Verwalten Sie Schwachstellen mit Claude, indem Sie umfassende Schwachstellen- und Risikomanagement-Workflows in Containern und Anwendungen implementieren","en":"Comprehensive UI/UX and Backend component design skills for AI-assisted development with Claude"},"definition":{"en":"Comprehensive UI/UX and Backend component design skills for AI-assisted development with Claude"},"features":{"zh":["多层扫描策略","SBOM生成（CycloneDX和SPDX）","风险优先级使用CVSS/EPSS/KEV","CI/CD安全门控模式","漏洞检测和修复工作流"],"ja":["多層スキャン戦略","SBOM生成（CycloneDXとSPDX）","リスク優先順位付け使用CVSS/EPSS/KEV","CI/CDセキュリティゲートパターン","脆弱性検出と修復のワークフロー"],"ko":["다중 계층 스캔 전략","SBOM 생성（CycloneDX 및 SPDX）","위험 우선순위 지정 사용 CVSS/EPSS/KEV","CI/CD 보안 게이트 패턴","취약성 탐지 및 수정 워크플로우"],"es":["Detección de vulnerabilidades en contenedores y código fuente","Generación de Software Bills of Materials (SBOMs)","Priorización basada en riesgos usando CVSS/EPSS/KEV","Integración con pipelines de CI/CD","Análisis de dependencias y aplicaciones en ejecución"],"fr":["Détection de vulnérabilités dans des conteneurs et du code source","Génération de factures de matériel logiciel (SBOMs)","Priorisation basée sur les risques à l''aide de CVSS/EPSS/KEV","Intégration avec des pipelines de CI/CD","Analyse de dépendances et d''applications en cours d''exécution"],"de":["Schwachstellen-Erkennung in Containern und Quellcode","Erstellung von Software-Bills-of-Materials (SBOMs)","Risikobasierte Priorisierung mit CVSS/EPSS/KEV","Integration in CI/CD-Pipelines","Analyse von Abhängigkeiten und laufenden Anwendungen"]},"keywords":{"zh":["漏洞管理","安全扫描","SBOM生成","风险优先级","CI/CD安全","软件安全","系统安全","漏洞检测","漏洞修复"],"ja":["脆弱性管理","セキュリティスキャン","SBOM生成","リスク優先順位付け","CI/CDセキュリティ","ソフトウェアセキュリティ","システムセキュリティ","脆弱性検出","脆弱性修復"],"ko":["취약성 관리","보안 스캔","SBOM 생성","위험 우선순위 지정","CI/CD 보안","소프트웨어 보안","시스템 보안","취약성 탐지","취약성 수정"],"es":["gestión de vulnerabilidades","seguridad de aplicaciones","detección de vulnerabilidades","SBOM","CVSS","EPSS","KEV","CI/CD","seguridad en la nube"],"fr":["gestion des vulnérabilités","sécurité des applications","détection de vulnérabilités","SBOM","CVSS","EPSS","KEV","CI/CD","sécurité dans le cloud"],"de":["Schwachstellen-Verwaltung","Anwendungssicherheit","Schwachstellen-Erkennung","SBOM","CVSS","EPSS","KEV","CI/CD","Cloud-Sicherheit"]}},"owner":"ancoleman","repo":"ai-design-components","repoPath":"ancoleman/ai-design-components","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.397Z","topics":[],"category":"community","skillMd":{"name":"managing-vulnerabilities","description":"Implementing multi-layer security scanning (container, SAST, DAST, SCA, secrets), SBOM generation, and risk-based vulnerability prioritization in CI/CD pipelines. Use when building DevSecOps workflows, ensuring compliance, or establishing security gates for container deployments.","bodyPreview":"# Vulnerability Management\n\nImplement comprehensive vulnerability detection and remediation workflows across containers, source code, dependencies, and running applications. This skill covers multi-layer scanning strategies, SBOM generation (CycloneDX and SPDX), risk-based prioritization using CVSS/EPSS/KEV, and CI/CD security gate patterns.\n\n## When to Use This Skill\n\nInvoke this skill when:\n\n- Building security scanning into CI/CD pipelines\n- Generating Software Bills of Materials (SBOMs) for","body":"# Vulnerability Management\n\nImplement comprehensive vulnerability detection and remediation workflows across containers, source code, dependencies, and running applications. This skill covers multi-layer scanning strategies, SBOM generation (CycloneDX and SPDX), risk-based prioritization using CVSS/EPSS/KEV, and CI/CD security gate patterns.\n\n## When to Use This Skill\n\nInvoke this skill when:\n\n- Building security scanning into CI/CD pipelines\n- Generating Software Bills of Materials (SBOMs) for compliance\n- Prioritizing vulnerability remediation using risk-based approaches\n- Implementing security gates (fail builds on critical vulnerabilities)\n- Scanning container images before deployment\n- Detecting secrets, misconfigurations, or code vulnerabilities\n- Establishing DevSecOps practices and automation\n- Meeting regulatory requirements (SBOM mandates, Executive Order 14028)\n\n## Multi-Layer Scanning Strategy\n\nVulnerability management requires scanning at multiple layers. Each layer detects different types of security issues.\n\n### Layer Overview\n\n**Container Image Scanning**\n- Detects vulnerabilities in OS packages, language dependencies, and binaries\n- Tools: Trivy (comprehensive), Grype (accuracy-focused), Snyk Container (commercial)\n- When: Every container build, base image selection, registry admission control\n\n**SAST (Static Application Security Testing)**\n- Analyzes source code for security flaws before runtime\n- Tools: Semgrep (fast, semantic), Snyk Code (developer-first), SonarQube (enterprise)\n- When: Every commit, PR checks, main branch protection\n\n**DAST (Dynamic Application Security Testing)**\n- Tests running applications for vulnerabilities (black-box testing)\n- Tools: OWASP ZAP (open-source), StackHawk (CI/CD native), Burp Suite (manual + automated)\n- When: Staging environment testing, API validation, authentication testing\n\n**SCA (Software Composition Analysis)**\n- Analyzes third-party dependencies for known vulnerabilities\n- Tools: Dependabot (GitHub native), Renovate (advanced), Snyk Open Source (commercial)\n- When: Every build, dependency updates, license audits\n\n**Secret Scanning**\n- Prevents secrets from being committed to source code\n- Tools: Gitleaks (fast, configurable), TruffleHog (entropy detection), GitGuardian (commercial)\n- When: Pre-commit hooks, repository scanning, CI/CD artifact checks\n\n### Quick Tool Selection\n\n```\nContainer Image → Trivy (default choice) OR Grype (accuracy focus)\nSource Code → Semgrep (open-source) OR Snyk Code (commercial)\nRunning Application → OWASP ZAP (open-source) OR StackHawk (CI/CD native)\nDependencies → Dependabot (GitHub) OR Renovate (advanced automation)\nSecrets → Gitleaks (open-source) OR GitGuardian (commercial)\n```\n\nFor detailed tool selection guidance, see `references/tool-selection.md`.\n\n## SBOM Generation\n\nSoftware Bills of Materials (SBOMs) provide a complete inventory of software components and dependencies. Required for compliance and security transparency.\n\n### CycloneDX vs. SPDX\n\n**CycloneDX** (Recommended for DevSecOps)\n- Security-focused, OWASP-maintained\n- Native vulnerability references\n- Fast, lightweight (JSON/XML/ProtoBuf)\n- Best for: DevSecOps pipelines, vulnerability tracking\n\n**SPDX** (Recommended for Legal/Compliance)\n- License compliance focus, ISO standard (ISO/IEC 5962:2021)\n- Comprehensive legal metadata\n- Government/defense preferred format\n- Best for: Legal teams, compliance audits, federal requirements\n\n### Generating SBOMs\n\n**With Trivy (CycloneDX or SPDX):**\n```bash\n# CycloneDX format (recommended for security)\ntrivy image --format cyclonedx --output sbom.json myapp:latest\n\n# SPDX format (for compliance)\ntrivy image --format spdx-json --output sbom-spdx.json myapp:latest\n\n# Scan SBOM (faster than re-scanning image)\ntrivy sbom sbom.json --severity HIGH,CRITICAL\n```\n\n**With Syft (high accuracy):**\n```bash\n# Generate CycloneDX\nsyft myapp:latest -o cyclonedx-json=sbom.json\n\n# Generate SPDX\nsyft myapp:latest -o spdx-json=sbom-spdx.json\n\n# Pipe to Grype for scanning\nsyft myapp:latest -o json | grype\n```\n\nFor comprehensive SBOM patterns and storage strategies, see `references/sbom-guide.md`.\n\n## Vulnerability Prioritization\n\nNot all vulnerabilities require immediate action. Prioritize based on actual risk using CVSS, EPSS, and KEV.\n\n### Modern Risk-Based Prioritization\n\n**Step 1: Gather Metrics**\n\n| Metric | Source | Purpose |\n|--------|--------|---------|\n| CVSS Base Score | NVD, vendor advisories | Vulnerability severity (0-10) |\n| EPSS Score | FIRST.org API | Exploitation probability (0-1) |\n| KEV Status | CISA KEV Catalog | Actively exploited CVEs |\n| Asset Criticality | Internal CMDB | Business impact if compromised |\n| Exposure | Network topology | Internet-facing vs. internal |\n\n**Step 2: Calculate Priority**\n\n```\nPriority Score = (CVSS × 0.3) + (EPSS × 100 × 0.3) + (KEV × 50) + (Asset × 0.2) + (Exposure × 0.2)\n\nKEV: 1 if in KEV catalog, 0 otherwise\nAsset: 1 (Critical), 0.7 (High), 0.4 (Medium), 0.1 (Low)\nExposure: 1 (Internet-facing), 0.5 (Internal), 0.1 (Isolated)\n```\n\n**Step 3: Apply SLA Tiers**\n\n| Priority | Criteria | SLA | Action |\n|----------|----------|-----|--------|\n| P0 - Critical | KEV + Internet-facing + Critical asset | 24 hours | Emergency patch immediately |\n| P1 - High | CVSS ≥ 9.0 OR (CVSS ≥ 7.0 AND EPSS ≥ 0.1) | 7 days | Prioritize in sprint, patch ASAP |\n| P2 - Medium | CVSS 7.0-8.9 OR EPSS ≥ 0.05 | 30 days | Normal sprint planning |\n| P3 - Low | CVSS 4.0-6.9, EPSS < 0.05 | 90 days | Backlog, maintenance windows |\n| P4 - Info | CVSS < 4.0 | No SLA | Track, address opportunistically |\n\n**Example: Log4Shell (CVE-2021-44228)**\n```\nCVSS: 10.0\nEPSS: 0.975 (97.5% exploitation probability)\nKEV: Yes (CISA catalog)\nAsset: Critical (payment API)\nExposure: Internet-facing\n\nPriority Score = (10 × 0.3) + (97.5 × 0.3) + 50 + (1 × 0.2) + (1 × 0.2) = 82.65\nResult: P0 - Critical (24-hour SLA)\n```\n\nFor complete prioritization framework and automation scripts, see `references/prioritization-framework.md`.\n\n## CI/CD Integration Patterns\n\n### Multi-Stage Security Pipeline\n\nImplement progressive security gates across pipeline stages:\n\n**Stage 1: Pre-Commit (Developer Workstation)**\n```yaml\nTools: Secret scanning (Gitleaks), SAST (Semgrep)\nThreshold: Block high-confidence secrets, critical SAST findings\nSpeed: < 10 seconds\n```\n\n**Stage 2: Pull Request (CI Pipeline)**\n```yaml\nTools: SAST, SCA, Secret scanning\nThreshold: No Critical/High vulnerabilities, no secrets\nSpeed: < 5 minutes\nAction: Block PR merge until fixed\n```\n\n**Stage 3: Build (CI Pipeline)**\n```yaml\nTools: Container scanning (Trivy), SBOM generation\nThreshold: No Critical vulnerabilities in production dependencies\nArtifacts: SBOM stored, scan results uploaded\nSpeed: < 2 minutes\nAction: Fail build on Critical findings\n```\n\n**Stage 4: Pre-Deployment (Staging)**\n```yaml\nTools: DAST, Integration tests\nThreshold: No Critical/High DAST findings\nSpeed: 10-30 minutes\nAction: Gate deployment to production\n```\n\n**Stage 5: Production (Runtime)**\n```yaml\nTools: Continuous scanning, runtime monitoring\nThreshold: Alert on new CVEs in deployed images\nAction: Alert security team, plan patching\n```\n\n### Example: GitHub Actions Multi-Stage Scan\n\n```yaml\nname: Security Scan Pipeline\n\non: [push, pull_request]\n\njobs:\n  secrets:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: trufflesecurity/trufflehog@main\n        with:\n          path: ./\n          extra_args: --only-verified\n\n  sast:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: semgrep/semgrep-action@v1\n        with:\n          config: p/security-audit\n\n  container:\n    runs-on: ubuntu-latest\n    needs: [secrets, sast]\n    steps:\n      - uses: actions/checkout@v4\n      - run: docker build -t myapp:${{ github.sha }} .\n\n      - uses: aquasecurity/trivy-action@master\n        with:\n          image-ref: myapp:${{ github.sha }}\n          format: sarif\n          output: trivy-results.sarif\n          severity: HIGH,CRITICAL\n          exit-code: 1\n\n      - name: Generate SBOM\n        run: |\n          trivy image --format cyclonedx \\\n            --output sbom.json myapp:${{ github.sha }}\n\n      - uses: actions/upload-artifact@v3\n        with:\n          name: sbom\n          path: sbom.json\n```\n\nFor complete CI/CD patterns (GitLab CI, Jenkins, Azure Pipelines), see `references/ci-cd-patterns.md`.\n\n## Container Scanning with Trivy\n\nTrivy is the recommended default for container scanning: comprehensive, fast, and CI/CD native.\n\n### Basic Usage\n\n```bash\n# Scan container image\ntrivy image alpine:latest\n\n# Scan with severity filter\ntrivy image --severity HIGH,CRITICAL alpine:latest\n\n# Fail on findings (CI/CD)\ntrivy image --exit-code 1 --severity HIGH,CRITICAL myapp:latest\n\n# Generate SBOM\ntrivy image --format cyclonedx --output sbom.json alpine:latest\n\n# Scan filesystem\ntrivy fs /path/to/project\n\n# Scan Kubernetes manifests\ntrivy config deployment.yaml\n```\n\n### Configuration (.trivy.yaml)\n\n```yaml\nseverity: HIGH,CRITICAL\nexit-code: 1\nignore-unfixed: true  # Only fail on fixable vulnerabilities\nvuln-type: os,library\nskip-dirs:\n  - node_modules\n  - vendor\nignorefile: .trivyignore\n```\n\n### Ignoring False Positives (.trivyignore)\n\n```\n# False positive\nCVE-2023-12345\n\n# Accepted risk with justification\nCVE-2023-67890  # Risk accepted: Not exploitable in our use case\n\n# Development dependency (not in production)\nCVE-2023-11111  # Dev dependency only\n```\n\n### GitHub Actions Integration\n\n```yaml\n- name: Trivy Scan\n  uses: aquasecurity/trivy-action@master\n  with:\n    image-ref: myapp:${{ github.sha }}\n    format: sarif\n    output: trivy-results.sarif\n    severity: HIGH,CRITICAL\n    exit-code: 1\n\n- name: Upload to GitHub Security\n  uses: github/codeql-action/upload-sarif@v2\n  if: always()\n  with:\n    sarif_file: trivy-results.sarif\n```\n\n## Alternative: Grype for Accuracy\n\nGrype focuses on minimal false positives and works with Syft for SBOM generation.\n\n**Important:** Use Grype v0.104.1 or later (credential disclosure CVE-2025-65965 patched in earlier versions).\n\n### Basic Usage\n\n```bash\n# Scan container image\ngrype alpine:latest\n\n# Scan with severity threshold\ngrype alpine:latest --fail-on high\n\n# Scan SBOM (faster)\ngrype sbom:./sbom.json\n\n# Syft + Grype workflow\nsyft alpine:latest -o json | grype --fail-on critical\n```\n\n### When to Use Grype\n\n- Projects sensitive to false positives\n- SBOM-first workflows (generate with Syft, scan with Grype)\n- Need second opinion validation\n- Anchore ecosystem users\n\nFor complete tool comparisons and selection criteria, see `references/tool-selection.md`.\n\n## Security Gates and Thresholds\n\n### Progressive Threshold Strategy\n\nBalance security and development velocity with progressive gates. Configure different thresholds for PR checks (fast, HIGH+CRITICAL), builds (comprehensive), and deployments (strict, CRITICAL only).\n\n### Policy-as-Code\n\nUse OPA (Open Policy Agent) for automated policy enforcement. Create policies to deny Critical vulnerabilities, enforce KEV catalog checks, and implement environment-specific rules.\n\nFor complete policy patterns, baseline detection, and OPA examples, see `references/policy-as-code.md`.\n\n## Remediation Workflows\n\n### Automated Remediation\n\nSet up automated workflows to scan daily, extract fixable vulnerabilities, update dependencies, and create remediation pull requests automatically.\n\n### SLA Tracking\n\nTrack vulnerability remediation against SLA targets (P0: 24 hours, P1: 7 days, P2: 30 days, P3: 90 days). Monitor overdue vulnerabilities and escalate as needed.\n\n### False Positive Management\n\nMaintain suppression files (.trivyignore) with documented justifications, review dates, and approval tracking. Implement workflows for false positive triage and approval.\n\nFor complete remediation workflows, SLA trackers, and automation scripts, see `references/remediation-workflows.md`.\n\n## Integration with Related Skills\n\n**building-ci-pipelines**\n- Add security stages to pipeline definitions\n- Configure artifacts for SBOM storage\n- Implement quality gates with vulnerability thresholds\n\n**secret-management**\n- Integrate secret scanning (Gitleaks, TruffleHog)\n- Automate secret rotation on detection\n- Use pre-commit hooks for prevention\n\n**infrastructure-as-code**\n- Scan Terraform and Kubernetes manifests with Trivy config\n- Detect misconfigurations before deployment\n- Enforce policy-as-code with OPA\n\n**security-hardening**\n- Apply remediation guidance from scan results\n- Select secure base images\n- Implement security best practices\n\n**compliance-frameworks**\n- Generate SBOMs for SOC2, ISO 27001 audits\n- Track vulnerability metrics for compliance reporting\n- Provide evidence for security controls\n\n## Quick Reference\n\n### Essential Commands\n\n```bash\n# Trivy: Scan image with severity filter\ntrivy image --severity HIGH,CRITICAL myapp:latest\n\n# Trivy: Generate SBOM\ntrivy image --format cyclonedx --output sbom.json myapp:latest\n\n# Trivy: Scan SBOM\ntrivy sbom sbom.json\n\n# Grype: Scan image\ngrype myapp:latest --fail-on high\n\n# Syft + Grype: SBOM workflow\nsyft myapp:latest -o json | grype\n\n# Gitleaks: Scan for secrets\ngitleaks detect --source . --verbose\n```\n\n### Common Patterns\n\n```bash\n# CI/CD: Fail build on Critical\ntrivy image --exit-code 1 --severity CRITICAL myapp:latest\n\n# Ignore unfixed vulnerabilities\ntrivy image --ignore-unfixed --severity HIGH,CRITICAL myapp:latest\n\n# Scan only OS packages\ntrivy image --vuln-type os myapp:latest\n\n# Skip specific directories\ntrivy fs --skip-dirs node_modules,vendor .\n```\n\n## Progressive Disclosure\n\nThis skill provides foundational vulnerability management patterns. For deeper topics:\n\n- **Tool Selection:** `references/tool-selection.md` - Complete decision frameworks\n- **SBOM Patterns:** `references/sbom-guide.md` - Generation, storage, consumption\n- **Prioritization:** `references/prioritization-framework.md` - CVSS/EPSS/KEV automation\n- **CI/CD Integration:** `references/ci-cd-patterns.md` - GitLab CI, Jenkins, Azure Pipelines\n- **Remediation:** `references/remediation-workflows.md` - SLA tracking, false positives\n- **Policy-as-Code:** `references/policy-as-code.md` - OPA examples, security gates\n\n**Working Examples:**\n- `examples/trivy/` - Trivy scanning patterns\n- `examples/grype/` - Grype + Syft workflows\n- `examples/ci-cd/` - Complete pipeline configurations\n- `examples/sbom/` - SBOM generation and management\n- `examples/prioritization/` - EPSS and KEV integration scripts\n\n**Automation Scripts:**\n- `scripts/vulnerability-report.sh` - Generate executive reports\n- `scripts/sla-tracker.sh` - Track remediation SLAs\n- `scripts/false-positive-manager.sh` - Manage suppression rules\n"},"lastSynced":"2026-02-18T02:32:28.297Z","agentAnalysis":{"suitability":{"en":"Ideal for Security-focused AI Agents like Claude needing advanced vulnerability detection and remediation capabilities","zh":"适合于需要高级漏洞检测和修复能力的安全性人工智能代理，如Claude","ja":"Claudeのような高度な脆弱性検出および修復機能を必要とするセキュリティに重点を置いたAIエージェントに適しています","ko":"클라우드와 같은 고급 취약점 탐지 및 수정 기능을 필요로 하는 보안 중심 인공지능 에이전트에 적합합니다","es":"Ideal para agentes de IA centrados en la seguridad como Claude que necesitan capacidades avanzadas de detección y remediación de vulnerabilidades","fr":"Idéal pour les agents IA axés sur la sécurité comme Claude nécessitant des capacités avancées de détection et de correction des vulnérabilités","de":"Ideal für sicherheitsfokussierte KI-Agenten wie Claude, die erweiterte Funktionen zur Schwachstellenerkennung und -behebung benötigen","pt":"Ideal para Agentes de IA com foco em Segurança, como Claude, que necessitam de capacidades avançadas de detecção e remediação de vulnerabilidades","ru":"Идеально подходит для агентов ИИ, ориентированных на безопасность, таких как Claude, требующих продвинутых возможностей обнаружения и устранения уязвимостей","ar":"المثالي لعميل الذكاء الاصطناعي الذي يركز على الأمن مثل كلود الذي يحتاج إلى قدرات متقدمة للكشف عن الثغرات وإصلاحها"},"recommendation":{"en":"Empowers agents to implement comprehensive vulnerability management workflows, utilizing multi-layer scanning strategies, SBOM generation with CycloneDX and SPDX, and risk-based prioritization using CVSS, EPSS, and KEV, directly integrating with CI/CD security gate patterns","zh":"赋予代理实施综合漏洞管理工作流的能力，利用多层扫描策略、CycloneDX和SPDX生成SBOM，并使用CVSS、EPSS和KEV进行风险基于优先级排序，直接集成到CI/CD安全门控模式","ja":"エージェントに、多層スキャン戦略、CycloneDXおよびSPDXを使用したSBOMの生成、CVSS、EPSS、KEVを使用したリスクベースの優先順位付けを活用した包括的な脆弱性管理ワークフローを実装する能力を付与し、CI/CDセキュリティゲートパターンに直接統合する","ko":"에이전트가 다층 스캔 전략, CycloneDX 및 SPDX를 사용한 SBOM 생성, CVSS, EPSS, KEV를 사용한 위험 기반 우선순위를 사용하여 종합적인 취약점 관리 워크플로를 구현할 수 있는 기능을 부여하고, CI/CD 보안 게이트 패턴에 직접 통합합니다","es":"Permite a los agentes implementar flujos de trabajo integrales de gestión de vulnerabilidades, utilizando estrategias de escaneo multicapa, generación de SBOM con CycloneDX y SPDX, y priorización basada en riesgos utilizando CVSS, EPSS y KEV, integrando directamente con patrones de puertas de seguridad de CI/CD","fr":"Permet aux agents de mettre en œuvre des flux de travail complets de gestion des vulnérabilités, utilisant des stratégies d''analyse multicouches, la génération de SBOM avec CycloneDX et SPDX, et la priorisation basée sur les risques utilisant CVSS, EPSS et KEV, s''intégrant directement avec les modèles de portes de sécurité CI/CD","de":"Ermöglicht Agenten die Implementierung umfassender Schwachstellenmanagement-Workflows unter Verwendung von Mehrschicht-Scanning-Strategien, SBOM-Generierung mit CycloneDX und SPDX sowie risikobasierter Priorisierung mit CVSS, EPSS und KEV, direkt integriert mit CI/CD-Sicherheitsgate-Mustern","pt":"Permite que os agentes implementem fluxos de trabalho de gerenciamento de vulnerabilidades abrangentes, utilizando estratégias de varredura em várias camadas, geração de SBOM com CycloneDX e SPDX, e priorização baseada em risco usando CVSS, EPSS e KEV, integrando-se diretamente com padrões de segurança de portas de CI/CD","ru":"Позволяет агентам реализовать комплексные рабочие процессы управления уязвимостями, используя многослойные стратегии сканирования, генерацию SBOM с помощью CycloneDX и SPDX, а также расстановку приоритетов на основе риска с использованием CVSS, EPSS и KEV, напрямую интегрируясь с шаблонами безопасности CI/CD","ar":"تمكّن الوكيل من تنفيذ سير عمل إدارة الثغرات الشاملة، باستخدام استراتيجيات المسح متعددة الطبقات، وتوليد فواتير البرامج SBOM باستخدام CycloneDX و SPDX، وتحديد الأولويات حسب المخاطر باستخدام CVSS و EPSS و KEV، والدمج المباشر مع أنماط بوابة الأمان CI/CD"},"useCases":{"en":["Automating vulnerability scanning in CI/CD pipelines","Generating Software Bills of Materials (SBOMs) for dependency management","Implementing risk-based prioritization for remediation efforts","Integrating security gate patterns into development workflows"],"zh":["在CI/CD管道中自动执行漏洞扫描","为依赖管理生成软件清单（SBOM）","为修复工作实施风险基于优先级排序","将安全门控模式集成到开发工作流中"],"ja":["CI/CDパイプラインでの脆弱性スキャンの自動化","依存関係管理のためのソフトウェアビルオ_MATERIAL（SBOM）の生成","修復作業のためのリスクベースの優先順位付けの実施","セキュリティゲートパターンの開発ワークフローへの統合"],"ko":["CI/CD 파이프라인에서 취약점 스캔 자동화","의존성 관리를 위한 소프트웨어 청구서(SBOM) 생성","수정 작업을 위한 위험 기반 우선순위 지정 구현","보안 게이트 패턴을 개발 워크플로에 통합"],"es":["Automatización del escaneo de vulnerabilidades en pipelines de CI/CD","Generación de Listas de Materiales de Software (SBOM) para la gestión de dependencias","Implementación de priorización basada en riesgos para esfuerzos de remediación","Integración de patrones de puertas de seguridad en flujos de trabajo de desarrollo"],"fr":["Automatisation de l''analyse des vulnérabilités dans les pipelines CI/CD","Génération de Listes de Matériels Logiciels (SBOM) pour la gestion des dépendances","Mise en œuvre d''une priorisation basée sur les risques pour les efforts de correction","Intégration de modèles de portes de sécurité dans les flux de travail de développement"],"de":["Automatisierung des Schwachstellenscans in CI/CD-Pipelines","Erstellung von Software-Bestandslisten (SBOM) für das Abhängigkeitsmanagement","Implementierung einer risikobasierten Priorisierung für Behebungsmaßnahmen","Integration von Sicherheitsgate-Mustern in Entwicklungs-Workflows"],"pt":["Automatizar a varredura de vulnerabilidades em pipelines de CI/CD","Gerar Faturas de Materiais de Software (SBOMs) para gerenciamento de dependências","Implementar priorização baseada em risco para esforços de remediação","Integrar padrões de segurança de portas em fluxos de trabalho de desenvolvimento"],"ru":["Автоматизировать сканирование уязвимостей в конвейерах CI/CD","Генерировать счета-фактуры программного обеспечения (SBOM) для управления зависимостями","Реализовать расстановку приоритетов на основе риска для усилий по исправлению","Интегрировать шаблоны безопасности в рабочие процессы разработки"],"ar":["تحويل مسح الثغرات تلقائيًا في خطوط أنابيب CI/CD","توليد فواتير البرامج SBOM لإدارة التبعيات","تنفيذ تحديد الأولويات حسب المخاطر للجهود التصالحية","دمج أنماط الأمان في سير العمل التطويرية"]},"limitations":{"en":["Requires integration with CI/CD pipelines","Dependent on CVSS, EPSS, and KEV for risk assessment","Limited to CycloneDX and SPDX for SBOM generation"],"zh":["需要与CI/CD管道集成","依赖于CVSS、EPSS和KEV进行风险评估","仅限于CycloneDX和SPDX进行SBOM生成"],"ja":["CI/CDパイプラインとの統合が必要","リスク評価にはCVSS、EPSS、KEVに依存","SBOMの生成にはCycloneDXとSPDXのみ"],"ko":["CI/CD 파이프라인과 통합해야 함","위험 평가에는 CVSS, EPSS, KEV에 의존","SBOM 생성에는 CycloneDX 및 SPDX만 제한"],"es":["Requiere integración con pipelines de CI/CD","Depende de CVSS, EPSS y KEV para la evaluación de riesgos","Limitado a CycloneDX y SPDX para la generación de SBOM"],"fr":["Nécessite une intégration avec les pipelines CI/CD","Dépend de CVSS, EPSS et KEV pour l''évaluation des risques","Limité à CycloneDX et SPDX pour la génération de SBOM"],"de":["Erfordert Integration in CI/CD-Pipelines","Abhängig von CVSS, EPSS und KEV für die Risikobewertung","Beschränkt auf CycloneDX und SPDX für die SBOM-Generierung"],"pt":["Exige integração com pipelines de CI/CD","Depende de CVSS, EPSS e KEV para avaliação de risco","Limitado a CycloneDX e SPDX para geração de SBOM"],"ru":["Требует интеграции с конвейерами CI/CD","Зависит от CVSS, EPSS и KEV для оценки риска","Ограничен CycloneDX и SPDX для генерации SBOM"],"ar":["يتطلب التكامل مع خطوط أنابيب CI/CD","يعتمد على CVSS و EPSS و KEV لتقييم المخاطر","محدود بـ CycloneDX و SPDX لتوليد فواتير البرامج SBOM"]},"version":3},"qualityScore":80}');
