INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fierzone/agent-skills-standard/Next.js Authentication', 'community', 'fierzone', 'agent-skills-standard', 'fierzone/agent-skills-standard', 'Next.js Authentication', 0, 0, 0, '2026-02-18T01:08:43.401Z', '2026-02-18T02:55:15.887Z', NULL, '{"id":"fierzone/agent-skills-standard/Next.js Authentication","name":"Next.js Authentication","description":{"zh":"Next.js , HttpOnly Cookies, ","ja":"Next.js, HttpOnly Cookies","ko":"Next.js, HttpOnly Cookies, ","es":"La autenticación en Next.js requiere el uso de cookies HttpOnly para almacenar tokens de forma segura","fr":"L''authentification dans Next.js nécessite l''utilisation de cookies HttpOnly pour stocker les jetons de manière sécurisée","de":"Die Authentifizierung in Next.js erfordert die Verwendung von HttpOnly-Cookies zum sicheren Speichern von Token","pt":"Autenticação Next.js é um conjunto de práticas para garantir a segurança dos tokens de autenticação em aplicativos Next.js.","ru":"Аутентификация Next.js — это набор практик для обеспечения безопасности токенов аутентификации в приложениях Next.js.","ar":"التحقق من الصحة في Next.js هو مجموعة من الممارسات لضمان أمان رموز التحقق من الصحة في تطبيقات Next.js.","en":""},"seo":{"title":{"zh":"Next.js ","ja":"Next.js","ko":"Next.js ","es":"Autenticación en Next.js","fr":"Authentification Next.js","de":"Next.js Authentifizierung","pt":"Autenticação Next.js: Melhores Práticas","ru":"Аутентификация Next.js: Лучшие Практики","ar":"التحقق من الصحة في Next.js: أفضل الممارسات","en":"Next.js Authentication"},"description":{"zh":"Next.js , HttpOnly Cookies, ","ja":"Next.js, HttpOnly Cookies","ko":"Next.js, HttpOnly Cookies, ","es":"La autenticación en Next.js requiere el uso de cookies HttpOnly para almacenar tokens de forma segura","fr":"L''authentification dans Next.js nécessite l''utilisation de cookies HttpOnly pour stocker les jetons de manière sécurisée","de":"Die Authentifizierung in Next.js erfordert die Verwendung von HttpOnly-Cookies zum sicheren Speichern von Token","pt":"Autenticação Next.js é um conjunto de práticas para garantir a segurança dos tokens de autenticação em aplicativos Next.js.","ru":"Аутентификация Next.js — это набор практик для обеспечения безопасности токенов аутентификации в приложениях Next.js.","ar":"التحقق من الصحة في Next.js هو مجموعة من الممارسات لضمان أمان رموز التحقق من الصحة في تطبيقات Next.js.","en":""},"definition":{"en":""},"features":{"zh":["HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure"],"ja":["HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure"],"ko":["HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure"],"es":["Almacenamiento de tokens con cookies HttpOnly","Lectura de tokens en componentes del servidor","Protección de rutas con middleware","Implementación de autenticación segura","Uso de cookies seguras con httpOnly y secure"],"fr":["Stockage de jetons avec des cookies HttpOnly","Lecture de jetons dans les composants serveur","Protection des routes avec un middleware","Implémentation d''une authentification sécurisée","Utilisation de cookies sécurisés avec httpOnly et secure"],"de":["Token-Speicherung mit HttpOnly-Cookies","Token-Lesevorgang in Server-Komponenten","Routen-Schutz mit Middleware","Implementierung einer sicheren Authentifizierung","Verwendung von sicheren Cookies mit httpOnly und secure"],"pt":["Armazenamento de tokens com HttpOnly Cookies","Leitura de tokens em Componentes de Servidor","Proteção de rotas com middleware","Configuração de cookies com httpOnly, secure e sameSite","Implementação de autenticação com tokens"],"ru":["Хранение токенов с помощью HttpOnly Cookies","Чтение токенов в Компонентах Сервера","Защита маршрутов с помощью middleware","Настройка куки с httpOnly, secure и sameSite","Реализация аутентификации с токенами"],"ar":["تخزين رموز التحقق من الصحة باستخدام HttpOnly Cookies","قراءة رموز التحقق من الصحة في مكونات الخادم","حماية المسارات باستخدام واجهة برمجة التطبيقات الوسيطة","تكوين ملفات تعريف الارتباط مع httpOnly و secure و sameSite","تنفيذ التحقق من الصحة باستخدام رموز التحقق من الصحة"]},"keywords":{"zh":["Next.js","HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure","token","authentication"],"ja":["Next.js","HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure","token","authentication"],"ko":["Next.js","HttpOnly Cookies","cookies().set()","cookies().get()","middleware","sameSite","secure","token","authentication"],"es":["autenticación next.js","httpOnly cookies","middleware","seguridad en next.js","almacenamiento de tokens","lectura de tokens","protección de rutas"],"fr":["authentification next.js","cookies httpOnly","middleware","sécurité dans next.js","stockage de jetons","lecture de jetons","protection des routes"],"de":["authentifizierung next.js","httpOnly-cookies","middleware","sicherheit in next.js","token-speicherung","token-lesevorgang","routen-schutz"],"pt":["autenticação next.js","httpOnly cookies","segurança de tokens","middleware de proteção","armazenamento de tokens","leitura de tokens","proteção de rotas"],"ru":["аутентификация next.js","httpOnly куки","безопасность токенов","middleware защиты","хранение токенов","чтение токенов","защита маршрутов"],"ar":["التحقق من الصحة في next.js","ملفات تعريف الارتباط httpOnly","أمان رموز التحقق من الصحة","واجهة برمجة التطبيقات الوسيطة للحماية","تخزين رموز التحقق من الصحة","قراءة رموز التحقق من الصحة","حماية المسارات"]}},"owner":"fierzone","repo":"agent-skills-standard","repoPath":"fierzone/agent-skills-standard","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.401Z","topics":[],"category":"community","skillMd":{"name":"Next.js Authentication","description":"Secure token storage (HttpOnly Cookies) and Middleware patterns.","bodyPreview":"# Authentication & Token Management\n\n## **Priority: P0 (CRITICAL)**\n\nUse **HttpOnly Cookies** for token storage. **Never** use LocalStorage.\n\n## Key Rules\n\n1. **Storage**: Use `cookies().set()` with `httpOnly: true`, `secure: true`, `sameSite: ''lax''`. (Reference: [Setting Tokens](references/auth-implementation.md))\n2. **Access**: Read tokens in Server Components via `cookies().get()`. (Reference: [Reading Tokens](references/auth-implementation.md))\n3. **Protection**: Guard routes in `middleware.","body":"# Authentication & Token Management\n\n## **Priority: P0 (CRITICAL)**\n\nUse **HttpOnly Cookies** for token storage. **Never** use LocalStorage.\n\n## Key Rules\n\n1. **Storage**: Use `cookies().set()` with `httpOnly: true`, `secure: true`, `sameSite: ''lax''`. (Reference: [Setting Tokens](references/auth-implementation.md))\n2. **Access**: Read tokens in Server Components via `cookies().get()`. (Reference: [Reading Tokens](references/auth-implementation.md))\n3. **Protection**: Guard routes in `middleware.ts` before rendering. (Reference: [Middleware Protection](references/auth-implementation.md))\n\n## Anti-Pattern: LocalStorage\n\n- **Security Risk**: Vulnerable to XSS.\n- **Performance Hit**: Incompatible with Server Components (RSC). Forces client hydration and causes layout shift.\n\n## Related Topics\n\ncommon/security-standards | server-components | app-router\n"},"lastSynced":"2026-02-18T02:55:15.887Z","agentAnalysis":{"suitability":{"en":"Ideal for Web Development Agents requiring secure Next.js authentication mechanisms","zh":"适合需要安全的 Next.js 身份验证机制的 Web 开发代理","ja":"セキュアな Next.js 認証メカニズムを必要とする Web 開発エージェントに最適","ko":"보안이 필요한 Next.js 인증 메커니즘을 사용하는 웹 개발 에이전트에 적합","es":"Ideal para agentes de desarrollo web que requieren mecanismos de autenticación seguros con Next.js","fr":"Idéal pour les agents de développement web nécessitant des mécanismes d''authentification sécurisés avec Next.js","de":"Ideal für Webentwicklungs-Agents, die sichere Next.js-Authentifizierungsmechanismen benötigen","pt":"Ideal para Agentes de Desenvolvimento Web que requerem mecanismos de autenticação seguros do Next.js","ru":"Идеально для агентов веб-разработки, требующих безопасных механизмов аутентификации Next.js","ar":"مثالي للوكلاء التطوير الويب الذين يحتاجون إلى آليات التحقق من الصلاحية آمنة من Next.js"},"recommendation":{"en":"Empowers agents to manage tokens securely using HttpOnly Cookies with options like httpOnly, secure, and sameSite set to ''lax'', while protecting routes through middleware, ensuring robust authentication and token management via cookies().set() and cookies().get() methods","zh":"赋予代理安全地管理令牌的能力，使用 HttpOnly Cookies，带有 httpOnly、secure 和 sameSite 设置为 ''lax'' 的选项，同时通过中间件保护路由，确保通过 cookies().set() 和 cookies().get() 方法进行强大的身份验证和令牌管理","ja":"HttpOnly Cookies を使用してトークンを安全に管理するエージェントの能力を付与します。httpOnly、secure、sameSite を ''lax'' に設定したオプションとともに、ミドルウェアを介してルートを保護し、cookies().set() と cookies().get() メソッドを介した強力な認証とトークン管理を保証します","ko":"HttpOnly 쿠키를 사용하여 토큰을 안전하게 관리할 수 있는 에이전트의 능력을 부여합니다. httpOnly, secure, sameSite를 ''lax''로 설정한 옵션과 함께 미들웨어를 통해 라우트를 보호하고, cookies().set() 및 cookies().get() 메서드를 통해 강력한 인증 및 토큰 관리를 보장합니다","es":"Capacita a los agentes para gestionar tokens de forma segura utilizando cookies HttpOnly con opciones como httpOnly, secure y sameSite establecido en ''lax'', mientras protege las rutas mediante middleware, garantizando una autenticación robusta y una gestión de tokens mediante los métodos cookies().set() y cookies().get()","fr":"Permet aux agents de gérer les jetons de manière sécurisée en utilisant des cookies HttpOnly avec des options comme httpOnly, secure et sameSite défini sur ''lax'', tout en protégeant les routes via un middleware, assurant une authentification robuste et une gestion des jetons via les méthodes cookies().set() et cookies().get()","de":"Ermöglicht Agents, Tokens sicher mit HttpOnly-Cookies zu verwalten, mit Optionen wie httpOnly, secure und sameSite auf ''lax'' gesetzt, während Routen durch Middleware geschützt werden, um eine robuste Authentifizierung und Token-Verwaltung über die Methoden cookies().set() und cookies().get() sicherzustellen","pt":"Habilita os agentes a gerenciar tokens de forma segura usando Cookies HttpOnly com opções como httpOnly, secure e sameSite definidas como ''lax'', enquanto protege rotas por meio de middleware, garantindo autenticação robusta e gerenciamento de tokens via métodos cookies().set() e cookies().get()","ru":"Предоставляет агентам возможность безопасно управлять токенами с помощью файлов cookie HttpOnly с опциями httpOnly, secure и sameSite, установленными на ''lax'', при этом защищая маршруты с помощью middleware, обеспечивая надежную аутентификацию и управление токенами через методы cookies().set() и cookies().get()","ar":"تمكين الوكلاء من إدارة الرموز الأمنية بشكل آمن باستخدام ملفات تعريف الارتباط HttpOnly مع خيارات مثل httpOnly و secure و sameSite معروضة على ''lax''، في حين حماية الطرق من خلال وسيط ، الضمان التحقق الصلاحية القوي وإدارة الرموز من خلال أساليب cookies().set() و cookies().get()"},"useCases":{"en":["Implementing secure token storage","Guarding routes with middleware protection","Reading tokens in Server Components"],"zh":["实现安全的令牌存储","使用中间件保护来保护路由","在服务器组件中读取令牌"],"ja":["セキュアなトークンストレージの実装","ミドルウェア保護を使用したルートの保護","サーバーコンポーネントでのトークンの読み取り"],"ko":["보안 토큰 저장 구현","미들웨어 보호를 사용한 라우트 보호","서버 컴포넌트에서 토큰 읽기"],"es":["Implementar almacenamiento seguro de tokens","Proteger rutas con protección de middleware","Leer tokens en Componentes de Servidor"],"fr":["Mettre en œuvre un stockage sécurisé des jetons","Protéger les routes avec une protection middleware","Lire les jetons dans les Composants Serveur"],"de":["Implementierung einer sicheren Tokenspeicherung","Schutz von Routen durch Middleware-Schutz","Lesen von Tokens in Serverkomponenten"],"pt":["Implementação de armazenamento de token seguro","Proteção de rotas com proteção de middleware","Leitura de tokens em Componentes de Servidor"],"ru":["Реализация безопасного хранения токенов","Защита маршрутов с помощью защиты middleware","Чтение токенов в компонентах сервера"],"ar":["تنفيذ تخزين رمز آمن","حماية الطرق بحماية وسيط ","قراءة الرموز في مكونات الخادم"]},"limitations":{"en":["Requires Next.js environment","Must use HttpOnly Cookies for token storage","Never use LocalStorage for security"],"zh":["需要 Next.js 环境","必须使用 HttpOnly Cookies 进行令牌存储","绝不能使用 LocalStorage 进行安全"],"ja":["Next.js 環境が必要","トークンストレージには HttpOnly Cookies を使用する必要がある","セキュリティのためにローカルストレージを使用してはならない"],"ko":["Next.js 환경이 필요","토큰 저장을 위해 HttpOnly 쿠키를 사용해야 함","보안을 위해 로컬 스토리지를 사용해서는 안 됨"],"es":["Requiere un entorno Next.js","Debe utilizar cookies HttpOnly para el almacenamiento de tokens","Nunca utilizar LocalStorage por seguridad"],"fr":["Nécessite un environnement Next.js","Doit utiliser des cookies HttpOnly pour le stockage des jetons","Ne jamais utiliser LocalStorage pour des raisons de sécurité"],"de":["Erfordert eine Next.js-Umgebung","Muss HttpOnly-Cookies zur Tokenspeicherung verwenden","Aus Sicherheitsgründen niemals LocalStorage verwenden"],"pt":["Requer ambiente Next.js","Deve usar Cookies HttpOnly para armazenamento de token","Nunca use LocalStorage para segurança"],"ru":["Требуется среда Next.js","Должно использовать файлы cookie HttpOnly для хранения токенов","Никогда не используйте LocalStorage для безопасности"],"ar":["يتطلب بيئة Next.js","يجب استخدام ملفات تعريف الارتباط HttpOnly لتخزين الرمز","أبدا استخدم LocalStorage للأمان"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('majiayu000/claude-skill-registry/prd', 'community', 'majiayu000', 'claude-skill-registry', 'majiayu000/claude-skill-registry', 'prd', 0, 0, 70, '2026-02-18T01:08:43.401Z', '2026-02-18T02:55:18.955Z', NULL, '{"id":"majiayu000/claude-skill-registry/prd","name":"prd","description":{"zh":"PRD 生成器通过收集特性描述、提问和回答来生成清晰的产品需求文档。该文档适合实现和开发使用。","ja":"PRD ジェネレーターは、特性の説明を収集し、質問と回答を通じて、明確な製品要件文書を生成します。この文書は、実装と開発に適しています。","ko":"PRD 생성기는 특성 설명을 수집하고 질문과 답변을 통해 명확한 제품 요구 사항 문서를 생성합니다. 이 문서는 구현과 개발에 적합합니다.","es":"El generador de PRD crea documentos de requisitos de producto detallados y claros para implementación. Recibe descripciones de características, hace preguntas de aclaración y genera un PRD estructurado.","fr":"Le générateur de PRD crée des documents de spécifications de produit détaillés et clairs pour mise en œuvre. Il reçoit des descriptions de fonctionnalités, pose des questions de clarification et génère un PRD structuré.","de":"Der PRD-Generator erstellt detaillierte und klare Produktanforderungsdokumente für die Implementierung. Er erhält Funktionsbeschreibungen, stellt Klarstellungsfragen und generiert ein strukturiertes PRD.","pt":"O gerador de PRD cria documentos de requisitos de produto detalhados e claros, adequados para implementação.","ru":"Генератор PRD создает подробные и ясные документы требований продукта, пригодные для реализации.","ar":"مولد مواصفات المنتج ي创建 وثائق متطلبات المنتج المفصلة والواضحة، والمناسبة للتنفيذ.","en":"The most comprehensive Claude Code skills registry | Web Search: https://skills-registry-web.vercel.app"},"seo":{"title":{"zh":"PRD 生成器 - 创建清晰的产品需求文档","ja":"PRD ジェネレーター - 実装可能な明確な製品要件文書を作成","ko":"PRD 생성기 - 구현 가능한 명확한 제품 요구 사항 문서 생성","es":"Generador de PRD: Crea documentos de requisitos de produc...","fr":"Générateur de PRD : Créez des documents de spécifications...","de":"PRD-