INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yxhpy/qcc_plus/qcc-git', 'community', 'yxhpy', 'qcc_plus', 'yxhpy/qcc_plus', 'qcc-git', 0, 0, 0, '2026-02-18T01:08:43.403Z', '2026-02-18T03:03:50.440Z', NULL, '{"id":"yxhpy/qcc_plus/qcc-git","name":"qcc-git","description":{"es":"QCC Git es un flujo de trabajo de Git que permite a los desarrolladores gestionar ramas y implementar cambios de manera automática","fr":"QCC Git est un workflow Git qui permet aux développeurs de gérer des branches et de déployer des modifications de manière automatique","de":"QCC Git ist ein Git-Workflow, der es Entwicklern ermöglicht, Branches zu verwalten und Änderungen automatisch bereitzustellen","pt":"O QCC Git é uma ferramenta de desenvolvimento que permite um fluxo de trabalho ágil e colaborativo para equipes de desenvolvimento de software","ru":"QCC Git - это инструмент разработки, который позволяет использовать гибкий и командный рабочий процесс для команд разработки программного обеспечения","ar":"QCC Git هو أداة تطوير تتيح تدفق عمل مرن و تعاوني للفرق التطوير البرمجيات","en":"Claude Code CLI 代理服务器 - 多租户、自动故障切换、Web 管理界面"},"seo":{"title":{"es":"QCC Git: Flujo de trabajo de Git para desarrolladores","fr":"QCC Git: Workflow Git pour les développeurs","de":"QCC Git: Git-Workflow für Entwickler","pt":"QCC Git: Fluxo de Trabalho de Desenvolvimento Ágil","ru":"QCC Git: Поток рабочих процессов разработки","ar":"QCC Git: تدفق عمل تطوير مرن","en":"qcc-git"},"description":{"es":"QCC Git es un flujo de trabajo de Git que permite a los desarrolladores gestionar ramas y implementar cambios de manera automática","fr":"QCC Git est un workflow Git qui permet aux développeurs de gérer des branches et de déployer des modifications de manière automatique","de":"QCC Git ist ein Git-Workflow, der es Entwicklern ermöglicht, Branches zu verwalten und Änderungen automatisch bereitzustellen","pt":"O QCC Git é uma ferramenta de desenvolvimento que permite um fluxo de trabalho ágil e colaborativo para equipes de desenvolvimento de software","ru":"QCC Git - это инструмент разработки, который позволяет использовать гибкий и командный рабочий процесс для команд разработки программного обеспечения","ar":"QCC Git هو أداة تطوير تتيح تدفق عمل مرن و تعاوني للفرق التطوير البرمجيات","en":"Claude Code CLI 代理服务器 - 多租户、自动故障切换、Web 管理界面"},"definition":{"en":"Claude Code CLI 代理服务器 - 多租户、自动故障切换、Web 管理界面"},"features":{"es":["Gestión de ramas","Implementación automática","Flujo de trabajo personalizable","Integración con servidores de producción","Soporte para múltiples entornos de desarrollo"],"fr":["Gestion de branches","Déploiement automatique","Workflow personnalisable","Intégration avec des serveurs de production","Prise en charge de plusieurs environnements de développement"],"de":["Branch-Verwaltung","Automatische Bereitstellung","Anpassbarer Workflow","Integration mit Produktionsservern","Unterstützung für mehrere Entwicklungsumgebungen"],"pt":["Fluxo de trabalho ágil e colaborativo","Automatização de tarefas de desenvolvimento","Controle de versão e gerenciamento de branches","Integração com ambientes de teste e produção","Interface de usuário web para gerenciamento"],"ru":["Гибкий и командный рабочий процесс","Автоматизация задач разработки","Контроль версий и управление ветками","Интеграция с тестовыми и продакшн-окружениями","Веб-интерфейс для управления"],"ar":["تدفق عمل مرن و تعاوني","آليّة المهام التطويرية","مراقبة الإصدارات و إدارة الفروع","التكامل مع بيئات الاختبار و الإنتاج","واجهة مستخدم ويب لإدارة"]},"keywords":{"es":["QCC Git","flujo de trabajo de Git","gestión de ramas","implementación automática","desarrollo de software","entornos de desarrollo","servidores de producción"],"fr":["QCC Git","workflow Git","gestion de branches","déploiement automatique","développement de logiciels","environnements de développement","serveurs de production"],"de":["QCC Git","Git-Workflow","Branch-Verwaltung","automatische Bereitstellung","Software-Entwicklung","Entwicklungsumgebungen","Produktionsserver"],"pt":["desenvolvimento de software","fluxo de trabalho ágil","ferramenta de desenvolvimento","colaboração em equipe","controle de versão","gerenciamento de branches"],"ru":["разработка программного обеспечения","гибкий рабочий процесс","инструмент разработки","командная работа","контроль версий","управление ветками"],"ar":["تطوير البرمجيات","تدفق عمل مرن","أداة تطوير","تعاون الفريق","مراقبة الإصدارات","إدارة الفروع"]}},"owner":"yxhpy","repo":"qcc_plus","repoPath":"yxhpy/qcc_plus","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.403Z","topics":[],"category":"community","skillMd":{"name":"qcc-git","description":"Use for Git workflow, branch strategy, and commit conventions in qcc_plus project","bodyPreview":"# QCC Plus Git 工作流\n\n## 分支策略（强制）\n\n**强制规则**: 所有开发工作必须在 `test` 分支进行，编写代码前必须确认当前分支。\n\n| 分支 | 用途 | 说明 |\n|------|------|------|\n| `test` | 日常开发 | ✅ 在这里开发，推送后自动部署到测试环境（端口 8001） |\n| `main` | 正式发布 | 合并测试通过的代码，用于打 tag 发布版本 |\n| `prod` | 生产部署 | 部署到生产服务器（端口 8000） |\n\n## 编写代码前检查\n\n```bash\n# 确认在 test 分支\ngit branch --show-current\n\n# 如不在 test 分支\ngit checkout test\n```\n\n## 工作流程\n\n```bash\n# 1. 开发\ngit checkout test\n# 编写代码\ngit push origin test\n\n# 2. 发布\ngit checkout main\ngit merge test\ngit tag vX.Y.Z\ngit push origin vX.Y.","body":"# QCC Plus Git 工作流\n\n## 分支策略（强制）\n\n**强制规则**: 所有开发工作必须在 `test` 分支进行，编写代码前必须确认当前分支。\n\n| 分支 | 用途 | 说明 |\n|------|------|------|\n| `test` | 日常开发 | ✅ 在这里开发，推送后自动部署到测试环境（端口 8001） |\n| `main` | 正式发布 | 合并测试通过的代码，用于打 tag 发布版本 |\n| `prod` | 生产部署 | 部署到生产服务器（端口 8000） |\n\n## 编写代码前检查\n\n```bash\n# 确认在 test 分支\ngit branch --show-current\n\n# 如不在 test 分支\ngit checkout test\n```\n\n## 工作流程\n\n```bash\n# 1. 开发\ngit checkout test\n# 编写代码\ngit push origin test\n\n# 2. 发布\ngit checkout main\ngit merge test\ngit tag vX.Y.Z\ngit push origin vX.Y.Z\n\n# 3. 部署\ngit checkout prod\ngit merge main\ngit push origin prod\n```\n\n## Commit 格式\n\n使用 Conventional Commits 格式：`type: description`\n\n| 类型 | 说明 | 版本影响 |\n|------|------|----------|\n| `feat` | 新功能 | minor 升级 |\n| `fix` | Bug 修复 | patch 升级 |\n| `feat!` / `fix!` | 重大变更 | major 升级 |\n| `docs` | 文档更新 | 不触发 |\n| `refactor` | 代码重构 | 不触发 |\n| `test` | 测试相关 | 不触发 |\n| `chore` | 构建/工具 | 不包含在 CHANGELOG |\n\n### 示例\n```\nfeat: 添加健康检查 API 端点\nfix: 修复节点切换延迟问题\ndocs: 更新 CLAUDE.md 文档结构\nfeat!: 重构 API 接口，移除 v1 兼容性\n```\n\n## 提交规范\n\n### Git 安全协议\n- **永不**更新 git config\n- **永不**运行破坏性命令（如 push --force, hard reset）除非用户明确请求\n- **永不**跳过 hooks（--no-verify, --no-gpg-sign）除非用户明确请求\n- **永不**强制推送到 main/master\n- 避免 `git commit --amend`，仅在用户明确请求或添加 pre-commit hook 的编辑时使用\n- 修改前总是检查作者：`git log -1 --format=''%an %ae''`\n- **永不**提交更改除非用户明确要求\n\n### 提交消息格式\n\n使用 HEREDOC 确保格式正确：\n```bash\ngit commit -m \"$(cat <<''EOF''\nCommit message here.\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\n\nCo-Authored-By: Claude Opus 4.5 <noreply@anthropic.com>\nEOF\n)\"\n```\n\n## 质量保证\n\n### 测试要求\n- 核心业务逻辑必须有单元测试\n- 使用真实数据测试，避免过度 mock\n- 测试边界条件和错误场景\n- 使用 `go test -race` 检测竞态条件\n\n### 代码审查\n- 所有合并到 main 的代码必须经过审查\n- 检查错误处理是否完善\n- 检查是否有资源泄漏（goroutine、文件句柄）\n- 检查并发安全性\n"},"lastSynced":"2026-02-18T03:03:50.440Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing automated Git workflow management with multi-tenancy and Web interface support.","zh":"非常适合需要具有多租户和Web界面支持的自动化Git工作流管理的DevOps代理。","ja":"マルチテナンシーとWebインターフェースサポートを備えた自動化されたGitワークフロー管理を必要とするDevOpsエージェントに最適です。","ko":"다중 테넌시와 웹 인터페이스 지원을 갖춘 자동화된 Git 워크플로우 관리가 필요한 DevOps 에이전트에 완벽합니다.","es":"Perfecto para agentes de DevOps que necesitan una gestión de flujo de trabajo de Git automatizada con multi-tenant y soporte de interfaz web.","fr":"Parfait pour les agents DevOps ayant besoin d''une gestion de workflow Git automatisée avec multi-locataires et prise en charge de l''interface Web.","de":"Perfekt für DevOps-Agents, die eine automatisierte Git-Workflow-Verwaltung mit Multi-Tenancy und Webinterface-Unterstützung benötigen.","pt":"Perfect for DevOps Agents needing automated Git workflow management with multi-tenancy and Web interface support.","ru":"Perfect for DevOps Agents needing automated Git workflow management with multi-tenancy and Web interface support.","ar":"Perfect for DevOps Agents needing automated Git workflow management with multi-tenancy and Web interface support."},"recommendation":{"en":"Empowers agents to manage Git repositories with automated branch strategies, including test, main, and prod environments, and leverages Web管理界面 for seamless management, utilizing protocols like Git push and pull, and handling file formats such as .gitignore.","zh":"使代理能够通过自动化分支策略（包括测试、主线和生产环境）管理Git仓库，并利用Web管理界面实现无缝管理，使用Git推送和拉取等协议，并处理.gitignore等文件格式。","ja":"テスト、メイン、本番環境を含む自動化されたブランチ戦略でGitリポジトリを管理し、Gitプッシュやプルなどのプロトコルを利用し、.gitignoreなどのファイル形式を扱うWeb管理インターフェースを活用してシームレスな管理を実現します。","ko":"테스트, 메인, 프로덕션 환경을 포함한 자동화된 브랜치 전략으로 Git 저장소를 관리하고, Git 푸시 및 풀과 같은 프로토콜을 활용하며 .gitignore와 같은 파일 형식을 처리하는 웹 관리 인터페이스를 통해 원활한 관리를 가능하게 합니다.","es":"Habilita a los agentes a gestionar repositorios de Git con estrategias de rama automatizadas, incluyendo entornos de prueba, principales y de producción, y aprovecha la interfaz web para una gestión sin problemas, utilizando protocolos como Git push y pull, y manejando formatos de archivo como .gitignore.","fr":"Permet aux agents de gérer des référentiels Git avec des stratégies de branche automatisées, notamment des environnements de test, principaux et de production, et exploite l''interface web pour une gestion transparente, en utilisant des protocoles tels que Git push et pull, et en gérant des formats de fichiers tels que .gitignore.","de":"Ermächtigt Agenten, Git-Repositorys mit automatisierten Branch-Strategien zu verwalten, einschließlich Test-, Haupt- und Produktionsumgebungen, und nutzt die Web-Oberfläche für eine reibungslose Verwaltung, indem Protokolle wie Git-Push und -Pull verwendet und Dateiformate wie .gitignore gehandhabt werden.","pt":"Empowers agents to manage Git repositories with automated branch strategies, including test, main, and prod environments, and leverages Web管理界面 for seamless management, utilizing protocols like Git push and pull, and handling file formats such as .gitignore.","ru":"Empowers agents to manage Git repositories with automated branch strategies, including test, main, and prod environments, and leverages Web管理界面 for seamless management, utilizing protocols like Git push and pull, and handling file formats such as .gitignore.","ar":"Empowers agents to manage Git repositories with automated branch strategies, including test, main, and prod environments, and leverages Web管理界面 for seamless management, utilizing protocols like Git push and pull, and handling file formats such as .gitignore."},"useCases":{"en":["Automating Git branch management for test and production environments","Deploying code changes to testing servers with Git push","Managing multi-tenant repositories with Web interface"],"zh":["为测试和生产环境自动化Git分支管理","使用Git推送将代码更改部署到测试服务器","通过Web界面管理多租户仓库"],"ja":["テスト環境と本番環境のためのGitブランチ管理の自動化","Gitプッシュを使用してテストサーバーにコード変更をデプロイ","Webインターフェースによるマルチテナントリポジトリの管理"],"ko":["테스트 및 프로덕션 환경을 위한 Git 브랜치 관리 자동화","Git 푸시로 테스트 서버에 코드 변경사항 배포","웹 인터페이스로 다중 테넌트 저장소 관리"],"es":["Automatizar la gestión de ramas de Git para entornos de prueba y producción","Implementar cambios de código en servidores de prueba con Git push","Gestionar repositorios multi-tenant con interfaz web"],"fr":["Automatiser la gestion des branches Git pour les environnements de test et de production","Déployer des modifications de code sur des serveurs de test avec Git push","Gérer des référentiels multi-locataires avec interface web"],"de":["Automatisieren der Git-Branch-Verwaltung für Test- und Produktionsumgebungen","Bereitstellen von Code-Änderungen auf Testservern mit Git-Push","Verwalten von Multi-Tenant-Repositorys mit Webinterface"],"pt":["Automating Git branch management for test and production environments","Deploying code changes to testing servers with Git push","Managing multi-tenant repositories with Web interface"],"ru":["Automating Git branch management for test and production environments","Deploying code changes to testing servers with Git push","Managing multi-tenant repositories with Web interface"],"ar":["Automating Git branch management for test and production environments","Deploying code changes to testing servers with Git push","Managing multi-tenant repositories with Web interface"]},"limitations":{"en":["Requires Git installation and configuration","Limited to Claude Code CLI 代理服务器","Needs confirmation of current branch before development"],"zh":["需要安装和配置Git","仅限于Claude Code CLI代理服务器","开发前需要确认当前分支"],"ja":["Gitのインストールと設定が必要","Claude Code CLIエージェントサーバーに限定","開発前に現在のブランチを確認する必要がある"],"ko":["Git 설치 및 구성 필요","Claude Code CLI 에이전트 서버로 제한됨","개발 전 현재 브랜치 확인 필요"],"es":["Requiere instalación y configuración de Git","Limitado a Claude Code CLI 代理服务器","Necesita confirmación de la rama actual antes del desarrollo"],"fr":["Nécessite l''installation et la configuration de Git","Limité à Claude Code CLI 代理服务器","Nécessite une confirmation de la branche actuelle avant le développement"],"de":["Benötigt Git-Installation und -Konfiguration","Begrenzt auf Claude Code CLI 代理服务器","Benötigt Bestätigung der aktuellen Branch vor der Entwicklung"],"pt":["Requires Git installation and configuration","Limited to Claude Code CLI 代理服务器","Needs confirmation of current branch before development"],"ru":["Requires Git installation and configuration","Limited to Claude Code CLI 代理服务器","Needs confirmation of current branch before development"],"ar":["Requires Git installation and configuration","Limited to Claude Code CLI 代理服务器","Needs confirmation of current branch before development"]},"version":3},"qualityScore":0}');
