INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zbruhnke/claude-code-starter/refresh-claude', 'community', 'zbruhnke', 'claude-code-starter', 'zbruhnke/claude-code-starter', 'refresh-claude', 0, 0, 80, '2026-02-18T01:08:43.404Z', '2026-02-18T03:09:30.609Z', NULL, '{"id":"zbruhnke/claude-code-starter/refresh-claude","name":"refresh-claude","description":{"zh":"refresh-claude 是一个生产就绪的 Claude Code 配置模板，具有堆栈预设、安全钩子和自动化工具","ja":"refresh-claude は、スタックのプリセット、セキュリティフック、および自動化ツールを備えたプロダクションレディの Claude Code 構成テンプレートです","ko":"refresh-claude는 스택 프리셋, 보안 후크 및 자동화 도구가 있는 프로덕션 레디 Claude Code 구성 템플릿입니다","es":"Refresh Claude es una plantilla de configuración de Claude Code que mantiene actualizado tu proyecto con preset de pila, ganchos de seguridad y herramientas de automatización","fr":"Refresh Claude est un modèle de configuration de Claude Code qui maintient votre projet à jour avec preset de pile, crochets de sécurité et outils d''automatisation","de":"Refresh Claude ist eine Vorlagenkonfiguration für Claude Code, die Ihr Projekt mit Stack-Preset, Sicherheitshooks und Automatisierungstools auf dem neuesten Stand hält","pt":"O Refresh Claude é um modelo de configuração de código que mantém o arquivo CLAUDE.md atualizado e relevante para sessões de código Claude.","ru":"Refresh Claude - это шаблон конфигурации кода, который поддерживает файл CLAUDE.md в актуальном состоянии и актуальным для сессий кода Claude.","ar":"Refresh Claude هو قالب تكوين كود يبقي ملف CLAUDE.md محدثًا وملائمًا للجلسات كود Claude.","en":"Production-ready Claude Code configuration template with stack presets, security hooks, and automation tools"},"seo":{"title":{"zh":"refresh-claude 技术模板","ja":"refresh-claude コード構成テンプレート","ko":"refresh-claude 코드 구성 템플릿","es":"Refresh Claude: plantilla de configuración de Claude Code","fr":"Refresh Claude : modèle de configuration de Claude Code","de":"Refresh Claude: Vorlagenkonfiguration für Claude Code","pt":"Refresh Claude: Modelo de Configuração de Código","ru":"Refresh Claude: Шаблон конфигурации кода","ar":"refresh Claude: قالب تكوين الكود","en":"refresh-claude"},"description":{"zh":"refresh-claude 是一个生产就绪的 Claude Code 配置模板，具有堆栈预设、安全钩子和自动化工具","ja":"refresh-claude は、スタックのプリセット、セキュリティフック、および自動化ツールを備えたプロダクションレディの Claude Code 構成テンプレートです","ko":"refresh-claude는 스택 프리셋, 보안 후크 및 자동화 도구가 있는 프로덕션 레디 Claude Code 구성 템플릿입니다","es":"Refresh Claude es una plantilla de configuración de Claude Code que mantiene actualizado tu proyecto con preset de pila, ganchos de seguridad y herramientas ...","fr":"Refresh Claude est un modèle de configuration de Claude Code qui maintient votre projet à jour avec preset de pile, crochets de sécurité et outils d''automati...","de":"Refresh Claude ist eine Vorlagenkonfiguration für Claude Code, die Ihr Projekt mit Stack-Preset, Sicherheitshooks und Automatisierungstools auf dem neuesten ...","pt":"O Refresh Claude é um modelo de configuração de código que mantém o arquivo CLAUDE.md atualizado e relevante para sessões de código Claude.","ru":"Refresh Claude - это шаблон конфигурации кода, который поддерживает файл CLAUDE.md в актуальном состоянии и актуальным для сессий кода Claude.","ar":"Refresh Claude هو قالب تكوين كود يبقي ملف CLAUDE.md محدثًا وملائمًا للجلسات كود Claude.","en":"Production-ready Claude Code configuration template with stack presets, security hooks, and automation tools"},"definition":{"en":"Production-ready Claude Code configuration template with stack presets, security hooks, and automation tools"},"features":{"zh":["代码库变更分析","新模式、约定或重要上下文识别","CLAUDE.md 更新","过时信息删除","自动化工具"],"ja":["コードベースの変更分析","新しいパターン、約束、または重要なコンテキストの識別","CLAUDE.md の更新","古い情報の削除","自動化ツール"],"ko":["코드베이스 변경 분석","새로운 패턴, 규약 또는 중요한 컨텍스트 식별","CLAUDE.md 업데이트","오래된 정보 삭제","자동화 도구"],"es":["Revisa los cambios recientes en el código","Identifica nuevos patrones y convenciones","Actualiza el archivo CLAUDE.md","Elimina información obsoleta","Incluye preset de pila y ganchos de seguridad"],"fr":["Vérifie les changements récents dans le code","Identifie les nouveaux modèles et conventions","Met à jour le fichier CLAUDE.md","Supprime les informations obsolètes","Inclut preset de pile et crochets de sécurité"],"de":["Überprüft die kürzlichen Änderungen im Code","Identifiziert neue Muster und Konventionen","Aktualisiert die Datei CLAUDE.md","Entfernt veraltete Informationen","Enthält Stack-Preset und Sicherheitshooks"],"pt":["Análise de alterações recentes no código","Identificação de novos padrões e convenções","Atualização do arquivo CLAUDE.md","Remoção de informações desatualizadas","Integração com ferramentas de automação"],"ru":["Анализ недавних изменений в коде","Определение новых паттернов и соглашений","Обновление файла CLAUDE.md","Удаление устаревшей информации","Интеграция с инструментами автоматизации"],"ar":["تحليل التغييرات الحديثة في الكود","تحديد أنماط جديدة وتوافق","تحديث ملف CLAUDE.md","إزالة المعلومات القديمة","التكامل مع أدوات التutomatisation"]},"keywords":{"zh":["refresh-claude","Claude Code","代码库变更分析","自动化工具","代码配置模板","生产就绪"],"ja":["refresh-claude","Claude Code","コードベースの変更分析","自動化ツール","コード構成テンプレート","プロダクションレディ"],"ko":["refresh-claude","Claude Code","코드베이스 변경 분석","자동화 도구","코드 구성 템플릿","프로덕션 레디"],"es":["Refresh Claude","Claude Code","plantilla de configuración","preset de pila","gancho de seguridad","herramienta de automatización","desarrollo de software","ingeniería de software"],"fr":["Refresh Claude","Claude Code","modèle de configuration","preset de pile","crochet de sécurité","outils d''automatisation","développement de logiciels","ingénierie de logiciels"],"de":["Refresh Claude","Claude Code","Vorlagenkonfiguration","Stack-Preset","Sicherheitshook","Automatisierungstool","Softwareentwicklung","Softwareingenieur"],"pt":["Refresh Claude","configuração de código","CLAUDE.md","desenvolvimento de software","ferramentas de automação","segurança de código","padrões de código","convenções de código"],"ru":["Refresh Claude","конфигурация кода","CLAUDE.md","разработка программного обеспечения","инструменты автоматизации","безопасность кода","паттерны кода","соглашения кода"],"ar":["Refresh Claude","تكوين الكود","CLAUDE.md","تطوير البرمجيات","أدوات التutomatisation","أمان الكود","أنماط الكود","اتفاقيات الكود"]}},"owner":"zbruhnke","repo":"claude-code-starter","repoPath":"zbruhnke/claude-code-starter","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"refresh-claude","description":"Review recent changes and update CLAUDE.md to keep it relevant for future sessions. Use after significant changes or periodically to maintain context.","bodyPreview":"# Refresh CLAUDE.md\n\nYou are refreshing the project''s CLAUDE.md file to ensure it stays relevant and useful for future Claude Code sessions.\n\n## Purpose\n\nCLAUDE.md serves as persistent context between sessions. When a project evolves, CLAUDE.md should evolve too. This skill:\n\n1. Reviews recent changes to the codebase\n2. Identifies new patterns, conventions, or important context\n3. Updates CLAUDE.md to reflect current state\n4. Removes outdated information\n\n## Process\n\n### Step 1: Analyze Recent C","body":"# Refresh CLAUDE.md\n\nYou are refreshing the project''s CLAUDE.md file to ensure it stays relevant and useful for future Claude Code sessions.\n\n## Purpose\n\nCLAUDE.md serves as persistent context between sessions. When a project evolves, CLAUDE.md should evolve too. This skill:\n\n1. Reviews recent changes to the codebase\n2. Identifies new patterns, conventions, or important context\n3. Updates CLAUDE.md to reflect current state\n4. Removes outdated information\n\n## Process\n\n### Step 1: Analyze Recent Changes\n\n```bash\n# Recent commits\ngit log --oneline -20\n\n# Changed files\ngit diff --stat HEAD~10..HEAD\n\n# New files\ngit diff --name-status HEAD~10..HEAD | grep \"^A\"\n```\n\nLook for:\n- New features or modules\n- New dependencies or tools\n- Changed conventions or patterns\n- New commands or scripts\n- Architecture changes\n\n### Step 2: Review Current CLAUDE.md\n\nRead the existing CLAUDE.md and identify:\n- [ ] Outdated information\n- [ ] Missing new features/tools\n- [ ] Incorrect commands or paths\n- [ ] Stale conventions\n\n### Step 3: Scan the Codebase\n\nCheck for patterns not reflected in CLAUDE.md:\n\n```bash\n# Check for new test patterns\nls -la **/test* **/*test* **/*spec* 2>/dev/null | head -20\n\n# Check for new config files\nls -la *.config.* .* 2>/dev/null | head -20\n\n# Check package.json/pyproject.toml/etc for new scripts\ncat package.json 2>/dev/null | jq ''.scripts'' || true\n```\n\n### Step 4: Update CLAUDE.md\n\nMake targeted updates:\n\n**DO update:**\n- New commands (dev, test, build, lint)\n- New project structure (directories, key files)\n- New conventions discovered in code\n- Important architectural decisions\n- New dependencies that affect how to work with the code\n\n**DON''T add:**\n- Implementation details that change frequently\n- Obvious things (e.g., \"this is a JavaScript project\" for a .js repo)\n- Temporary workarounds\n- Personal preferences not enforced by tooling\n\n### Step 5: Verify Changes\n\nAfter updating, verify:\n- [ ] Commands still work\n- [ ] Paths are correct\n- [ ] No duplicate sections\n- [ ] Concise and scannable\n\n## Output Format\n\n```markdown\n## CLAUDE.md Refresh Summary\n\n### Changes Made\n- Added: [what was added]\n- Updated: [what was updated]\n- Removed: [what was removed]\n\n### Context Discovered\n- [New pattern or convention found]\n- [New tool or command found]\n\n### Recommendations\n- [Suggestions for project improvements]\n```\n\n## Guidelines\n\n### Keep It Concise\nCLAUDE.md should be scannable. Every line should earn its place.\n\n```\n❌ \"This project uses React, which is a JavaScript library for building user interfaces...\"\n✓ \"React 18 with TypeScript. See src/components/ for patterns.\"\n```\n\n### Focus on What''s Actionable\nInclude information Claude needs to work effectively:\n\n```\n✓ Commands to run\n✓ Key file locations\n✓ Conventions to follow\n✓ Things to avoid\n```\n\n### Avoid Duplication\nDon''t repeat what''s in:\n- README.md (user-facing docs)\n- Code comments (implementation details)\n- Config files (tooling handles it)\n\n### Keep It Fresh\nRemove information that''s:\n- No longer accurate\n- Covered by tooling (linters, formatters)\n- Too detailed for context\n\n## Example Updates\n\n### Adding a New Command\n```markdown\n## Commands\n+ npm run e2e        # Run end-to-end tests\n```\n\n### Adding a Convention\n```markdown\n## Conventions\n+ API routes follow REST conventions in `src/api/`\n+ Use `zod` for runtime validation at API boundaries\n```\n\n### Removing Outdated Info\n```markdown\n- ## Legacy\n- The old auth system in `src/auth-old/` is deprecated.\n```\n\n## When to Run\n\n- After adding major features\n- After significant refactoring\n- After adding new tools or dependencies\n- Periodically (weekly/monthly) on active projects\n- Before onboarding new team members\n"},"lastSynced":"2026-02-18T03:09:30.609Z","agentAnalysis":{"suitability":{"en":"Ideal for Code Analysis Agents requiring automated documentation updates and project context maintenance, particularly those utilizing Claude Code configurations.","zh":"适用于需要自动文档更新和项目上下文维护的代码分析代理，特别是那些使用 Claude Code 配置的代理。","ja":"Claude Code 構成を使用するコード分析エージェントが自動ドキュメント更新とプロジェクトコンテキストの維持を必要とする場合に最適です。","ko":"자동 문서 업데이트 및 프로젝트 컨텍스트 유지 관리가 필요한 코드 분석 에이전트에 적합하며, 특히 Claude Code 구성 사용 에이전트에 적합합니다.","es":"Ideal para agentes de análisis de código que requieren actualizaciones de documentación automatizadas y mantenimiento de contexto de proyecto, particularmente aquellos que utilizan configuraciones de Claude Code.","fr":"Idéal pour les agents d''analyse de code nécessitant des mises à jour de documentation automatisées et une maintenance du contexte de projet, en particulier ceux qui utilisent des configurations Claude Code.","de":"Ideal für Code-Analyse-Agents, die automatisierte Dokumentationsaktualisierungen und Projekt-Kontext-Wartung erfordern, insbesondere solche, die Claude-Code-Konfigurationen verwenden.","pt":"Ideal para Agentes de Análise de Código que exigem atualizações de documentação automatizadas e manutenção de contexto de projeto, particularmente aqueles que utilizam configurações de Claude Code.","ru":"Идеально для агентов анализа кода, требующих автоматических обновлений документации и поддержания контекста проекта, особенно тех, кто использует конфигурации Claude Code.","ar":"مثالي لعميل تحليل الشفرة الذي يتطلب تحديثات التوثيق الآلي وتحديث سياق المشروع، خاصة تلك التي تستخدم تكوينات Claude Code."},"recommendation":{"en":"Empowers agents to maintain up-to-date CLAUDE.md files by reviewing recent codebase changes, identifying new patterns and conventions, and automating updates to reflect the current project state, utilizing stack presets, security hooks, and automation tools.","zh":"使代理能够通过审查最近的代码库更改、识别新模式和约定、并自动更新以反映当前项目状态来维护最新的 CLAUDE.md 文件，利用堆栈预设、安全钩子和自动化工具。","ja":"最近のコードベースの変更をレビューし、新しいパターンと規約を識別し、スタックのプリセット、セキュリティフック、および自動化ツールを利用して現在のプロジェクト状態を反映するように自動的に更新することで、CLAUDE.md ファイルを最新の状態に保つことができます。","ko":"최근의 코드베이스 변경을 검토하고 새로운 패턴 및 규약을 식별하며, 스택 프리셋, 보안 후크 및 자동화 도구를 활용하여 현재 프로젝트 상태를 반영하도록 자동으로 업데이트함으로써 에이전트가 최신의 CLAUDE.md 파일을 유지할 수 있도록 합니다.","es":"Habilita a los agentes a mantener archivos CLAUDE.md actualizados mediante la revisión de los cambios recientes en el conjunto de código, la identificación de nuevos patrones y convenciones, y la automatización de las actualizaciones para reflejar el estado actual del proyecto, utilizando preset de pila, ganchos de seguridad y herramientas de automatización.","fr":"Permet aux agents de maintenir des fichiers CLAUDE.md à jour en examinant les modifications récentes du codebase, en identifiant de nouveaux modèles et conventions, et en automatisant les mises à jour pour refléter l''état actuel du projet, en utilisant des préconfigurations de pile, des crochets de sécurité et des outils d''automatisation.","de":"Ermächtigt Agents, CLAUDE.md-Dateien auf dem neuesten Stand zu halten, indem sie kürzliche Änderungen im Codebase überprüfen, neue Muster und Konventionen identifizieren und Aktualisierungen automatisieren, um den aktuellen Projektzustand widerzuspiegeln, und dabei Stack-Voreinstellungen, Sicherheitshooks und Automatisierungstools nutzen.","pt":"Habilita os agentes a manter arquivos CLAUDE.md atualizados revisando as alterações recentes no conjunto de código, identificando novos padrões e convenções e automatizando as atualizações para refletir o estado atual do projeto, utilizando conjuntos de pilha, ganchos de segurança e ferramentas de automação.","ru":"Позволяет агентам поддерживать файлы CLAUDE.md в актуальном состоянии, просматривая недавние изменения в кодовой базе, выявляя новые шаблоны и соглашения, и автоматизируя обновления для отражения текущего состояния проекта, используя наборы стека, крючки безопасности и инструменты автоматизации.","ar":"يمكن للعميل الحفاظ على ملفات CLAUDE.md محدثة من خلال مراجعة التغييرات الأخيرة في قاعدة الشفرة، وتحديد أنماط جديدة واتفاقيات، وتحديث التغييرات تلقائيًا لتعكس حالة المشروع الحالية، باستخدام مجموعات الحزمة ومخالب الأمان وأدوات الأتمتة."},"useCases":{"en":["Automating CLAUDE.md updates after significant codebase changes","Identifying and documenting new project conventions and patterns","Removing outdated information from CLAUDE.md to maintain project relevance"],"zh":["在重大代码库更改后自动更新 CLAUDE.md","识别和记录新的项目约定和模式","从 CLAUDE.md 中删除过时信息以维护项目相关性"],"ja":["重大なコードベースの変更後、CLAUDE.md を自動的に更新します","新しいプロジェクト規約とパターンを識別し、文書化します","プロジェクトの関連性を維持するために、CLAUDE.md から古い情報を削除します"],"ko":["重大한 코드베이스 변경 후 CLAUDE.md를 자동으로 업데이트합니다","새로운 프로젝트 규약 및 패턴을 식별 및 문서화합니다","프로젝트 관련성을 유지하기 위해 CLAUDE.md에서 구식 정보를 제거합니다"],"es":["Automatizar las actualizaciones de CLAUDE.md después de cambios significativos en el conjunto de código","Identificar y documentar nuevas convenciones y patrones del proyecto","Eliminar información obsoleta de CLAUDE.md para mantener la relevancia del proyecto"],"fr":["Automatiser les mises à jour de CLAUDE.md après des modifications importantes du codebase","Identifier et documenter de nouvelles conventions et modèles de projet","Supprimer les informations obsolètes de CLAUDE.md pour maintenir la pertinence du projet"],"de":["Automatisieren von CLAUDE.md-Aktualisierungen nach wesentlichen Änderungen im Codebase","Identifizieren und Dokumentieren neuer Projektkonventionen und -muster","Entfernen veralteter Informationen aus CLAUDE.md, um die Projektrelevanz zu erhalten"],"pt":["Automatizar atualizações de CLAUDE.md após alterações significativas no conjunto de código","Identificar e documentar novas convenções e padrões de projeto","Remover informações desatualizadas de CLAUDE.md para manter a relevância do projeto"],"ru":["Автоматизировать обновления CLAUDE.md после значительных изменений в кодовой базе","Выявлять и документировать новые соглашения и шаблоны проекта","Удалять устаревшую информацию из CLAUDE.md для поддержания актуальности проекта"],"ar":["تحديث ملفات CLAUDE.md تلقائيًا بعد التغييرات الكبيرة في قاعدة الشفرة","تحديد وتوثيق الاتفاقيات والأنماط الجديدة للمشروع","إزالة المعلومات القديمة من ملفات CLAUDE.md للحفاظ على صلاحية المشروع"]},"limitations":{"en":["Requires access to the project''s codebase and CLAUDE.md file","Specifically designed for Claude Code configurations"],"zh":["需要访问项目的代码库和 CLAUDE.md 文件","特别为 Claude Code 配置设计"],"ja":["プロジェクトのコードベースと CLAUDE.md ファイルへのアクセスが必要です","Claude Code 構成専用に設計されています"],"ko":["프로젝트의 코드베이스 및 CLAUDE.md 파일에 대한 액세스가 필요합니다","Claude Code 구성 전용으로 설계되었습니다"],"es":["Requiere acceso al conjunto de código y al archivo CLAUDE.md del proyecto","Diseñado específicamente para configuraciones de Claude Code"],"fr":["Nécessite un accès au codebase et au fichier CLAUDE.md du projet","Conçu spécifiquement pour les configurations Claude Code"],"de":["Benötigt Zugriff auf den Codebase und die CLAUDE.md-Datei des Projekts","Speziell für Claude-Code-Konfigurationen konzipiert"],"pt":["Exige acesso à base de código e ao arquivo CLAUDE.md do projeto","Projetado especificamente para configurações de Claude Code"],"ru":["Требует доступа к кодовой базе и файлу CLAUDE.md проекта","Разработан специально для конфигураций Claude Code"],"ar":["يتطلب الوصول إلى قاعدة الشفرة وملف CLAUDE.md للمشروع","تم تصميمه خصيصًا لتكوينات Claude Code"]},"version":3},"qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('erichowens/some_claude_skills/product-appeal-analyzer', 'community', 'erichowens', 'some_claude_skills', 'erichowens/some_claude_skills', 'product-appeal-analyzer', 0, 0, 65, '2026-02-18T01:08:43.404Z', '2026-02-18T03:09:17.346Z', NULL, '{"id":"erichowens/some_claude_skills/product-appeal-analyzer","name":"product-appeal-analyzer","description":{"zh":"产品吸引力分析器是一种评估用户对产品的吸引力和情感共鸣的工具，帮助开发者优化产品设计和营销策略","ja":"製品魅力分析ツールは、ユーザーの製品に対する魅力と感情的な共鳴を評価するツールで、開発者が製品の設計とマーケティング戦略を最適化するのに役立ちます","ko":"제품 매력 분석기는 사용자의 제품에 대한 매력과 감정적 공감을 평가하는 도구로, 개발자가 제품 디자인과 마케팅 전략을 최적화하는 데 도움이 됩니다","es":"El Análisis de Atracción de Producto evalúa si los usuarios desean un producto. Ayuda a comprender la emoción y la conexión con el usuario.","fr":"L''Analyseur d''Attrait de Produit évalue si les utilisateurs veulent un produit. Il aide à comprendre l''émotion et le lien avec l''utilisateur.","de":"Die Produkt-Anziehungskraft-Analyse bewertet, ob Benutzer ein Produkt wollen. Sie hilft, die Emotion und den Zusammenhang mit dem Benutzer zu verstehen.","pt":"O Analisador de Apego ao Produto ajuda a avaliar se os usuários irão querer um produto, considerando a experiência emocional e a conexão com o público-alvo.","ru":"Анализатор привлекательности продукта помогает оценить, захотят ли пользователи продукт, учитывая эмоциональный опыт и связь с целевой аудиторией.","ar":"محلل جاذبية المنتج يساعد في تقييم ما إذا كان المستخدمون يريدون منتجًا، مع مراعاة التجربة العاطفية والارتباط بالجمهور المستهدف.","en":"Claude skills that make my life easier."},"seo":{"title":{"zh":"产品吸引力分析器","ja":"製品魅力分析ツール","ko":"제품 매력 분석기","es":"Análisis de Atracción de Producto","fr":"Analyseur d''Attrait de Produit","de":"Produkt-Anziehungskraft-Analyse","pt":"Analisador de Apego ao Produto","ru":"Анализатор привлекательности продукта","ar":"محلل جاذبية المنتج","en":"product-appeal-analyzer"},"description":{"zh":"产品吸引力分析器是一种评估用户对产品的吸引力和情感共鸣的工具，帮助开发者优化产品设计和营销策略","ja":"製品魅力分析ツールは、ユーザーの製品に対する魅力と感情的な共鳴を評価するツールで、開発者が製品の設計とマーケティング戦略を最適化するのに役立ちます","ko":"제품 매력 분석기는 사용자의 제품에 대한 매력과 감정적 공감을 평가하는 도구로, 개발자가 제품 디자인과 마케팅 전략을 최적화하는 데 도움이 됩니다","es":"El Análisis de Atracción de Producto evalúa si los usuarios desean un producto. Ayuda a comprender la emoción y la conexión con el usuario.","fr":"L''Analyseur d''Attrait de Produit évalue si les utilisateurs veulent un produit. Il aide à comprendre l''émotion et le lien avec l''utilisateur.","de":"Die Produkt-Anziehungskraft-Analyse bewertet, ob Benutzer ein Produkt wollen. Sie hilft, die Emotion und den Zusammenhang mit dem Benutzer zu verstehen.","pt":"O Analisador de Apego ao Produto ajuda a avaliar se os usuários irão querer um produto, considerando a experiência emocional e a conexão com o público-alvo.","ru":"Анализатор привлекательности продукта помогает оценить, захотят ли пользователи продукт, учитывая эмоциональный опыт и связь с целевой аудиторией.","ar":"محلل جاذبية المنتج يساعد في تقييم ما إذا كان المستخدمون يريدون منتجًا، مع مراعاة التجربة العاطفية والارتباط بالجمهور المستهدف.","en":"Claude skills that make my life easier."},"definition":{"en":"Claude skills that make my life easier."},"features":{"zh":["评估用户对产品的吸引力","分析用户的情感共鸣","优化产品设计和营销策略","评估产品页面和应用商店列表","制定信息传递和语气指导"],"ja":["ユーザーの製品に対する魅力を評価する","ユーザーの感情的な共鳴を分析する","製品の設計とマーケティング戦略を最適化する","製品ページとアプリストアリストを評価する","情報伝達と口調の指針を立てる"],"ko":["사용자의 제품에 대한 매력을 평가한다","사용자의 감정적 공감을 분석한다","제품 디자인과 마케팅 전략을 최적화한다","제품 페이지와 앱 스토어 목록을 평가한다","정보 전달과 톤 가이드를 설정한다"],"es":["Evaluación de páginas de aterrizaje y de producto","Análisis de listados de tiendas de aplicaciones","Creación de mensajes y dirección de identidad visual","Evaluación de la resonancia emocional con personas objetivo","Posicionamiento de productos contra alternativas"],"fr":["Évaluation des pages de destination et de produit","Analyse des listes de magasins d''applications","Création de messages et de direction d''identité visuelle","Évaluation de la résonance émotionnelle avec les personnes cibles","Positionnement de produits par rapport aux alternatives"],"de":["Bewertung von Landingpages und Produktseiten","Analyse von App-Store-Listings","Erstellung von Nachrichten und visueller Identitätsrichtung","Bewertung der emotionalen Resonanz mit Zielpersonen","Positionierung von Produkten gegenüber Alternativen"],"pt":["Avaliação de páginas de destino e listagens de loja de aplicativos","Posicionamento de produtos contra alternativas","Criação de mensagens, tom e direção de identidade visual","Avaliação da ressonância emocional com personas de destino","Análise de atratividade do produto"],"ru":["Оценка посадочных страниц и списков магазина приложений","Позиционирование продукта по отношению к альтернативам","Создание сообщений, тона и направления визуальной идентичности","Оценка эмоциональной резонансности с целевыми персонами","Анализ привлекательности продукта"],"ar":["تقييم صفحات الوجهة وقوائم متجر التطبيقات","موقف المنتج مقابل البديل","إنشاء رسائل وطابع وتوجيه الهوية البصرية","تقييم الانعكاس العاطفي مع شخصيات الوجهة","تحليل جاذبية المنتج"]},"keywords":{"zh":["产品吸引力分析","用户体验","产品设计","营销策略","情感共鸣","产品页面优化"],"ja":["製品魅力分析","ユーザーエクスペリエンス","製品設計","マーケティング戦略","感情的な共鳴","製品ページ最適化"],"ko":["제품 매력 분석","사용자 경험","제품 디자인","마케팅 전략","감정적 공감","제품 페이지 최적화"],"es":["análisis de atracción de producto","evaluación de productos","posicionamiento de productos","creación de mensajes","identidad visual","resonancia emocional","personas objetivo","desarrollo de productos"],"fr":["analyse d''attrait de produit","évaluation de produits","positionnement de produits","création de messages","identité visuelle","résonance émotionnelle","personnes cibles","développement de produits"],"de":["Produkt-Anziehungskraft-Analyse","Produktbewertung","Produktpositionierung","Nachrichtenerstellung","visuelle Identität","emotionale Resonanz","Zielgruppen","Produktentwicklung"],"pt":["análise de produto","desenvolvimento de produto","experiência do usuário","análise de atratividade","posicionamento de produto","criação de mensagens","identidade visual","análise de ressonância emocional"],"ru":["анализ продукта","разработка продукта","опыт пользователя","анализ привлекательности","позиционирование продукта","создание сообщений","визуальная идентичность","анализ эмоциональной резонансности"],"ar":["تحليل المنتج","تطوير المنتج","تجربة المستخدم","تحليل الجاذبية","موقف المنتج","إنشاء الرسائل","الهوية البصرية","تحليل الانعكاس العاطفي"]}},"owner":"erichowens","repo":"some_claude_skills","repoPath":"erichowens/some_claude_skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"product-appeal-analyzer","description":"Evaluate product desirability, market positioning, and emotional resonance—the complement to friction analysis. Assess whether users will WANT a product (not just use it), identity fit, trust signals, and value proposition clarity. Activate on will they like it, market positioning, appeal analysis, product desirability, value proposition, why would someone choose this, landing page review, conversion optimization, messaging strategy. NOT for UX friction analysis (use ux-friction-analyzer), visual design implementation (use web-design-expert), or A/B test setup (use frontend-developer).","tags":"","bodyPreview":"# Product Appeal Analyzer\n\nEvaluate whether users will *want* a product—not just use it. The complement to friction analysis.\n\n**Core insight**: Users don''t choose the best product—they choose the product that feels most like it was made for them.\n\n## When to Use\n\n✅ **Use for:**\n- Evaluating landing pages, product pages, app store listings\n- Positioning a product against alternatives\n- Crafting messaging, tone, visual identity direction\n- Assessing emotional resonance with target personas\n- Pre-","body":"# Product Appeal Analyzer\n\nEvaluate whether users will *want* a product—not just use it. The complement to friction analysis.\n\n**Core insight**: Users don''t choose the best product—they choose the product that feels most like it was made for them.\n\n## When to Use\n\n✅ **Use for:**\n- Evaluating landing pages, product pages, app store listings\n- Positioning a product against alternatives\n- Crafting messaging, tone, visual identity direction\n- Assessing emotional resonance with target personas\n- Pre-launch \"will this convert?\" analysis\n\n❌ **NOT for:**\n- UX friction audits (→ use ux-friction-analyzer)\n- Visual design execution (→ use web-design-expert)\n- A/B test implementation (→ use frontend-developer)\n- Market size estimation or financial forecasting\n- Feature comparison matrices\n\n---\n\n## The Desirability Triangle\n\n**All three must be present.** Missing any one kills conversion:\n\n```\n                    IDENTITY FIT\n                    \"This is for people like me\"\n                         /\\\n                        /  \\\n                       /    \\\n                      /  ★   \\\n                     / DESIRE \\\n                    /          \\\n                   /______________\\\n        PROBLEM               TRUST\n        URGENCY               SIGNALS\n   \"I need this now\"     \"This will actually work\"\n```\n\n| Missing Element | User Reaction |\n|-----------------|---------------|\n| Identity Fit | \"Seems useful, but not for me\" |\n| Problem Urgency | \"Cool, maybe someday\" |\n| Trust Signals | \"Looks sketchy / too good to be true\" |\n\n**Decision tree**: When analyzing, score each vertex 1-10. If any is &lt;5, that''s your priority fix.\n\n---\n\n## Quick Analysis: The 5-Second Test\n\nWithin 5 seconds of landing, a visitor should know:\n\n1. **What is this?** (Category recognition)\n2. **Who is it for?** (Identity signal)\n3. **What''s the core promise?** (Value proposition)\n4. **What do I do next?** (Clear CTA)\n\n**How to run it:**\n- Show landing page to someone unfamiliar for exactly 5 seconds\n- Hide it, then ask: \"What was that? Who''s it for? What would you do there?\"\n- Record verbatim—don''t coach or clarify\n\n**Scoring:**\n\n| Result | Score | Action |\n|--------|-------|--------|\n| All 4 clear in &lt;3 sec | 9-10 | Ship it |\n| All 4 clear in 3-5 sec | 7-8 | Minor polish |\n| 3 of 4 clear | 5-6 | Fix the gap |\n| 2 or fewer clear | 2-4 | Significant rework |\n| Confusing/unclear | 0-1 | Start over |\n\n---\n\n## Analysis Process\n\n### Step 1: Identify Target Personas\n\nFor each persona, document:\n- **Who**: One-sentence description\n- **Problem**: What''s broken + how it feels\n- **Current workaround**: What they do today (and why it sucks)\n- **Identity**: How they see themselves, who they want to become\n\n### Step 2: Score the Desirability Triangle\n\nFor each persona:\n\n```\nPERSONA: [Name]\n\nIDENTITY FIT                    [/10]\n  Visual identity match         [/10]  \"Does this look like my kind of tool?\"\n  Language resonance            [/10]  \"Do they speak my language?\"\n  Implied user match            [/10]  \"Are people like me shown?\"\n\nPROBLEM URGENCY                 [/10]\n  Pain point acknowledged       [/10]  \"They understand my problem\"\n  Emotional resonance           [/10]  \"They get how frustrating it is\"\n  Solution clarity              [/10]  \"I see how this fixes it\"\n\nTRUST SIGNALS                   [/10]\n  Professional execution        [/10]  \"This looks legitimate\"\n  Social proof                  [/10]  \"Others like me use it\"\n  Risk reduction                [/10]  \"What if it doesn''t work?\"\n\nOVERALL APPEAL SCORE:           [/90]\n```\n\n### Step 3: Map Objections\n\n| Objection | Type | How Addressed? |\n|-----------|------|----------------|\n| \"Is this legit?\" | Trust | [Answer] |\n| \"I''ve tried things before\" | Skepticism | [Answer] |\n| \"Too expensive\" | Value | [Answer] |\n| \"Too complicated\" | Effort | [Answer] |\n| \"Not for people like me\" | Identity | [Answer] |\n| \"What if it doesn''t work?\" | Risk | [Answer] |\n| \"I''ll do it later\" | Urgency | [Answer] |\n\n### Step 4: Generate Recommendations\n\nUse priority formula: `Impact = (Users Affected × Severity) / Fix Difficulty`\n\nCategorize into:\n- **Immediate** (ship this week)\n- **Medium-term** (this sprint)\n- **Long-term** (roadmap)\n\n---\n\n## Common Anti-Patterns\n\n### Feature Soup Headline\n\n**Novice thinking**: \"List all capabilities to show value\"\n\n**Reality**: Visitors scan for 2-3 seconds. Feature lists feel generic.\n\n**What to use instead**:\n| Bad | Good |\n|-----|------|\n| \"AI-Powered Recovery Planning Tool with Analytics\" | \"Know exactly what to do next in your recovery\" |\n| \"Comprehensive Legal Document Platform\" | \"Find out in 2 minutes if your record can be expunged\" |\n\n**Detection**: Headline contains 3+ nouns or buzzwords like \"AI-powered\", \"comprehensive\", \"platform\"\n\n### Screenshot Hero\n\n**Novice thinking**: \"Show the product interface so people know what they''re getting\"\n\n**Reality**: Strangers don''t understand your UI. They care about outcomes.\n\n**What to use instead**:\n- Person experiencing the benefit\n- The outcome/result they''ll get\n- Abstract visualization of the transformation\n\n**Detection**: Hero image is a product screenshot with no context\n\n### Trust Ladder Violation\n\n**Novice thinking**: \"Get their email immediately, then convert them\"\n\n**Reality**: Trust builds in stages. Asking for too much too early kills conversion.\n\n**The Trust Ladder** (each rung requires more trust):\n1. Land on page → Professional design, no broken elements\n2. Click/explore → Clear navigation, fast load\n3. Spend &gt;2 min → Demonstrated value, clear progress\n4. Enter info → Why you need it explained, no dark patterns\n5. Create account → Privacy visible, minimal fields, clear benefit\n6. Pay money → Guarantee, testimonials, recognizable processor\n\n**Detection**: Asking for account creation before demonstrating value\n\n### Identity Mismatch\n\n**Novice thinking**: \"Broad appeal = more users\"\n\n**Reality**: When everyone is the target, no one feels targeted.\n\n**What to use instead**:\n| Signal Type | How It Works |\n|-------------|--------------|\n| Visual identity | Dark mode = \"power user\"; Soft pastels = \"wellness\" |\n| Language/tone | \"Crush your goals\" vs \"Find your balance\" |\n| Social proof | Company logos vs individual testimonials |\n| Complexity | Minimal = simplicity-seeker; Feature-rich = power user |\n\n**Detection**: Homepage tries to appeal to 3+ different personas\n\n---\n\n## Self-Contained Tools\n\n### Analysis Workflow\n\n1. **Read** the landing page content and structure\n2. **WebFetch** the target URL to analyze live content\n3. **Write** analysis results to a markdown file\n4. **Edit** recommendations into actionable copy changes\n\n### Appeal Scorer Script\n\nRun: `python scripts/appeal_scorer.py <url>`\n\nProduces structured JSON output with scores and recommendations.\n\n### Reference Files (See for deep dives)\n\n| File | When to Use |\n|------|-------------|\n| `references/scoring-templates.md` | Full scoring matrices and templates |\n| `references/trust-ladder.md` | Deep dive on trust building stages |\n| `references/identity-signals.md` | Visual/verbal identity signal catalog |\n| `references/objection-catalog.md` | Common objections by product type |\n\n---\n\n## Output Format\n\nWhen running this skill, produce:\n\n1. **Executive Summary** - 3 bullet key findings\n2. **Desirability Triangle Scores** - Per persona\n3. **5-Second Test Assessment** - What''s clear, what''s not\n4. **Top 3 Objections** - And how to address them\n5. **Priority Recommendations** - Immediate / Medium / Long-term\n\n---\n\n## Integration with ux-friction-analyzer\n\n**Appeal + Friction = Complete picture**\n\n| This Skill Answers | ux-friction-analyzer Answers |\n|--------------------|------------------------------|\n| \"Do they want it?\" | \"Can they use it?\" |\n| Will they choose this over alternatives? | Can they complete the task? |\n| Does it feel made for them? | Does the flow make sense? |\n| Is the promise compelling? | Is the experience smooth? |\n\n**Run both**: High appeal + high friction = frustrated users. Low friction + low appeal = abandoned product.\n\n---\n\n**Philosophy**: A product with low friction but low appeal gets abandoned. A product with high appeal but high friction gets frustrated users. You need both.\n"},"lastSynced":"2026-02-18T03:09:17.346Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Agents needing advanced product appeal analysis and user experience optimization.","zh":"非常适合需要高级产品吸引力分析和用户体验优化的营销代理。","ja":"マーケティングエージェントが高度な製品アピール分析とユーザーエクスペリエンス最適化を必要とする場合に最適です。","ko":"고급 제품 어필 분석 및 사용자 경험 최적화가 필요한 마케팅 에이전트에게 적합합니다.","es":"Perfecto para agentes de marketing que necesitan un análisis avanzado de atractivo del producto y optimización de la experiencia del usuario.","fr":"Parfait pour les agents de marketing qui ont besoin d''une analyse avancée de l''attrait du produit et d''une optimisation de l''expérience utilisateur.","de":"Perfekt für Marketingagenten, die eine erweiterte Produktattraktivitätsanalyse und eine Optimierung der Benutzererfahrung benötigen.","pt":"Perfeito para Agentes de Marketing que necessitam de análise avançada de apelo de produto e otimização da experiência do usuário.","ru":"Идеально для маркетинговых агентов, которым необходим продвинутый анализ привлекательности продукта и оптимизация пользовательского опыта.","ar":"مثالي للوكلاء التسويقيين الذين يحتاجون إلى تحليل متقدم لجاذبية المنتج وتحسين تجربة المستخدم."},"recommendation":{"en":"Empowers agents to evaluate product appeal through friction analysis and emotional resonance assessment, leveraging landing page evaluation, product positioning, and messaging crafting using protocols like A/B testing and data formats like user personas.","zh":"赋予代理评估产品吸引力通过摩擦分析和情感共鸣评估，利用着陆页评估、产品定位和消息制作使用协议如A/B测试和数据格式如用户画像。","ja":"エージェントは、フリクション分析と感情的共鳴評価を通じて製品アピールを評価し、ランディングページ評価、製品の位置付け、メッセージ作成などを使用することで、A/Bテストやユーザーペルソナなどのプロトコルやデータ形式を活用できます。","ko":"에이전트는 마찰 분석 및 정서적 공鳴 평가를 통해 제품의 매력을 평가하고, 랜딩 페이지 평가, 제품 위치 지정, 메시지 제작 등을 사용하여 A/B 테스트 및 사용자 페르소나 등의 프로토콜 및 데이터 형식을 활용할 수 있습니다.","es":"Habilita a los agentes a evaluar el atractivo del producto a través del análisis de fricciones y la evaluación de la resonancia emocional, utilizando la evaluación de páginas de destino, la posición del producto y la creación de mensajes mediante protocolos como pruebas A/B y formatos de datos como perfiles de usuario.","fr":"Permet aux agents d''évaluer l''attrait d''un produit grâce à l''analyse des frictions et à l''évaluation de la résonance émotionnelle, en exploitant l''évaluation des pages de destination, la positionnement du produit et l''élaboration de messages en utilisant des protocoles tels que les tests A/B et des formats de données tels que les personas utilisateurs.","de":"Ermächtigt die Agenten, den Produktattraktivitätsgrad durch Reibungsanalyse und emotionale Resonanzbewertung zu bewerten, unter Nutzung der Auswertung von Zielseiten, des Produktplatzierungs und der Formulierung von Nachrichten unter Verwendung von Protokollen wie A/B-Test und Datenformaten wie Benutzerprofile.","pt":"Habilita os agentes a avaliar o apelo do produto por meio da análise de atrito e avaliação da ressonância emocional, aproveitando a avaliação de páginas de destino, posicionamento de produto e criação de mensagens usando protocolos como testes A/B e formatos de dados como personas de usuário.","ru":"Наделяет агентов возможностью оценить привлекательность продукта посредством анализа трения и оценки эмоциональной резонансности, используя оценку целевых страниц, позиционирование продукта и формирование сообщений с помощью протоколов типа тестирования А/Б и форматов данных типа пользовательских персон.","ar":"تمكّن الوكلاء من تقييم جاذبية المنتج من خلال تحليل الاحتكاك وتقييم الانعكاس العاطفي، مستفيداً من تقييم صفحات الوجهة ووضع المنتج وصياغة الرسائل باستخدام بروتوكولات مثل اختبار أ/ب وتنسيقات البيانات مثل شخصيات المستخدم."},"useCases":{"en":["Evaluating landing pages for user engagement","Crafting messaging and tone for target personas","Assessing emotional resonance with product alternatives"],"zh":["评估着陆页的用户参与度","为目标人群撰写信息和语气","评估产品替代品的情感共鸣"],"ja":["ユーザー関与度のためのランディングページの評価","ターゲットペルソナのためのメッセージとトーンの作成","製品代替品の感情的共鳴の評価"],"ko":["사용자 참여도를 위한 랜딩 페이지 평가","대상 페르소나를 위한 메시지 및 톤 제작","제품 대체품의 정서적 공鳴 평가"],"es":["Evaluación de páginas de destino para la participación del usuario","Creación de mensajes y tono para personas objetivo","Evaluación de la resonancia emocional con alternativas de productos"],"fr":["Évaluation des pages de destination pour l''engagement des utilisateurs","Création de messages et de ton pour les personas cibles","Évaluation de la résonance émotionnelle avec les alternatives de produits"],"de":["Auswertung von Zielseiten für die Benutzerteilnahme","Formulierung von Nachrichten und Ton für Zielgruppen","Bewertung der emotionalen Resonanz mit Produktalternativen"],"pt":["Avaliar páginas de destino para engajamento do usuário","Criar mensagens e tom para personas-alvo","Avaliar a ressonância emocional com alternativas de produto"],"ru":["Оценка целевых страниц для вовлеченности пользователей","Формирование сообщений и тона для целевых персон","Оценка эмоциональной резонансности с альтернативными продуктами"],"ar":["تقييم صفحات الوجهة لمشاركة المستخدم","صياغة الرسائل والنبرة للشخصيات المستهدفة","تقييم الانعكاس العاطفي مع بدائل المنتج"]},"limitations":{"en":["Requires access to product pages and app store listings","Limited to evaluating user appeal, not technical functionality"],"zh":["需要访问产品页面和应用商店列表","仅限于评估用户吸引力，不包括技术功能"],"ja":["製品ページとアプリストアリストへのアクセスが必要","ユーザーアピールの評価のみに限定され、技術的機能は評価されない"],"ko":["제품 페이지 및 앱 스토어 목록에 대한 액세스가 필요","사용자 매력을 평가하는 것만으로 제한되며, 기술적 기능은 평가되지 않음"],"es":["Requiere acceso a páginas de productos y listados de tiendas de aplicaciones","Limitado a la evaluación del atractivo del usuario, no la funcionalidad técnica"],"fr":["Nécessite un accès aux pages de produits et aux listes de magasins d''applications","Limité à l''évaluation de l''attrait de l''utilisateur, et non à la fonctionnalité technique"],"de":["Erfordert Zugriff auf Produktseiten und App-Store-Listen","Begrenzt auf die Bewertung des Benutzerattraktivitätsgrades, nicht der technischen Funktionalität"],"pt":["Requer acesso a páginas de produto e listagens de loja de aplicativos","Limitado à avaliação do apelo do usuário, não à funcionalidade técnica"],"ru":["Требует доступа к страницам продукта и спискам магазина приложений","Ограничен оценкой привлекательности пользователя, не технической функциональности"],"ar":["يتطلب الوصول إلى صفحات المنتج وقوائم متجر التطبيقات","محدود بالتقييم جاذبية المستخدم، وليس بالوظيفة الفنية"]},"version":3},"qualityScore":65}');
