INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('az9713/ai-co-writing-claude-skills/voice-dna-creator', 'community', 'az9713', 'ai-co-writing-claude-skills', 'az9713/ai-co-writing-claude-skills', 'voice-dna-creator', 0, 0, 80, '2026-02-18T01:08:43.404Z', '2026-02-18T03:09:42.467Z', NULL, '{"id":"az9713/ai-co-writing-claude-skills/voice-dna-creator","name":"voice-dna-creator","description":{"zh":"语音DNA创建器是基于上下文工程原则的AI协同写作系统，用于分析写作样本并提取独特的语音特征","ja":"ボイスDNAクリエーターは、文章サンプルを分析して独自のボイスプロファイルを抽出する、コンテキストエンジニアリング原則に基づくAIコライティングシステムです","ko":"보이스 DNA 생성기는 글쓰기 샘플을 분석하여 고유한 보이스 프로필을 추출하는 콘텐츠 엔지니어링 원칙에 기반한 AI 공동 작성 시스템입니다","es":"El Creador de ADN de Voz es un sistema de co-escritura de IA que analiza muestras de escritura para crear un perfil de voz único","fr":"Le Créateur d''ADN de Voix est un système de co-écriture d''IA qui analyse des échantillons d''écriture pour créer un profil de voix unique","de":"Der Stimm-DNA-Ersteller ist ein KI-Co-Writing-System, das Schreibproben analysiert, um ein einzigartiges Stimmprofil zu erstellen","pt":"O Voice DNA Creator é um sistema de co-escrita baseado em princípios de engenharia de contexto, que cria perfis de voz únicos para conteúdo personalizado.","ru":"Voice DNA Creator - это система совместного письма, основанная на принципах контекстной инженерии, которая создает уникальные голосовые профили для персонализированного контента.","ar":"Voice DNA Creator هو نظام للكتابة المشتركة يعتمد على مبادئ هندسة السياق، ويخلق ملفات صوتية فريدة للمحتوى المخصص","en":"AI Co-Writing System with Claude Skills - A complete Claude Code writing system for content creators based on context engineering principles. Inspired by Alex McFarland''s Claude Code Masterclass."},"seo":{"title":{"zh":"语音DNA创建器：AI内容协同写作系统","ja":"ボイスDNAクリエーター：AIコライティングシステム","ko":"보이스 DNA 생성기: AI 콘텐츠 공동 작성 시스템","es":"Creador de ADN de Voz: sistema de co-escritura de IA","fr":"Créateur d''ADN de Voix: système de co-écriture d''IA","de":"Stimm-DNA-Ersteller: KI-Co-Writing-System","pt":"Crie Perfil de Voz Único com Voice DNA Creator","ru":"Создайте уникальный голосовой профиль с Voice DNA Creator","ar":"إنشاء ملف صوتي فريد باستخدام Voice DNA Creator","en":"voice-dna-creator"},"description":{"zh":"语音DNA创建器是基于上下文工程原则的AI协同写作系统，用于分析写作样本并提取独特的语音特征","ja":"ボイスDNAクリエーターは、文章サンプルを分析して独自のボイスプロファイルを抽出する、コンテキストエンジニアリング原則に基づくAIコライティングシステムです","ko":"보이스 DNA 생성기는 글쓰기 샘플을 분석하여 고유한 보이스 프로필을 추출하는 콘텐츠 엔지니어링 원칙에 기반한 AI 공동 작성 시스템입니다","es":"El Creador de ADN de Voz es un sistema de co-escritura de IA que analiza muestras de escritura para crear un perfil de voz único","fr":"Le Créateur d''ADN de Voix est un système de co-écriture d''IA qui analyse des échantillons d''écriture pour créer un profil de voix unique","de":"Der Stimm-DNA-Ersteller ist ein KI-Co-Writing-System, das Schreibproben analysiert, um ein einzigartiges Stimmprofil zu erstellen","pt":"O Voice DNA Creator é um sistema de co-escrita baseado em princípios de engenharia de contexto, que cria perfis de voz únicos para conteúdo personalizado.","ru":"Voice DNA Creator - это система совместного письма, основанная на принципах контекстной инженерии, которая создает уникальные голосовые профили для персонали...","ar":"Voice DNA Creator هو نظام للكتابة المشتركة يعتمد على مبادئ هندسة السياق، ويخلق ملفات صوتية فريدة للمحتوى المخصص","en":"AI Co-Writing System with Claude Skills - A complete Claude Code writing system for content creators based on context engineering principles. Inspired by Ale..."},"definition":{"en":"AI Co-Writing System with Claude Skills - A complete Claude Code writing system for content creators based on context engineering principles. Inspired by Alex McFarland''s Claude Code Masterclass."},"features":{"zh":["分析写作样本","提取独特的语音特征","创建语音DNA","AI协同写作","支持多种内容格式"],"ja":["文章サンプルを分析","独自のボイスプロファイルを抽出","ボイスDNAを作成","AIコライティング","多種多様なコンテンツ形式をサポート"],"ko":["글쓰기 샘플을 분석","고유한 보이스 프로필을 추출","보이스 DNA를 생성","AI 공동 작성","다양한 콘텐츠 형식을 지원"],"es":["Análisis de muestras de escritura para crear perfiles de voz únicos","Sistema de co-escritura de IA para contenido auténtico","Ideal para ghostwriting y creación de contenido a gran escala","Actualización de perfiles de voz después de la evolución del estilo","Integración con flujos de trabajo de creación de contenido"],"fr":["Analyse d''échantillons d''écriture pour créer des profils de voix uniques","Système de co-écriture d''IA pour du contenu authentique","Idéal pour le ghostwriting et la création de contenu à grande échelle","Mise à jour des profils de voix après l''évolution du style","Intégration avec les flux de travail de création de contenu"],"de":["Analyse von Schreibproben zur Erstellung einzigartiger Stimmprofile","KI-Co-Writing-System für authentischen Inhalt","Ideal für Ghostwriting und Content-Erstellung im großen Maßstab","Aktualisierung von Stimmprofilen nach Stilevolution","Integration in Content-Erstellungsworkflows"],"pt":["Análise de amostras de escrita para extração de perfis de voz","Criação de perfis de voz únicos para conteúdo personalizado","Compatibilidade com sistema de co-escrita AI","Atualização de perfis de voz após evolução de estilo","Integração com fluxo de trabalho de criação de conteúdo"],"ru":["Анализ образцов письма для извлечения голосовых профилей","Создание уникальных голосовых профилей для персонализированного контента","Совместимость с системой совместного письма AI","Обновление голосовых профилей после эволюции стиля","Интеграция с рабочим процессом создания контента"],"ar":["تحليل عينات الكتابة لاستخراج ملفات صوتية","إنشاء ملفات صوتية فريدة للمحتوى المخصص","التوافق مع نظام الكتابة المشتركة بالذكاء الاصطناعي","تحديث ملفات صوتية بعد تطور الأسلوب","التكامل مع تدفق عمل إنشاء المحتوى"]},"keywords":{"zh":["语音DNA","AI协同写作","内容创作","写作样本分析","语音特征提取"],"ja":["ボイスDNA","AIコライティング","コンテンツ作成","文章サンプル分析","ボイスプロファイル抽出"],"ko":["보이스 DNA","AI 공동 작성","콘텐츠 생성","글쓰기 샘플 분석","보이스 프로필 추출"],"es":["creador de ADN de voz","sistema de co-escritura de IA","ingeniería de contexto","ghostwriting","creación de contenido","perfiles de voz únicos","análisis de escritura","estilos de escritura auténticos"],"fr":["créateur d''ADN de voix","système de co-écriture d''IA","ingénierie de contexte","ghostwriting","création de contenu","profils de voix uniques","analyse d''écriture","styles d''écriture authentiques"],"de":["Stimm-DNA-Ersteller","KI-Co-Writing-System","Kontext-Engineering","Ghostwriting","Content-Erstellung","einzigartige Stimmprofile","Schreibanalyse","authentische Schreibstile"],"pt":["Voice DNA Creator","co-escrita AI","perfis de voz únicos","conteúdo personalizado","engenharia de contexto","sistema de co-escrita","análise de escrita","criação de conteúdo"],"ru":["Voice DNA Creator","совместное письмо AI","уникальные голосовые профили","персонализированный контент","контекстная инженерия","система совместного письма","анализ письма","создание контента"],"ar":["Voice DNA Creator","نظام الكتابة المشتركة بالذكاء الاصطناعي","ملفات صوتية فريدة","محتوى مخصص","هندسة السياق","نظام الكتابة المشتركة","تحليل الكتابة","إنشاء المحتوى"]}},"owner":"az9713","repo":"ai-co-writing-claude-skills","repoPath":"az9713/ai-co-writing-claude-skills","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"voice-dna-creator","description":"Analyze writing samples to create a comprehensive voice DNA profile. Use when the user wants to capture their unique writing voice, needs to create a voice profile for AI content, or is setting up a new writing system.","bodyPreview":"# Voice DNA Creator\n\nAnalyze writing samples to extract and codify a unique voice profile that AI can use to replicate your authentic writing style.\n\n## When to Use This Skill\n\n- Setting up a new writing system\n- Creating voice profiles for clients (ghostwriting)\n- Updating voice profiles after style evolution\n- Onboarding into content creation workflow\n\n## Requirements\n\nThe user must provide:\n- **Minimum**: 3 writing samples (500+ words each)\n- **Ideal**: 5-10 samples across different content t","body":"# Voice DNA Creator\n\nAnalyze writing samples to extract and codify a unique voice profile that AI can use to replicate your authentic writing style.\n\n## When to Use This Skill\n\n- Setting up a new writing system\n- Creating voice profiles for clients (ghostwriting)\n- Updating voice profiles after style evolution\n- Onboarding into content creation workflow\n\n## Requirements\n\nThe user must provide:\n- **Minimum**: 3 writing samples (500+ words each)\n- **Ideal**: 5-10 samples across different content types\n- **Best**: Mix of casual (social posts) and formal (articles) content\n\n## Analysis Process\n\n### Step 1: Collect Samples\n\nAsk: \"Please share 3-10 writing samples that represent your authentic voice. These can be:\n- Newsletter issues\n- Blog posts\n- Social media posts\n- Emails you''ve written\n- Any content where you feel ''this sounds like me''\n\nPaste them here or point me to files in the knowledge folder.\"\n\n### Step 2: Analyze Core Elements\n\nFor each sample, analyze:\n\n**Personality Markers**\n- What personality traits come through?\n- What''s the energy level?\n- How does the writer relate to the reader?\n\n**Emotional Range**\n- What emotions are expressed?\n- How intense are they?\n- What''s the dominant emotional tone?\n\n**Communication Style**\n- Formality level (casual to professional)\n- Sentence length patterns\n- Paragraph structure\n- Use of questions, commands, statements\n\n**Language Patterns**\n- Signature phrases that repeat\n- Power words used frequently\n- Transition phrases\n- Opening and closing patterns\n\n**What They Avoid**\n- Words or phrases never used\n- Tones never taken\n- Approaches avoided\n\n**Formatting Habits**\n- Emoji usage\n- List usage\n- Header styles\n- Bold/italic patterns\n\n### Step 3: Synthesize Findings\n\nCombine analysis across all samples to identify:\n- Consistent patterns (appear in most samples)\n- Contextual variations (change based on content type)\n- Core voice elements (never change)\n\n### Step 4: Generate Voice DNA\n\nCreate the profile following this structure:\n\n```json\n{\n  \"voice_dna\": {\n    \"version\": \"1.0\",\n    \"last_updated\": \"YYYY-MM-DD\",\n    \"core_essence\": {\n      \"identity\": \"\",\n      \"primary_role\": \"\",\n      \"unique_angle\": \"\"\n    },\n    \"personality_traits\": {\n      \"primary\": [],\n      \"how_it_shows\": {}\n    },\n    \"emotional_palette\": {\n      \"dominant_emotions\": [],\n      \"emotional_range\": {},\n      \"energy_level\": \"\"\n    },\n    \"communication_style\": {\n      \"formality\": \"\",\n      \"complexity\": \"\",\n      \"sentence_structure\": {},\n      \"paragraph_style\": \"\"\n    },\n    \"language_patterns\": {\n      \"signature_phrases\": [],\n      \"power_words\": [],\n      \"words_to_avoid\": [],\n      \"transitions\": []\n    },\n    \"never_say\": {\n      \"phrases\": [],\n      \"tones\": [],\n      \"approaches\": []\n    },\n    \"formatting_preferences\": {},\n    \"content_philosophy\": {},\n    \"voice_examples\": {\n      \"opening_lines\": [],\n      \"closing_lines\": [],\n      \"transitional_phrases\": []\n    }\n  }\n}\n```\n\n## Output Instructions\n\n1. After analysis, present key findings in a summary\n\n2. Generate the complete JSON voice profile\n\n3. Save to `/context/voice-dna.json`\n\n4. Provide 3 example sentences written in the captured voice for validation\n\n5. Ask: \"Does this capture your voice? What would you adjust?\"\n\n## Best Practices\n\n- Focus on TONE and PERSONALITY, not just word choice\n- Avoid creating a profile that just repeats phrases\n- Capture the \"feeling\" of the writing, not just patterns\n- Include what NOT to do (equally important)\n- Make the profile actionable for content generation\n\n## Validation Test\n\nAfter creating the profile, write a short paragraph on any topic using ONLY the voice DNA as guidance. Ask the user: \"Does this sound like you?\"\n\nIf not, iterate on the profile based on feedback.\n\n## Common Pitfalls to Avoid\n\n- Don''t just list frequently used words\n- Don''t create a parody of the voice (too exaggerated)\n- Don''t ignore context (social posts ≠ articles)\n- Don''t miss the underlying personality\n- Don''t forget emotional elements\n"},"lastSynced":"2026-02-18T03:09:42.467Z","agentAnalysis":{"suitability":{"en":"Perfect for Language Agents needing advanced content creation capabilities based on context engineering principles.","zh":"非常适合需要基于上下文工程原则的高级内容创建功能的语言代理。","ja":"コンテキストエンジニアリングの原則に基づく高度なコンテンツ作成機能を必要とする言語エージェントに最適です。","ko":"문맥 공학 원칙을 기반으로 고급 콘텐츠 생성 기능이 필요한 언어 에이전트에 적합합니다.","es":"Perfecto para Agentes de Lenguaje que necesitan capacidades de creación de contenido avanzadas basadas en principios de ingeniería de contexto.","fr":"Parfait pour les Agents de Langage ayant besoin de capacités de création de contenu avancées basées sur les principes d''ingénierie de contexte.","de":"Perfekt für Sprachagenten, die erweiterte Inhaltserschaffungsfähigkeiten auf der Grundlage von Kontext-Engineering-Prinzipien benötigen.","pt":"Perfeito para Agentes de Linguagem que necessitam de capacidades avançadas de criação de conteúdo baseadas em princípios de engenharia de contexto.","ru":"Идеально подходит для языковых агентов, которым необходимы продвинутые возможности создания контента на основе принципов контекстной инженерии.","ar":"مثالي للوكلاء اللغويين الذين يحتاجون إلى إمكانيات متقدمة لإنشاء المحتوى dựa على مبادئ هندسة السياق."},"recommendation":{"en":"Empowers agents to extract and codify unique voice profiles from writing samples, replicating authentic writing styles using Claude Code and context engineering principles, and supporting ghostwriting and content evolution workflows through voice profile updates.","zh":"赋予代理从写作样本中提取和编码唯一的声音个人资料，使用 Claude 代码和上下文工程原则复制真实的写作风格，并通过声音个人资料更新支持代写和内容演进工作流。","ja":"代理は、Claude コードとコンテキストエンジニアリングの原則を使用して、書き込みサンプルから一意のボイスプロファイルを抽出し、コード化し、真実の書き込みスタイルを複製し、ボイスプロファイルの更新を通じてゴーストライティングとコンテンツエボリューションワークフローをサポートします。","ko":"대리人は Claude 코드와 문맥 공학 원칙을 사용하여 작성 샘플에서 고유한 음성 프로필을 추출 및 코딩하여 실제 작성 스타일을 복제하고 음성 프로필 업데이트를 통해 유령 작성 및 콘텐츠 진화 워크플ロー를 지원합니다.","es":"Habilita a los agentes a extraer y codificar perfiles de voz únicos a partir de muestras de escritura, replicando estilos de escritura auténticos utilizando Claude Code y principios de ingeniería de contexto, y apoyando flujos de trabajo de escritura fantasma y evolución de contenido a través de actualizaciones de perfiles de voz.","fr":"Permet aux agents d''extraire et de codifier des profils de voix uniques à partir d''échantillons d''écriture, en reproduisant des styles d''écriture authentiques en utilisant Claude Code et les principes d''ingénierie de contexte, et en soutenant les flux de travail de rédaction fantôme et l''évolution du contenu via des mises à jour de profils de voix.","de":"Ermächtigt die Agenten, einzigartige Sprachprofile aus Schreibproben zu extrahieren und zu kodifizieren, authentische Schreibstile unter Verwendung von Claude Code und Kontext-Engineering-Prinzipien zu replizieren und Workflows für Ghostwriting und Content-Evolution durch Sprachprofil-Updates zu unterstützen.","pt":"Habilita os agentes a extrair e codificar perfis de voz únicos a partir de amostras de escrita, replicando estilos de escrita autênticos usando o Código Claude e princípios de engenharia de contexto, e apoiando fluxos de trabalho de redação fantasma e evolução de conteúdo por meio de atualizações de perfis de voz.","ru":"Наделяет агентов возможностью извлекать и кодифицировать уникальные голосовые профили из образцов письма, реплицируя аутентичные стили письма с помощью кода Claude и принципов контекстной инженерии, а также поддерживает рабочие процессы ghostwriting и эволюции контента через обновления голосовых профилей.","ar":"تمكن الوكلاء من استخراج وترميز ملفات صوتية فريدة من العينات الكتابية، وتمثيل أساليب الكتابة الأصيلة باستخدام كود كلود ومبادئ هندسة السياق، ودعم سلاسل العمل للكتابة البارزة وتطور المحتوى من خلال تحديثات ملفات الصوت."},"useCases":{"en":["Analyzing writing samples to create unique voice profiles","Generating content with authentic writing styles for clients","Updating voice profiles after style evolution to maintain consistency"],"zh":["分析写作样本以创建唯一的声音个人资料","为客户生成具有真实写作风格的内容","在风格演进后更新声音个人资料以保持一致性"],"ja":["書き込みサンプルを分析して一意のボイスプロファイルを作成する","クライアントのために真実の書き込みスタイルを持つコンテンツを生成する","スタイルの進化後、ボイスプロファイルを更新して一貫性を維持する"],"ko":["작성 샘플을 분석하여 고유한 음성 프로필을 생성하는 것","고객을 위해 실제 작성 스타일을 가진 콘텐츠를 생성하는 것","스타일 진화 후 음성 프로필을 업데이트하여 일관성을 유지하는 것"],"es":["Análisis de muestras de escritura para crear perfiles de voz únicos","Generación de contenido con estilos de escritura auténticos para clientes","Actualización de perfiles de voz después de la evolución del estilo para mantener la coherencia"],"fr":["Analyse d''échantillons d''écriture pour créer des profils de voix uniques","Génération de contenu avec des styles d''écriture authentiques pour les clients","Mise à jour des profils de voix après l''évolution du style pour maintenir la cohérence"],"de":["Analyse von Schreibproben zur Erstellung einzigartiger Sprachprofile","Erzeugung von Inhalten mit authentischen Schreibstilen für Kunden","Aktualisierung von Sprachprofilen nach Stilevolution, um die Konsistenz zu wahren"],"pt":["Analisar amostras de escrita para criar perfis de voz únicos","Gerar conteúdo com estilos de escrita autênticos para clientes","Atualizar perfis de voz após evolução de estilo para manter a consistência"],"ru":["Анализировать образцы письма для создания уникальных голосовых профилей","Генерировать контент с аутентичными стилями письма для клиентов","Обновлять голосовые профили после эволюции стиля для поддержания согласованности"],"ar":["تحليل العينات الكتابية لإنشاء ملفات صوتية فريدة","توليد المحتوى بأساليب كتابية أصيلة للعملاء","تحديث ملفات الصوت بعد تطور الأسلوب للحفاظ على الاتساق"]},"limitations":{"en":["Requires minimum 3 writing samples of 500+ words each","Ideal performance with 5-10 diverse content samples"],"zh":["需要至少 3 个 500+ 字的写作样本","具有 5-10 个多样化内容样本的理想性能"],"ja":["少なくとも 500 語以上の書き込みサンプル 3 つを必要とする","5-10 個の多様なコンテンツ サンプルを備えた理想的なパフォーマンス"],"ko":["최소 500 자 이상의 작성 샘플 3 개 이상이 필요함","다양한 콘텐츠 샘플 5-10 개로 최적의 성능"],"es":["Requiere un mínimo de 3 muestras de escritura de 500+ palabras cada una","Rendimiento ideal con 5-10 muestras de contenido diversas"],"fr":["Nécessite un minimum de 3 échantillons d''écriture de 500+ mots chacun","Performance idéale avec 5-10 échantillons de contenu divers"],"de":["Benötigt mindestens 3 Schreibproben à 500+ Wörtern","Ideale Leistung mit 5-10 verschiedenen Inhaltsproben"],"pt":["Exige no mínimo 3 amostras de escrita de 500+ palavras cada","Desempenho ideal com 5-10 amostras de conteúdo diversificadas"],"ru":["Требует как минимум 3 образца письма объемом 500+ слов каждый","Идеальная производительность с 5-10 разнообразными образцами контента"],"ar":["يتطلب الحد الأدنى 3 عينات كتابية من 500+ كلمة كل منها","الأداء المثالي مع 5-10 عينات محتوى متنوعة"]},"version":3},"qualityScore":80}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('marcglasberg/async_redux/asyncredux-persistence', 'community', 'marcglasberg', 'async_redux', 'marcglasberg/async_redux', 'asyncredux-persistence', 0, 0, 0, '2026-02-18T01:08:43.404Z', '2026-02-18T03:10:02.939Z', NULL, '{"id":"marcglasberg/async_redux/asyncredux-persistence","name":"asyncredux-persistence","description":{"zh":"AsyncRedux 提供了强大的状态管理功能，通过持久化存储在磁盘上的应用状态","ja":"AsyncRedux は強力な状態管理機能を提供し、ディスクに保存されたアプリの状態を永続化します","ko":"AsyncRedux는 강력한 상태 관리 기능을 제공하며 디스크에 저장된 앱 상태를 영속화합니다","pt":"O AsyncRedux Persistence fornece gerenciamento de estado para aplicativos Flutter, permitindo a restauração do estado entre sessões.","ru":"AsyncRedux Persistence предоставляет управление состоянием для приложений Flutter, позволяя восстанавливать состояние между сессиями.","ar":"يوفر AsyncRedux Persistence إدارة الحالة لتطبيقات Flutter، مما يتيح استعادة الحالة بين الجلسات.","en":"Powerful State Management for Flutter. Docs: https://asyncredux.com"},"seo":{"title":{"zh":"AsyncRedux 持久性状态管理","ja":"AsyncRedux パーシステントステート管理","ko":"AsyncRedux 상태 관리","pt":"AsyncRedux Persistence: Gerenciamento de Estado para Flutter","ru":"AsyncRedux Persistence: Управление состоянием для Flutter","ar":"AsyncRedux Persistence: إدارة الحالة ل Flutter","en":"asyncredux-persistence"},"description":{"zh":"AsyncRedux 提供了强大的状态管理功能，通过持久化存储在磁盘上的应用状态","ja":"AsyncRedux は強力な状態管理機能を提供し、ディスクに保存されたアプリの状態を永続化します","ko":"AsyncRedux는 강력한 상태 관리 기능을 제공하며 디스크에 저장된 앱 상태를 영속화합니다","pt":"O AsyncRedux Persistence fornece gerenciamento de estado para aplicativos Flutter, permitindo a restauração do estado entre sessões.","ru":"AsyncRedux Persistence предоставляет управление состоянием для приложений Flutter, позволяя восстанавливать состояние между сессиями.","ar":"يوفر AsyncRedux Persistence إدارة الحالة لتطبيقات Flutter، مما يتيح استعادة الحالة بين الجلسات.","en":"Powerful State Management for Flutter. Docs: https://asyncredux.com"},"definition":{"en":"Powerful State Management for Flutter. Docs: https://asyncredux.com"},"features":{"zh":["状态持久化","磁盘存储","应用状态恢复","强大的状态管理","支持 Flutter"],"ja":["状態の永続化","ディスク保存","アプリの状態の復元","強力な状態管理","Flutter対応"],"ko":["상태 영속화","디스크 저장","앱 상태 복원","강력한 상태 관리","Flutter 지원"],"pt":["Manter o estado da aplicação em disco","Restaurar o estado entre sessões","Iniciar a loja com persistor","Criar estado padrão se nenhum existir","Ler estado existente do disco","Inicializar a loja com estado restaurado"],"ru":["Сохранять состояние приложения на диске","Восстанавливать состояние между сессиями","Инициализировать магазин с persistor","Создавать состояние по умолчанию, если оно не существует","Читать существующее состояние с диска","Инициализировать магазин с восстановленным состоянием"],"ar":["الحفاظ على حالة التطبيق على القرص","استعادة الحالة بين الجلسات","تهيئة المتجر مع persistor","إنشاء حالة افتراضية إذا لم تكن موجودة","قراءة الحالة الموجودة على القرص","تهيئة المتجر مع حالة مستعادة"]},"keywords":{"zh":["AsyncRedux","状态管理","持久化","Flutter","状态恢复","磁盘存储"],"ja":["AsyncRedux","状態管理","永続化","Flutter","状態復元","ディスク保存"],"ko":["AsyncRedux","상태 관리","영속화","Flutter","상태 복원","디스크 저장"],"pt":["AsyncRedux Persistence","Gerenciamento de Estado Flutter","Estado da Aplicação","Restauração de Estado","Persistor","Flutter","Desenvolvimento de Aplicativos"],"ru":["AsyncRedux Persistence","Управление состоянием Flutter","Состояние приложения","Восстановление состояния","Persistor","Flutter","Разработка приложений"],"ar":["AsyncRedux Persistence","إدارة الحالة Flutter","حالة التطبيق","استعادة الحالة","Persistor","Flutter","تطوير التطبيقات"]}},"owner":"marcglasberg","repo":"async_redux","repoPath":"marcglasberg/async_redux","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"asyncredux-persistence","description":"Implement local state persistence using Persistor. Covers creating a custom Persistor class, implementing `readState()`, `persistDifference()`, `deleteState()`, using LocalPersist helper, throttling saves, and pausing/resuming persistence with app lifecycle.","bodyPreview":"## Overview\n\nAsyncRedux provides state persistence by passing a `persistor` object to the Store. This maintains app state on disk, enabling restoration between sessions.\n\n## Store Initialization with Persistor\n\nAt startup, read any existing state from disk, create default state if none exists, then initialize the store:\n\n```dart\nvar persistor = MyPersistor();\n\nvar initialState = await persistor.readState();\n\nif (initialState == null) {\n  initialState = AppState.initialState();\n  await persistor.","body":"## Overview\n\nAsyncRedux provides state persistence by passing a `persistor` object to the Store. This maintains app state on disk, enabling restoration between sessions.\n\n## Store Initialization with Persistor\n\nAt startup, read any existing state from disk, create default state if none exists, then initialize the store:\n\n```dart\nvar persistor = MyPersistor();\n\nvar initialState = await persistor.readState();\n\nif (initialState == null) {\n  initialState = AppState.initialState();\n  await persistor.saveInitialState(initialState);\n}\n\nvar store = Store<AppState>(\n  initialState: initialState,\n  persistor: persistor,\n);\n```\n\n## The Persistor Abstract Class\n\nThe `Persistor<St>` base class defines these methods:\n\n```dart\nabstract class Persistor<St> {\n  /// Read persisted state, or return null if none exists\n  Future<St?> readState();\n\n  /// Delete state from disk\n  Future<void> deleteState();\n\n  /// Save state changes. Provides both newState and lastPersistedState\n  /// so you can compare them and save only the difference.\n  Future<void> persistDifference({\n    required St? lastPersistedState,\n    required St newState\n  });\n\n  /// Convenience method for initial saves\n  Future<void> saveInitialState(St state) =>\n    persistDifference(lastPersistedState: null, newState: state);\n\n  /// Controls save frequency. Return null to disable throttling.\n  Duration get throttle => const Duration(seconds: 2);\n}\n```\n\n## Creating a Custom Persistor\n\nExtend the abstract class and implement the required methods:\n\n```dart\nclass MyPersistor extends Persistor<AppState> {\n\n  @override\n  Future<AppState?> readState() async {\n    // Read state from disk (e.g., from SharedPreferences, file, etc.)\n    return null;\n  }\n\n  @override\n  Future<void> deleteState() async {\n    // Delete state from disk\n  }\n\n  @override\n  Future<void> persistDifference({\n    required AppState? lastPersistedState,\n    required AppState newState,\n  }) async {\n    // Save state to disk.\n    // You can compare lastPersistedState with newState to save only changes.\n  }\n\n  @override\n  Duration get throttle => const Duration(seconds: 2);\n}\n```\n\n## Throttling\n\nThe `throttle` getter controls how often state is saved. All changes within the throttle window are collected and saved in a single call. The default is 2 seconds.\n\n```dart\n// Save at most every 5 seconds\n@override\nDuration get throttle => const Duration(seconds: 5);\n\n// Disable throttling (save immediately on every change)\n@override\nDuration? get throttle => null;\n```\n\n## Forcing Immediate Save\n\nDispatch `PersistAction()` to save immediately, bypassing the throttle:\n\n```dart\nstore.dispatch(PersistAction());\n```\n\n## Pausing and Resuming Persistence\n\nControl persistence with these store methods:\n\n```dart\nstore.pausePersistor();           // Pause saving\nstore.persistAndPausePersistor(); // Save current state, then pause\nstore.resumePersistor();          // Resume saving\n```\n\n## App Lifecycle Integration\n\nPause persistence when the app goes to background and resume when it becomes active. Create an `AppLifecycleManager` widget:\n\n```dart\nclass AppLifecycleManager extends StatefulWidget {\n  final Widget child;\n\n  const AppLifecycleManager({\n    Key? key,\n    required this.child,\n  }) : super(key: key);\n\n  @override\n  _AppLifecycleManagerState createState() => _AppLifecycleManagerState();\n}\n\nclass _AppLifecycleManagerState extends State<AppLifecycleManager>\n    with WidgetsBindingObserver {\n\n  @override\n  void initState() {\n    super.initState();\n    WidgetsBinding.instance.addObserver(this);\n  }\n\n  @override\n  void dispose() {\n    WidgetsBinding.instance.removeObserver(this);\n    super.dispose();\n  }\n\n  @override\n  void didChangeAppLifecycleState(AppLifecycleState lifecycle) {\n    store.dispatch(ProcessLifecycleChange_Action(lifecycle));\n  }\n\n  @override\n  Widget build(BuildContext context) => widget.child;\n}\n```\n\nCreate an action to handle lifecycle changes:\n\n```dart\nclass ProcessLifecycleChange_Action extends ReduxAction<AppState> {\n  final AppLifecycleState lifecycle;\n\n  ProcessLifecycleChange_Action(this.lifecycle);\n\n  @override\n  Future<AppState?> reduce() async {\n    if (lifecycle == AppLifecycleState.resumed ||\n        lifecycle == AppLifecycleState.inactive) {\n      store.resumePersistor();\n    } else if (lifecycle == AppLifecycleState.paused ||\n        lifecycle == AppLifecycleState.detached) {\n      store.persistAndPausePersistor();\n    } else {\n      throw AssertionError(lifecycle);\n    }\n    return null;\n  }\n}\n```\n\nWrap your app with the lifecycle manager:\n\n```dart\nStoreProvider<AppState>(\n  store: store,\n  child: AppLifecycleManager(\n    child: MaterialApp( ... ),\n  ),\n)\n```\n\n## LocalPersist Helper\n\nThe `LocalPersist` class simplifies disk operations for Android/iOS. It works with simple object structures containing only primitives, lists, and maps.\n\n```dart\nimport ''package:async_redux/local_persist.dart'';\n\n// Create instance with a file name\nvar persist = LocalPersist(\"myFile\");\n\n// Save data\nList<Object> simpleObjs = [\n  ''Hello'',\n  42,\n  true,\n  [100, 200, {\"name\": \"John\"}],\n];\nawait persist.save(simpleObjs);\n\n// Load data\nList<Object> loaded = await persist.load();\n\n// Append data\nList<Object> moreObjs = [''more'', ''data''];\nawait persist.save(moreObjs, append: true);\n\n// File operations\nint length = await persist.length();\nbool exists = await persist.exists();\nawait persist.delete();\n\n// JSON operations for single objects\nawait persist.saveJson(simpleObj);\nObject? simpleObj = await persist.loadJson();\n```\n\n**Note:** `LocalPersist` only supports simple objects. For complex nested structures or custom classes, you need to implement serialization yourself (e.g., using JSON encoding with `toJson`/`fromJson` methods).\n\n## References\n\nURLs from the documentation:\n- https://asyncredux.com/sitemap.xml\n- https://asyncredux.com/flutter/miscellaneous/persistence\n- https://asyncredux.com/flutter/basics/store\n- https://asyncredux.com/flutter/miscellaneous/database-and-cloud\n- https://asyncredux.com/flutter/intro\n- https://asyncredux.com/flutter/testing/mocking\n- https://asyncredux.com/flutter/advanced-actions/redux-action\n- https://asyncredux.com/flutter/about\n- https://asyncredux.com/flutter/testing/store-tester\n- https://asyncredux.com/flutter/miscellaneous/advanced-waiting\n"},"lastSynced":"2026-02-18T03:10:02.939Z","agentAnalysis":{"suitability":{"en":"Ideal for Flutter Agents requiring robust state management and persistence capabilities.","zh":"适用于需要强大状态管理和持久化能力的Flutter代理。","ja":"強力な状態管理と永続化機能を必要とするFlutterエージェントに適しています。","ko":"강력한 상태 관리와 지속성 기능을 필요로 하는 Flutter 에이전트에 적합합니다.","es":"Ideal para agentes de Flutter que requieren una gestión de estado robusta y capacidades de persistencia.","fr":"Idéal pour les agents Flutter nécessitant une gestion d''état robuste et des capacités de persistance.","de":"Ideal für Flutter-Agents, die eine robuste Zustandsverwaltung und Persistenzfunktionen erfordern.","pt":"Ideal para Agentes Flutter que exigem gerenciamento de estado robusto e capacidades de persistência.","ru":"Идеально подходит для агентов Flutter, требующих надежного управления состоянием и возможностей сохранения.","ar":"مثالي لعميل Flutter الذي يتطلب إدارة حالة قوية و قابليات استمرار."},"recommendation":{"en":"Empowers agents to maintain app state on disk using a persistor object, enabling seamless restoration between sessions with AsyncRedux and Store Initialization.","zh":"赋予代理使用持久化对象在磁盘上维护应用程序状态的能力，实现会话之间的无缝恢复，使用AsyncRedux和存储初始化。","ja":"エージェントに、永続化オブジェクトを使用してディスク上でアプリケーションの状態を維持する機能を付与し、AsyncReduxとストア初期化を使用してセッション間のシームレスな復元を実現します。","ko":"에이전트에 퍼시스터 객체를 사용하여 디스크에서 애플리케이션 상태를 유지하는 기능을 부여하여 AsyncRedux 및 저장소 초기화를 사용하여 세션 간의 無断 복원을 구현합니다.","es":"Permite a los agentes mantener el estado de la aplicación en disco mediante un objeto persistor, lo que permite una restauración fluida entre sesiones con AsyncRedux y la inicialización de la tienda.","fr":"Permet aux agents de maintenir l''état de l''application sur disque à l''aide d''un objet persistor, ce qui permet une restauration fluide entre les sessions avec AsyncRedux et l''initialisation du magasin.","de":"Ermöglicht es den Agents, den Anwendungsstatus auf der Festplatte mithilfe eines Persistor-Objekts zu speichern, wodurch eine nahtlose Wiederherstellung zwischen den Sitzungen mit AsyncRedux und Store-Initialisierung ermöglicht wird.","pt":"Habilita os agentes a manter o estado do aplicativo no disco usando um objeto persistor, permitindo a restauração sem problemas entre sessões com AsyncRedux e Inicialização do Armazenamento.","ru":"Наделяет агентов возможностью сохранять состояние приложения на диске с помощью объекта сохранителя, что позволяет осуществлять бесшовное восстановление между сессиями с AsyncRedux и инициализацией хранилища.","ar":"يمكن الوكلاء من الحفاظ على حالة التطبيق على القرص باستخدام كائن محفظ، مما يسمح بالاستعادة دون مشاكل بين الجلسات مع AsyncRedux وتحديد مخزن التخزين."},"useCases":{"en":["Initializing stores with persisted state","Restoring app state between sessions","Managing state persistence with custom persistor objects"],"zh":["使用持久状态初始化存储","会话间恢复应用程序状态","使用自定义持久化对象管理状态持久性"],"ja":["永続状態を使用してストアを初期化する","セッション間でアプリケーションの状態を復元する","カスタム永続化オブジェクトを使用して状態の永続性を管理する"],"ko":["지속 상태를 사용하여 저장소를 초기화하는 것","세션 간에 애플리케이션 상태를 복원하는 것","사용자 지정 퍼시스터 객체를 사용하여 상태 지속성을 관리하는 것"],"es":["Inicializar tiendas con estado persistido","Restaurar el estado de la aplicación entre sesiones","Administrar la persistencia del estado con objetos persistor personalizados"],"fr":["Initialiser les magasins avec un état persisté","Rétablir l''état de l''application entre les sessions","Gérer la persistance de l''état avec des objets persistor personnalisés"],"de":["Speichert den Shop-Status mit persistiertem Status","Stellt den Anwendungsstatus zwischen den Sitzungen wieder her","Verwaltet die Statuspersistenz mit benutzerdefinierten Persistor-Objekten"],"pt":["Inicializar lojas com estado persistido","Restaurar o estado do aplicativo entre sessões","Gerenciar a persistência de estado com objetos persistores personalizados"],"ru":["Инициализация хранилищ со сохраненным состоянием","Восстановление состояния приложения между сессиями","Управление сохранением состояния с помощью пользовательских объектов сохранителя"],"ar":["ت 초기ية مخازن بالحالة المحفوظة","استعادة حالة التطبيق بين الجلسات","إدارة استمرار الحالة باستخدام كائنات محفظة مخصصة"]},"limitations":{"en":["Requires Dart and Flutter environment","Dependent on AsyncRedux library"],"zh":["需要Dart和Flutter环境","依赖于AsyncRedux库"],"ja":["DartおよびFlutter環境が必要","AsyncReduxライブラリに依存"],"ko":["Dart 및 Flutter 환경이 필요","AsyncRedux 라이브러리에 의존"],"es":["Requiere entorno de Dart y Flutter","Dependiente de la biblioteca AsyncRedux"],"fr":["Nécessite un environnement Dart et Flutter","Dépend de la bibliothèque AsyncRedux"],"de":["Benötigt Dart- und Flutter-Umgebung","Abhängig von der AsyncRedux-Bibliothek"],"pt":["Exige ambiente Dart e Flutter","Dependente da biblioteca AsyncRedux"],"ru":["Требует среды Dart и Flutter","Зависит от 