INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('orient-bot/orient/atlassian-mcp', 'community', 'orient-bot', 'orient', 'orient-bot/orient', 'atlassian-mcp', 0, 0, 0, '2026-02-18T01:08:43.404Z', '2026-02-18T03:09:44.699Z', NULL, '{"id":"orient-bot/orient/atlassian-mcp","name":"atlassian-mcp","description":{"zh":"Atlassian MCP 服务器提供了直接访问 JIRA 和 Confluence 的方式，支持 Cursor 和 Claude Code 的集成","ja":"Atlassian MCP サーバーは JIRA と Confluence に直接アクセスするための方法を提供し、Cursor と Claude Code の統合をサポートします","ko":"Atlassian MCP 서버는 JIRA와 Confluence에 직접 액세스하는 방법을 제공하며 Cursor와 Claude Code의 통합을 지원합니다","es":"El servidor Atlassian MCP proporciona acceso directo a JIRA y Confluence desde agentes de codificación","fr":"Le serveur Atlassian MCP fournit un accès direct à JIRA et Confluence depuis des agents de codage","de":"Der Atlassian MCP Server bietet direkten Zugriff auf JIRA und Confluence von Codierungsagenten","pt":"O Atlassian MCP Server fornece acesso direto ao JIRA e Confluence de agentes de codificação","ru":"Сервер Atlassian MCP обеспечивает прямой доступ к JIRA и Confluence из кодирующих агентов","ar":"خادم Atlassian MCP يوفر الوصول المباشر إلى JIRA و Confluence من وكلاء الترميز","en":"Orient - AI Agent Platform"},"seo":{"title":{"zh":"Atlassian MCP 服务器 - JIRA 集成","ja":"Atlassian MCP サーバー - JIRA 統合","ko":"Atlassian MCP 서버 - JIRA 통합","es":"Atlassian MCP Server para JIRA","fr":"Serveur Atlassian MCP pour JIRA","de":"Atlassian MCP Server für JIRA","pt":"Atlassian MCP Server para JIRA","ru":"Сервер Atlassian MCP для JIRA","ar":"خادم Atlassian MCP لجيرا","en":"atlassian-mcp"},"description":{"zh":"Atlassian MCP 服务器提供了直接访问 JIRA 和 Confluence 的方式，支持 Cursor 和 Claude Code 的集成","ja":"Atlassian MCP サーバーは JIRA と Confluence に直接アクセスするための方法を提供し、Cursor と Claude Code の統合をサポートします","ko":"Atlassian MCP 서버는 JIRA와 Confluence에 직접 액세스하는 방법을 제공하며 Cursor와 Claude Code의 통합을 지원합니다","es":"El servidor Atlassian MCP proporciona acceso directo a JIRA y Confluence desde agentes de codificación","fr":"Le serveur Atlassian MCP fournit un accès direct à JIRA et Confluence depuis des agents de codage","de":"Der Atlassian MCP Server bietet direkten Zugriff auf JIRA und Confluence von Codierungsagenten","pt":"O Atlassian MCP Server fornece acesso direto ao JIRA e Confluence de agentes de codificação","ru":"Сервер Atlassian MCP обеспечивает прямой доступ к JIRA и Confluence из кодирующих агентов","ar":"خادم Atlassian MCP يوفر الوصول المباشر إلى JIRA و Confluence من وكلاء الترميز","en":"Orient - AI Agent Platform"},"definition":{"en":"Orient - AI Agent Platform"},"features":{"zh":["直接访问 JIRA 和 Confluence","支持 Cursor 和 Claude Code 的集成","提供 MCP 服务器配置","支持全局配置"],"ja":["JIRA と Confluence に直接アクセス","Cursor と Claude Code の統合をサポート","MCP サーバーの構成を提供","グローバル構成をサポート"],"ko":["JIRA와 Confluence에 직접 액세스","Cursor와 Claude Code의 통합을 지원","MCP 서버 구성 제공","전역 구성 지원"],"es":["Acceso directo a JIRA y Confluence","Compatibilidad con agentes de codificación","Configuración global en Cursor","Soporte para Claude Code","Acceso a datos de Atlassian"],"fr":["Accès direct à JIRA et Confluence","Compatibilité avec des agents de codage","Configuration globale dans Cursor","Prise en charge de Claude Code","Accès aux données Atlassian"],"de":["Direkter Zugriff auf JIRA und Confluence","Kompatibilität mit Codierungsagenten","Globale Konfiguration in Cursor","Unterstützung für Claude Code","Zugriff auf Atlassian-Daten"],"pt":["Acesso direto ao JIRA e Confluence","Configuração global no Cursor","Habilitação do servidor Atlassian-MCP-Server","Localização de configuração em ~/.cursor/mcp.json","Suporte para agentes de codificação","Integração com o Cursor e o Claude Code"],"ru":["Прямой доступ к JIRA и Confluence","Глобальная настройка в Cursor","Включение сервера Atlassian-MCP-Server","Местоположение конфигурации в ~/.cursor/mcp.json","Поддержка кодирующих агентов","Интеграция с Cursor и Claude Code"],"ar":["الوصول المباشر إلى JIRA و Confluence","التكوين العالمي في Cursor","تمكين خادم Atlassian-MCP-Server","موقع التكوين في ~/.cursor/mcp.json","دعم وكلاء الترميز","التكامل مع Cursor و Claude Code"]},"keywords":{"zh":["Atlassian MCP 服务器","JIRA 集成","Confluence 集成","Cursor","Claude Code","MCP 服务器配置"],"ja":["Atlassian MCP サーバー","JIRA 統合","Confluence 統合","Cursor","Claude Code","MCP サーバーの構成"],"ko":["Atlassian MCP 서버","JIRA 통합","Confluence 통합","Cursor","Claude Code","MCP 서버 구성"],"es":["Atlassian MCP","JIRA","Confluence","agentes de codificación","Cursor","Claude Code","desarrollo de software","integración de herramientas","acceso a datos"],"fr":["Atlassian MCP","JIRA","Confluence","agents de codage","Cursor","Claude Code","développement de logiciels","intégration d''outils","accès aux données"],"de":["Atlassian MCP","JIRA","Confluence","Codierungsagenten","Cursor","Claude Code","Softwareentwicklung","Tool-Integration","Datenzugriff"],"pt":["Atlassian MCP Server","JIRA","Confluence","Cursor","Claude Code","agentes de codificação","servidor de MCP","configuração global","integração com JIRA"],"ru":["Сервер Atlassian MCP","JIRA","Confluence","Cursor","Claude Code","кодирующие агенты","сервер MCP","глобальная настройка","интеграция с JIRA"],"ar":["خادم Atlassian MCP","JIRA","Confluence","Cursor","Claude Code","وكلاء الترميز","خادم MCP","التكوين العالمي","التكامل مع JIRA"]}},"owner":"orient-bot","repo":"orient","repoPath":"orient-bot/orient","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"atlassian-mcp","description":"Use the Atlassian MCP Server to interact with JIRA from coding agents (Cursor, Claude Code). This skill documents how to use the official Atlassian MCP server for JIRA and Confluence operations. Enable this MCP server in your Cursor/Claude Code settings for JIRA access.","bodyPreview":"# Atlassian MCP Server for JIRA\n\nThe Atlassian MCP Server provides direct access to JIRA and Confluence from coding agents. This is the supported way to access Atlassian data from Cursor or Claude Code.\n\n## Setup\n\n### In Cursor\n\nThe Atlassian MCP Server is already configured globally. To enable it:\n\n1. Open Cursor Settings\n2. Go to Tools & MCP\n3. Enable \"Atlassian-MCP-Server\"\n\nConfiguration location: `~/.cursor/mcp.json`\n\n```json\n{\n  \"mcpServers\": {\n    \"Atlassian-MCP-Server\": {\n      \"url\": \"ht","body":"# Atlassian MCP Server for JIRA\n\nThe Atlassian MCP Server provides direct access to JIRA and Confluence from coding agents. This is the supported way to access Atlassian data from Cursor or Claude Code.\n\n## Setup\n\n### In Cursor\n\nThe Atlassian MCP Server is already configured globally. To enable it:\n\n1. Open Cursor Settings\n2. Go to Tools & MCP\n3. Enable \"Atlassian-MCP-Server\"\n\nConfiguration location: `~/.cursor/mcp.json`\n\n```json\n{\n  \"mcpServers\": {\n    \"Atlassian-MCP-Server\": {\n      \"url\": \"https://mcp.atlassian.com/v1/sse\"\n    }\n  }\n}\n```\n\n### In Claude Code\n\nAdd to your Claude Code MCP settings:\n\n```json\n{\n  \"mcpServers\": {\n    \"Atlassian-MCP-Server\": {\n      \"url\": \"https://mcp.atlassian.com/v1/sse\"\n    }\n  }\n}\n```\n\n## Available Tools\n\nWhen enabled, the Atlassian MCP Server provides these tools:\n\n### Issue Operations\n\n| Tool                                     | Description                     |\n| ---------------------------------------- | ------------------------------- |\n| `mcp_Atlassian_getJiraIssue`             | Get details of a specific issue |\n| `mcp_Atlassian_createJiraIssue`          | Create a new issue              |\n| `mcp_Atlassian_editJiraIssue`            | Update an existing issue        |\n| `mcp_Atlassian_transitionJiraIssue`      | Change issue status             |\n| `mcp_Atlassian_searchJiraIssuesUsingJql` | Search issues with JQL          |\n\n### Comments\n\n| Tool                                  | Description                |\n| ------------------------------------- | -------------------------- |\n| `mcp_Atlassian_addCommentToJiraIssue` | Add a comment to an issue  |\n| `mcp_Atlassian_getJiraIssueComments`  | Get comments from an issue |\n\n### Confluence (if enabled)\n\n| Tool                                 | Description              |\n| ------------------------------------ | ------------------------ |\n| `mcp_Atlassian_createConfluencePage` | Create a Confluence page |\n| `mcp_Atlassian_getConfluencePage`    | Get a Confluence page    |\n| `mcp_Atlassian_searchConfluence`     | Search Confluence        |\n\n## Common Patterns\n\n### Get Issue Details\n\n```\nUse mcp_Atlassian_getJiraIssue with issueKey: \"PROJ-123\"\n```\n\n### Search for Issues\n\n```\nUse mcp_Atlassian_searchJiraIssuesUsingJql with:\n  jql: \"project = YOUR_PROJECT AND component = ''YOUR_COMPONENT'' AND status = ''In Progress''\"\n```\n\n### Create an Issue\n\n```\nUse mcp_Atlassian_createJiraIssue with:\n  project: \"YOUR_PROJECT\"\n  issueType: \"Story\"\n  summary: \"Implement new feature\"\n  description: \"Description of the feature\"\n  components: [\"YOUR_COMPONENT\"]\n```\n\n### Transition Issue Status\n\n```\nUse mcp_Atlassian_transitionJiraIssue with:\n  issueKey: \"PROJ-123\"\n  transition: \"In Progress\"\n```\n\n### Add Comment\n\n```\nUse mcp_Atlassian_addCommentToJiraIssue with:\n  issueKey: \"PROJ-123\"\n  comment: \"Started working on this issue\"\n```\n\n## JQL Quick Reference\n\nCommon JQL queries for the Orient Task Force:\n\n```jql\n# All issues for YOUR_COMPONENT\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\"\n\n# In Progress issues\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\" AND status = \"In Progress\"\n\n# Blockers\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\" AND (priority = Blocker OR labels = blocked)\n\n# Recent issues (last 7 days)\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\" AND created >= -7d\n\n# My issues\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\" AND assignee = currentUser()\n\n# Sprint issues\nproject = YOUR_PROJECT AND component = \"YOUR_COMPONENT\" AND sprint in openSprints()\n```\n\n## Troubleshooting\n\n### \"Tool not found\" Error\n\nMake sure the Atlassian MCP Server is enabled in your IDE settings. The tools won''t appear until the server is connected.\n\n### Authentication Issues\n\nThe Atlassian MCP Server uses OAuth. If you''re not authenticated:\n\n1. The tool will prompt you to authenticate\n2. Follow the OAuth flow in your browser\n3. Grant the necessary permissions\n\n### Rate Limits\n\nThe Atlassian MCP Server is subject to Atlassian''s rate limits. If you hit limits:\n\n- Reduce query frequency\n- Use more specific JQL to reduce result sets\n- Cache results when appropriate\n"},"lastSynced":"2026-02-18T03:09:44.699Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents like Cursor or Claude Code needing direct access to JIRA and Confluence data via the Atlassian MCP Server","zh":"非常适合像 Cursor 或 Claude Code 这样的编码代理，需要直接访问 JIRA 和 Confluence 数据的 Atlassian MCP 服务器","ja":"Cursor または Claude Code のようなコーディング エージェントに適しています。JIRA および Confluence データへの直接アクセスが必要です。Atlassian MCP サーバーを使用","ko":"Cursor 또는 Claude Code와 같은 코딩 에이전트에 적합합니다. JIRA 및 Confluence 데이터에 직접 액세스하는 Atlassian MCP 서버가 필요합니다","es":"Perfecto para agentes de codificación como Cursor o Claude Code que necesitan acceso directo a datos de JIRA y Confluence a través del servidor Atlassian MCP","fr":"Parfait pour les agents de codage comme Cursor ou Claude Code qui nécessitent un accès direct aux données JIRA et Confluence via le serveur Atlassian MCP","de":"Perfekt für Codierungsagenten wie Cursor oder Claude Code, die direkten Zugriff auf JIRA- und Confluence-Daten über den Atlassian-MCP-Server benötigen","pt":"Perfeito para Agentes de Codificação como Cursor ou Claude Code que necessitam de acesso direto aos dados do JIRA e Confluence via o Servidor MCP da Atlassian","ru":"Идеально подходит для агентов кодирования, таких как Cursor или Claude Code, требующих прямого доступа к данным JIRA и Confluence через сервер Atlassian MCP","ar":"مثالي لعميل التشفير مثل Cursor أو Claude Code الذي يحتاج إلى الوصول المباشر إلى بيانات JIRA و Confluence عبر خادم Atlassian MCP"},"recommendation":{"en":"Empowers agents to access Atlassian data using the MCP protocol, enabling seamless integration with JIRA and Confluence from within the agent''s workflow, utilizing configuration files like `mcp.json`","zh":"赋予代理访问 Atlassian 数据的能力，使用 MCP 协议，实现与 JIRA 和 Confluence 的无缝集成，使用配置文件如 `mcp.json`","ja":"エージェントが Atlassian データにアクセスする能力を提供します。MCP プロトコルを使用して、JIRA および Confluence とシームレスに統合します。`mcp.json` のような構成ファイルを使用","ko":"에이전트가 Atlassian 데이터에 액세스할 수 있는 기능을 제공합니다. MCP 프로토콜을 사용하여 JIRA 및 Confluence와 원활하게 통합됩니다. `mcp.json`과 같은 구성 파일을 사용","es":"Habilita a los agentes a acceder a los datos de Atlassian utilizando el protocolo MCP, lo que permite una integración sin problemas con JIRA y Confluence desde dentro del flujo de trabajo del agente, utilizando archivos de configuración como `mcp.json`","fr":"Permet aux agents d''accéder aux données Atlassian en utilisant le protocole MCP, ce qui permet une intégration transparente avec JIRA et Confluence depuis le flux de travail de l''agent, en utilisant des fichiers de configuration comme `mcp.json`","de":"Ermöglicht es Agenten, auf Atlassian-Daten über das MCP-Protokoll zuzugreifen, was eine nahtlose Integration mit JIRA und Confluence innerhalb des Arbeitsablaufs des Agents ermöglicht, unter Verwendung von Konfigurationsdateien wie `mcp.json`","pt":"Habilita os agentes a acessarem dados da Atlassian usando o protocolo MCP, permitindo uma integração perfeita com JIRA e Confluence dentro do fluxo de trabalho do agente, utilizando arquivos de configuração como `mcp.json`","ru":"Наделяет агентов возможностью доступа к данным Atlassian с помощью протокола MCP, обеспечивая бесшовную интеграцию с JIRA и Confluence внутри рабочего процесса агента, используя файлы конфигурации типа `mcp.json`","ar":"يمنح الوكلاء الوصول إلى بيانات Atlassian باستخدام بروتوكول MCP، وتمكين التكامل السلس مع JIRA و Confluence داخل تدفق عمل الوكيل، باستخدام ملفات التكوين مثل `mcp.json`"},"useCases":{"en":["Accessing JIRA issues directly from coding agents","Integrating Confluence content into automated workflows","Enabling MCP-based communication between agents and Atlassian services"],"zh":["直接从编码代理访问 JIRA 问题","将 Confluence 内容集成到自动化工作流中","在代理和 Atlassian 服务之间启用基于 MCP 的通信"],"ja":["コーディング エージェントから直接 JIRA の問題にアクセス","Confluence コンテンツを自動化されたワークフローに統合","エージェントと Atlassian サービス間の MCP ベースの通信を有効にする"],"ko":["코딩 에이전트에서 직접 JIRA 문제에 액세스","Confluence 콘텐츠를 자동화된 워크플로에 통합","에이전트와 Atlassian 서비스 간의 MCP 기반 통신을 활성화"],"es":["Acceder a problemas de JIRA directamente desde agentes de codificación","Integrar contenido de Confluence en flujos de trabajo automatizados","Habilitar la comunicación basada en MCP entre agentes y servicios de Atlassian"],"fr":["Accéder aux problèmes JIRA directement depuis les agents de codage","Intégrer le contenu Confluence dans des flux de travail automatisés","Activer la communication basée sur MCP entre les agents et les services Atlassian"],"de":["Direkten Zugriff auf JIRA-Probleme von Codierungsagenten aus","Integrieren von Confluence-Inhalten in automatisierte Arbeitsabläufe","Ermöglichen der MCP-basierten Kommunikation zwischen Agenten und Atlassian-Diensten"],"pt":["Acessar problemas do JIRA diretamente a partir de agentes de codificação","Integrar conteúdo do Confluence em fluxos de trabalho automatizados","Habilitar comunicação baseada em MCP entre agentes e serviços da Atlassian"],"ru":["Доступ к проблемам JIRA напрямую из агентов кодирования","Интеграция содержимого Confluence в автоматические рабочие процессы","Включение коммуникации на основе MCP между агентами и сервисами Atlassian"],"ar":["الوصول إلى مشاكل JIRA مباشرة من عميل التشفير","تكامل محتوى Confluence في سير عمل آلي","تمكين التواصل القائم على MCP بين الوكلاء وخدمات Atlassian"]},"limitations":{"en":["Requires Atlassian MCP Server setup","Configuration file management via `~/.cursor/mcp.json`","Specifically designed for use with Cursor or Claude Code agents"],"zh":["需要 Atlassian MCP 服务器设置","通过 `~/.cursor/mcp.json` 管理配置文件","专门为 Cursor 或 Claude Code 代理设计"],"ja":["Atlassian MCP サーバーのセットアップが必要","構成ファイルの管理 `~/.cursor/mcp.json` を介して","Cursor または Claude Code エージェント専用に設計"],"ko":["Atlassian MCP 서버 설정이 필요합니다","구성 파일 관리를 `~/.cursor/mcp.json`을 통해","Cursor 또는 Claude Code 에이전트専用로 설계"],"es":["Requiere configuración del servidor Atlassian MCP","Administración de archivos de configuración a través de `~/.cursor/mcp.json`","Diseñado específicamente para su uso con agentes Cursor o Claude Code"],"fr":["Nécessite la configuration du serveur Atlassian MCP","Gestion des fichiers de configuration via `~/.cursor/mcp.json`","Conçu spécifiquement pour une utilisation avec les agents Cursor ou Claude Code"],"de":["Benötigt die Einrichtung des Atlassian-MCP-Servers","Verwaltung von Konfigurationsdateien über `~/.cursor/mcp.json`","Speziell für die Verwendung mit Cursor- oder Claude-Code-Agenten konzipiert"],"pt":["Requer configuração do Servidor MCP da Atlassian","Gerenciamento de arquivos de configuração via `~/.cursor/mcp.json`","Projetado especificamente para uso com agentes Cursor ou Claude Code"],"ru":["Требует настройки сервера Atlassian MCP","Управление файлами конфигурации через `~/.cursor/mcp.json`","Разработан специально для использования с агентами Cursor или Claude Code"],"ar":["يتطلب إعداد خادم Atlassian MCP","إدارة ملفات التكوين عبر `~/.cursor/mcp.json`","صممت خصيصًا للاستخدام مع عميل التشفير Cursor أو Claude Code"]},"version":3},"qualityScore":0}');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AstraBert/scpr/web-scraping', 'community', 'AstraBert', 'scpr', 'AstraBert/scpr', 'web-scraping', 0, 0, 45, '2026-02-18T01:08:43.404Z', '2026-02-18T03:09:55.631Z', NULL, '{"id":"AstraBert/scpr/web-scraping","name":"web-scraping","description":{"zh":"Web ","ja":"Web","ko":"Web ","es":"La herramienta de scraping web scpr es una línea de comandos para extraer datos de sitios web de manera sencilla y eficiente","fr":"L''outil de scraping web scpr est une ligne de commande pour extraire des données de sites web de manière simple et efficace","de":"Das Web-Scraping-Tool scpr ist eine Kommandozeile zum Extrahieren von Daten von Websites auf einfache und effiziente Weise","pt":"A ferramenta de web scraping é uma solução eficaz para extrair dados de páginas web. Use o comando scpr para scraper páginas web","ru":"Инструмент веб-скрейпинга - это эффективное решение для сбора данных из веб-страниц. Используйте команду scpr для скрейпинга веб-страниц","ar":"أداة حفر البيانات على الويب هي حل فعال لاستخراج البيانات من صفحات الويب. استخدم الأمر scpr لscraper صفحات الويب","en":"Web scraper CLI and MCP built for human and coding agents"},"seo":{"title":{"zh":"Web ","ja":"Web","ko":"Web ","es":"Herramienta de Scraping Web para Desarrolladores","fr":"Outil de Scraping Web pour Développeurs","de":"Web Scraping Tool für Entwickler","pt":"Web Scraping: Ferramenta de Extração de Dados","ru":"Веб-скрейпинг: Инструмент для сбора данных","ar":"حفر البيانات على الويب: أداة لاستخراج البيانات","en":"web-scraping"},"description":{"zh":"Web ","ja":"Web","ko":"Web ","es":"La herramienta de scraping web scpr es una línea de comandos para extraer datos de sitios web de manera sencilla y eficiente","fr":"L''outil de scraping web scpr est une ligne de commande pour extraire des données de sites web de manière simple et efficace","de":"Das Web-Scraping-Tool scpr ist eine Kommandozeile zum Extrahieren von Daten von Websites auf einfache und effiziente Weise","pt":"A ferramenta de web scraping é uma solução eficaz para extrair dados de páginas web. Use o comando scpr para scraper páginas web","ru":"Инструмент веб-скрейпинга - это эффективное решение для сбора данных из веб-страниц. Используйте команду scpr для скрейпинга веб-страниц","ar":"أداة حفر البيانات على الويب هي حل فعال لاستخراج البيانات من صفحات الويب. استخدم الأمر scpr لscraper صفحات الويب","en":"Web scraper CLI and MCP built for human and coding agents"},"definition":{"en":"Web scraper CLI and MCP built for human and coding agents"},"features":{"zh":["CLI","MCP","",""],"ja":["CLI","MCP","",""],"ko":["CLI","MCP","",""],"es":["Línea de comandos scpr para scraping web","Soporte para scraping recursivo","Soporte para scraping paralelo","Opción de salida personalizable","Soporte para dominios permitidos","Límite de profundidad configurable"],"fr":["Ligne de commande scpr pour le scraping web","Prise en charge du scraping récursif","Prise en charge du scraping parallèle","Option de sortie personnalisable","Prise en charge des domaines autorisés","Limite de profondeur configurable"],"de":["Kommandozeile scpr für Web-Scraping","Unterstützung für rekursives Scraping","Unterstützung für paralleles Scraping","Anpassbare Ausgabemöglichkeit","Unterstützung für erlaubte Domänen","Konfigurierbare Tiefebegrenzung"],"pt":["Scraping de páginas web","Scraping recursivo","Scraping paralelo","Saída em formato markdown","Opção de definir domínio permitido","Opção de definir profundidade máxima"],"ru":["Скрейпинг веб-страниц","Рекурсивный скрейпинг","Параллельный скрейпинг","Выходные данные в формате markdown","Возможность указать разрешенный домен","Возможность указать максимальную глубину"],"ar":["حفر صفحات الويب","حفر تكراري","حفر متوازي","إخراج البيانات في صيغة markdown","خيار تحديد النطاق المسموح به","خيار تحديد العمق الأقصى"]},"keywords":{"zh":["Web ","CLI","MCP","Web ","Web ","Web "],"ja":["Web","CLI","MCP","Web","Web","Web"],"ko":["Web ","CLI","MCP","Web ","Web ","Web "],"es":["scraping web","herramienta de scraping","línea de comandos scpr","scraping recursivo","scraping paralelo","extracción de datos","desarrollo web","programación"],"fr":["scraping web","outil de scraping","ligne de commande scpr","scraping récursif","scraping parallèle","extraction de données","développement web","programmation"],"de":["web scraping","scraping tool","kommandozeile scpr","rekursives scraping","paralleles scraping","datenextraktion","webentwicklung","programmierung"],"pt":["web scraping","scraping de dados","extração de dados","ferramenta de scraping","scraping de páginas web","scraping recursivo","scraping paralelo"],"ru":["веб-скрейпинг","скрейпинг данных","сбор данных","инструмент скрейпинга","скрейпинг веб-страниц","рекурсивный скрейпинг","параллельный скрейпинг"],"ar":["حفر البيانات على الويب","حفر البيانات","استخراج البيانات","أداة حفر البيانات","حفر صفحات الويب","حفر تكراري","حفر متوازي"]}},"owner":"AstraBert","repo":"scpr","repoPath":"AstraBert/scpr","stars":0,"forks":0,"updatedAt":"2026-02-18T01:08:43.404Z","topics":[],"category":"community","skillMd":{"name":"web-scraping","description":"Scrape web pages based on a provided URL using the scpr CLI app.","bodyPreview":"When asked to scrape a web page, use the `scpr` command line interface.\n\nBasic usage (scrape a single page):\n\n```bash\nscpr --url https://example.com --output ./scraped\n```\n\nThis will scrape the page and save it as a markdown file in the `./scraped` folder.\n\n**Recursive scraping**\n\nTo scrape a page and all linked pages within the same domain:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 3\n```\n\n**Parallel scraping**\n\nSpeed up recursive scraping","body":"When asked to scrape a web page, use the `scpr` command line interface.\n\nBasic usage (scrape a single page):\n\n```bash\nscpr --url https://example.com --output ./scraped\n```\n\nThis will scrape the page and save it as a markdown file in the `./scraped` folder.\n\n**Recursive scraping**\n\nTo scrape a page and all linked pages within the same domain:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 3\n```\n\n**Parallel scraping**\n\nSpeed up recursive scraping with multiple threads:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 2 --parallel 5\n```\n\n**Additional options**\n\n- `--log` - Set logging level (info, debug, warn, error)\n- `--max` - Maximum depth of pages to follow (default: 1)\n- `--parallel` - Number of concurrent threads (default: 1)\n- `--allowed` - Allowed domains for recursive scraping (can be specified multiple times)\n\nFor more details, run:\n\n```bash\nscpr --help\n```\n\nOnce you are done with scraping, you should scan the output folder to find the content the user asked you for, here is an example flow:\n\n```bash\nscpr --url https://example.com --output ./scraped --recursive --allowed example.com --max 2\ncd ./scraped\ngrep -r \"pattern of interest\"\n```\n"},"lastSynced":"2026-02-18T03:09:55.631Z","agentAnalysis":{"suitability":{"en":"Perfect for Data Crawler Agents needing advanced web-scraping capabilities with recursive and parallel scraping","zh":"非常适合需要高级网页抓取功能的数据爬虫代理，包括递归和并行抓取","ja":"データクローラーエージェントが高度なWebスクレイピング機能を必要とする場合に最適であり、再帰的および並列スクレイピングが可能","ko":"데이터 크롤러 에이전트가 고급 웹 스크레이핑 기능을 필요로 하는 경우에 적합하며, 재귀적 및 병렬 스크레이핑이 가능","es":"Perfecto para Agentes de Crawling de Datos que necesitan capacidades avanzadas de extracción web con extracción recursiva y paralela","fr":"Parfait pour les agents de crawling de données ayant besoin de capacités avancées de scraping web avec scraping récursif et parallèle","de":"Perfekt für Data-Crawler-Agents, die erweiterte Web-Scraping-Funktionen mit rekursivem und parallelem Scraping benötigen","pt":"Perfeito para Agentes de Crawler de Dados que necessitam de capacidades avançadas de extração de dados da web com raspagem recursiva e paralela","ru":"Идеально подходит для агентов Data Crawler, которым необходимы расширенные возможности веб-скрапинга с рекурсивным и параллельным скрапингом","ar":"مثالي لعميل حشرجة البيانات الذي يحتاج إلى قدرات متقدمة لتقشير الويب مع تقشير متكرر ومتوازي"},"recommendation":{"en":"Empowers agents to scrape web pages using the `scpr` command line interface, handling recursive scraping with domain restrictions and parallel scraping for speed, all while saving output as markdown files","zh":"赋予代理使用 `scpr` 命令行界面抓取网页的能力，处理递归抓取的域限制和并行抓取以提高速度，同时将输出保存为markdown文件","ja":"`scpr` コマンドラインインターフェイスを使用してWebページをスクレイピングするエージェントを可能にし、ドメイン制限と並列スクレイピングによる再帰スクレイピングの高速化を処理し、出力をMarkdownファイルとして保存","ko":"에이전트가 `scpr` 명령줄 인터페이스를 사용하여 웹 페이지를 스크레이핑할 수 있도록 하며, 도메인 제한 및 병렬 스크레이핑을 통한 재귀적 스크레이핑을 처리하고, 출력을 마크다운 파일로 저장","es":"Habilita a los agentes a scrapear páginas web utilizando la interfaz de línea de comandos `scpr`, manejando el scraping recursivo con restricciones de dominio y el scraping paralelo para la velocidad, todo mientras se guarda la salida como archivos markdown","fr":"Permet aux agents d''extraire des pages web en utilisant l''interface de ligne de commande `scpr`, en gérant le scraping récursif avec des restrictions de domaine et le scraping parallèle pour la vitesse, tout en sauvegardant la sortie sous forme de fichiers markdown","de":"Ermöglicht es Agents, Webseiten mithilfe der Kommandozeilenoberfläche `scpr` zu scrapear, wobei das rekursive Scrapear mit Domänenbeschränkungen und das parallele Scrapear für die Geschwindigkeit gehandhabt wird, während die Ausgabe als Markdown-Dateien gespeichert wird","pt":"Habilita os agentes a extrair páginas da web usando a interface de linha de comando `scpr`, lidando com raspagem recursiva com restrições de domínio e raspagem paralela para velocidade, salvando a saída como arquivos markdown","ru":"Наделяет агентов возможностью скрапить веб-страницы с помощью интерфейса командной строки `scpr`, обрабатывая рекурсивный скрапинг с ограничениями домена и параллельный скрапинг для скорости, сохраняя вывод в виде файлов markdown","ar":"يمنح العملاء khảية تقشير صفحات الويب باستخدام واجهة سطر الأوامر `scpr` ، معالجة تقشير متكرر مع قيود النطاق و تقشير متوازي للسرعة ، وحفظ الإخراج كملفات markdown"},"useCases":{"en":["Scraping single web pages for data extraction","Recursively scraping linked pages within a domain for comprehensive data collection","Parallelizing recursive scraping to speed up large-scale data gathering"],"zh":["抓取单个网页以提取数据","递归抓取域内链接的网页以进行全面数据收集","并行化递归抓取以加速大规模数据采集"],"ja":["データ抽出のために単一のWebページをスクレイピング","ドメイン内でのリンクされたページの再帰スクレイピングによる包括的なデータ収集","大規模なデータ収集の高速化のために再帰スクレイピングを並列化"],"ko":["데이터 추출을 위해 단일 웹 페이지를 스크레이핑","도메인 내의 연결된 페이지의 재귀적 스크레이핑을 통한 포괄적인 데이터 수집","대규모 데이터 수집의 속도를 높이기 위해 재귀적 스크레이핑을 병렬화"],"es":["Scrapear páginas web individuales para la extracción de datos","Scrapear páginas enlazadas de forma recursiva dentro de un dominio para una recopilación de datos completa","Paralelizar el scraping recursivo para acelerar la recopilación de datos a gran escala"],"fr":["Extraire des pages web individuelles pour l''extraction de données","Extraire des pages liées de manière récursive à l''intérieur d''un domaine pour une collecte de données complète","Paralléliser le scraping récursif pour accélérer la collecte de données à grande échelle"],"de":["Einzelne Webseiten scrapear, um Daten zu extrahieren","Verknüpfte Seiten rekursiv innerhalb einer Domäne scrapear, um eine umfassende Datensammlung durchzuführen","Das rekursive Scrapear parallelisieren, um die Großdatensammlung zu beschleunigen"],"pt":["Extração de dados de páginas da web individuais","Raspagem recursiva de páginas vinculadas dentro de um domínio para coleta de dados abrangente","Paralelização da raspagem recursiva para acelerar a coleta de dados em grande escala"],"ru":["Извлечение данных из отдельных веб-страниц","Рекурсивный скрапинг связанных страниц внутри домена для всесторонней сбора данных","Параллелизация рекурсивного скрапинга для ускорения сбора данных в крупном масштабе"],"ar":["استخراج البيانات من صفحات الويب الفردية","تقشير متكرر للصفحات المتصلة داخل نطاق لمجموعة بيانات شاملة","تدوين تقشير متكرر لتسريع جمع البيانات على نطاق كبير"]},"limitations":{"en":["Requires CLI access","Output limited to markdown files","Recursive scraping limited by --max parameter"],"zh":["需要CLI访问","输出仅限于markdown文件","递归抓取受 --max 参数限制"],"ja":["CLIアクセスが必要","出力はMarkdownファイルのみ","再帰スクレイピングは --max パラメータによって制限される"],"ko":["CLI 액세스가 필요","출력은 마크다운 파일만","재귀적 스크레이핑은 --max 매개 변수에 의해 제한"],"es":["Requiere acceso a la interfaz de línea de comandos","La salida está limitada a archivos markdown","El scraping recursivo está limitado por el parámetro --max"],"fr":["Nécessite un accès à l''interface de ligne de commande","La sortie est limitée aux fichiers markdown","Le scraping récursif est limité par le paramètre --max"],"de":["Benötigt Zugriff auf die Kommandozeilenoberfläche","Die Ausgabe ist auf Markdown-Dateien beschränkt","Das rekursive Scrapear ist durch den --max-Parameter beschränkt"],"pt":["Requer acesso à CLI","Saída limitada a arquivos markdown","Raspagem recursiva limitada pelo parâmetro --max"],"ru":["Требуется доступ к CLI","Вывод ограничен файлами markdown","Рекурсивный скрапинг ограничен параметром --max"],"ar":["يتطلب الوصول إلى CLI","الإخراج مقيد بملفات markdown","تقشير متكرر مقيد بالمعامل --max"]},"version":3},"qualityScore":45}');
